import { Fieldset } from "../components/Fieldset";
import { useSourceFormContext } from "../SourceForm";
import * as Form from "../../Form";
import { TextInput } from "../../TextInput";
import { PlaceInput } from "../components/PlaceInput";
import { Control } from "../types";
import { useTranslation } from "react-i18next";

export const Event = ({ control }: { control: Control }) => {
  const { t } = useTranslation();
  const { scopedTKey, config } = useSourceFormContext();
  const eventTitle = Form.useFormField(control, "eventTitle");
  const eventPlace = Form.useFormField(control, "eventPlace");

  return (
    <Fieldset id="event" fields={["eventTitle", "eventPlace"]} onLegendClick={eventTitle.focus}>
      {config.fields.eventTitle && (
        <Form.Element issue={eventTitle.issue}>
          <label className="text-sm" htmlFor={eventTitle.id}>
            {t(scopedTKey("event.label"))}
          </label>
          <TextInput
            value={eventTitle.value}
            onValueChange={eventTitle.update}
            id={eventTitle.id}
            invalid={!!eventTitle.issue}
            ref={eventTitle.ref}
          />
        </Form.Element>
      )}
      {config.fields.eventPlace && (
        <Form.Element issue={eventPlace.issue}>
          <PlaceInput onValueChange={eventPlace.update} value={eventPlace.value} idPrefix="event-place" />
        </Form.Element>
      )}
    </Fieldset>
  );
};
