import {
  createContext,
  HTMLAttributes,
  LiHTMLAttributes,
  ReactNode,
  Ref,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";

type ListProps = {
  options: Array<{ id: string }>;
  children: ReactNode;
  onOptionSelect: (activeOption: string) => void;
  autoFocus?: boolean;
  selectOptionOnMouseOver?: boolean;
  elementToListenForEvents?: HTMLElement;
};

type RootContextProps = {
  onOptionMouseOver: (optionId: string) => void;
  onOptionSelect: (optionId: string) => void;
  activeOptionId?: string;
  activeOptionRef: Ref<HTMLLIElement> | undefined;
};

const RootContext = createContext<RootContextProps | null>(null);

export function Root({
  options,
  onOptionSelect,
  children,
  autoFocus,
  selectOptionOnMouseOver = true,
  elementToListenForEvents,
  ...props
}: ListProps & HTMLAttributes<HTMLUListElement>) {
  const [scrollIntoView, setScrollIntoView] = useState(false);
  const [activeOptionId, setActiveOptionId] = useState<string | undefined>(undefined);
  const activeOptionRef = useRef<HTMLLIElement | null>(null);
  const ulRef = useRef<HTMLUListElement | null>(null);

  const elementToListen = elementToListenForEvents ?? ulRef.current;

  const handleOptionSelect = useCallback(
    (selectedOption: string) => {
      onOptionSelect(selectedOption);
      setActiveOptionId(selectedOption);
    },
    [onOptionSelect],
  );

  const onActiveOptionChange = useCallback(
    (delta: number) => {
      let index = options.findIndex((option) => option.id === activeOptionId) + delta;
      if (index < 0) {
        index = options.length - 1;
      } else if (index >= options.length) {
        index = 0;
      }
      const option = options[index];
      setActiveOptionId(option?.id);
      setScrollIntoView(true);
    },
    [activeOptionId, options],
  );

  const onKeyDown = useCallback(
    async (event: KeyboardEvent) => {
      // If elementToListenForEvents is passed in, and we are listening for events on that element, we need to ignore KeyDown on an option to avoid double events.
      // example: elementToListenForEvents is document body, we don't want to execute onkeydown if a user has select element opened and tries to navigate with arrow keys between options.
      if (
        elementToListenForEvents !== ulRef.current &&
        event.target instanceof HTMLElement &&
        event.target.role === "option"
      ) {
        return;
      }
      switch (event.key) {
        case "ArrowUp":
          onActiveOptionChange(-1);
          event.preventDefault();
          break;
        case "ArrowDown":
          onActiveOptionChange(1);
          event.preventDefault();
          break;
        case "Enter":
          const index = options.findIndex((option) => option.id === activeOptionId);
          const selectedOption = options[index];
          if (selectedOption) {
            handleOptionSelect(selectedOption.id);
            event.preventDefault();
          }
          break;
      }
    },
    [elementToListenForEvents, handleOptionSelect, onActiveOptionChange, activeOptionId, options],
  );

  const handleOptionMouseOver = useCallback(
    (optionId: string) => {
      if (selectOptionOnMouseOver && activeOptionId !== optionId) {
        setActiveOptionId(optionId);
        elementToListen?.focus();
      }
    },
    [elementToListen, selectOptionOnMouseOver, activeOptionId, setActiveOptionId],
  );

  useEffect(() => {
    if (autoFocus && options[0]) {
      setActiveOptionId(options[0].id);
      elementToListen?.focus();
    }
  }, [elementToListen, autoFocus, options]);

  useEffect(() => {
    elementToListen?.addEventListener("keydown", onKeyDown);

    return () => elementToListen?.removeEventListener("keydown", onKeyDown);
  }, [elementToListen, onKeyDown]);

  useEffect(() => {
    if (scrollIntoView) {
      activeOptionRef.current?.scrollIntoView({ block: "center" });
      setScrollIntoView(false);
    }
  }, [scrollIntoView]);

  return (
    <RootContext.Provider
      value={{
        onOptionMouseOver: handleOptionMouseOver,
        activeOptionId,
        activeOptionRef,
        onOptionSelect: handleOptionSelect,
      }}
    >
      <ul
        {...props}
        ref={ulRef}
        onBlur={() => setActiveOptionId(undefined)}
        role="listbox"
        aria-activedescendant={String(activeOptionId)}
        tabIndex={0}
      >
        {children}
      </ul>
    </RootContext.Provider>
  );
}

type OptionProps = {
  id: string;
  children: ReactNode;
} & LiHTMLAttributes<HTMLLIElement>;
export function Option(props: OptionProps) {
  const { id, children } = props;
  const context = useContext(RootContext);

  const isActive = context?.activeOptionId === id;

  return (
    <li
      {...props}
      role="option"
      ref={isActive ? context?.activeOptionRef : undefined}
      onMouseOver={() => context?.onOptionMouseOver(id)}
      aria-selected={isActive}
      onClick={() => context?.onOptionSelect(id)}
    >
      {children}
    </li>
  );
}
