import { Fieldset } from "../components/Fieldset";
import { Control } from "../types";
import { useTranslation } from "react-i18next";
import { SourceType, SourceTypes } from "@cgs/types";
import { camelCase, capitalize } from "@cgs/utils";
import { Button } from "../../Button";
import { SearchableSelect } from "../../SearchableSelect";
import { AngleDown } from "../../Icon";
import * as Form from "../../Form";

export const Type = ({ control }: { control: Control }) => {
  const type = Form.useFormField(control, "type");
  const { t } = useTranslation();

  return (
    <Fieldset id="type" fields={["type"]} onLegendClick={type.focus}>
      <Form.Element issue={type.issue}>
        <SearchableSelect
          searchPlaceholder={t("universalSourceForm.sourceTypeSelect.searchPlaceholder")}
          emptyText={t("universalSourceForm.sourceTypeSelect.emptyText")}
          value={type.value}
          onValueChange={(value) => {
            type.update(value as SourceType);
          }}
          itemData={[
            {
              items: SourceTypes.map((sourceType) => ({
                label: capitalize(t(`sourceTypes.${camelCase(sourceType)}`)),
                value: sourceType,
              })),
            },
          ]}
        >
          <Button shouldFitContainer endIcon={AngleDown} justify="between" variant="outline" size="sm">
            {capitalize(t(`sourceTypes.${camelCase(type.value)}`))}
          </Button>
        </SearchableSelect>
      </Form.Element>
    </Fieldset>
  );
};
