import { Fieldset } from "../components/Fieldset";
import { YearInput } from "../components/YearInput";
import { DayInput } from "../components/DayInput";
import { MonthOrSeasonInput } from "../components/MonthOrSeasonInput";
import { isSeason } from "@cgs/utils";
import { Season } from "@cgs/types";
import { useSourceFormContext } from "../SourceForm";
import { Checkbox, CheckedState } from "../../Checkbox";
import * as Form from "../../Form";
import * as Tooltip from "../../Tooltip";
import { TextInput } from "../../TextInput";
import { Control } from "../types";
import { useTranslation } from "react-i18next";
import { Button } from "../../Button";

const Row = ({ path, form }: { path: "issued" | "originalDate"; form: Control }) => {
  const { t } = useTranslation();
  const { scopedTKey, config } = useSourceFormContext();
  const { value, update, issue } = Form.useFormField(form, path);
  const raw = Form.useFormField(form, `${path}.raw`);
  const year = Form.useFormField(form, `${path}.year`);
  const month = Form.useFormField(form, `${path}.month`);
  const season = Form.useFormField(form, `${path}.season`);
  const day = Form.useFormField(form, `${path}.day`);

  const isRaw = !!value?.raw;

  const handleYearChange = (newValue: number | undefined) => {
    update({ ...value, year: newValue });
  };
  const handleMonthSeasonChange = (newValue: number | Season | undefined) => {
    if (isSeason(newValue)) {
      update({ ...value, season: newValue, month: undefined });
    } else {
      update({ ...value, month: newValue || undefined, season: undefined });
    }
  };
  const handleDayChange = (newValue: number | undefined) => {
    update({ ...value, day: newValue });
  };
  const handleCircaChange = (newValue: CheckedState) => {
    update({ ...value, circa: !!newValue });
  };
  const handleRawChange = (newValue: string) => {
    update({ ...value, raw: newValue });
  };
  const handleUseDatePickerClick = () => {
    update({});
  };

  if (isRaw) {
    return (
      <div>
        <Form.Element issue={raw.issue}>
          <TextInput
            value={value.raw || ""}
            onValueChange={handleRawChange}
            aria-label={t(scopedTKey(`issued.${path}.raw.label`))}
            invalid={!!raw.issue}
            ref={raw.ref}
            id={raw.id}
          />
        </Form.Element>
        <Button onClick={handleUseDatePickerClick} variant="link" size="sm" color="blue">
          {t(scopedTKey("issued.useDatePicker"))}
        </Button>
      </div>
    );
  }

  return (
    <div className="flex items-start gap-4">
      <Form.Element issue={issue}>
        <div className="grid grow grid-cols-3 gap-4">
          <Form.Element issue={year.issue}>
            <YearInput
              value={year.value}
              onChange={handleYearChange}
              invalid={!!year.issue}
              placeholder={t(scopedTKey(`issued.${path}.year.placeholder`))}
              aria-label={t(scopedTKey(`issued.${path}.year.label`))}
              ref={year.ref}
              id={year.id}
            />
          </Form.Element>
          <Form.Element issue={month.issue || season.issue}>
            <MonthOrSeasonInput
              value={month.value || season.value}
              onChange={handleMonthSeasonChange}
              aria-label={t(scopedTKey(`issued.${path}.month.label`))}
              ref={month.ref}
              id={month.id}
            />
          </Form.Element>
          <Form.Element issue={day.issue}>
            <DayInput
              value={day.value}
              onChange={handleDayChange}
              month={month.value && month.value - 1}
              year={year.value}
              disabled={year.value === undefined || month.value === undefined}
              aria-label={t(scopedTKey(`issued.${path}.day.label`))}
              ref={day.ref}
            />
          </Form.Element>
        </div>
      </Form.Element>
      {config.options?.circaInIssued && (
        <label className="mt-2.5 flex grow-0 items-center space-x-2 text-sm">
          <Checkbox checked={!!value?.circa} onCheckedChange={handleCircaChange} size="sm" />
          <Tooltip.Root>
            <Tooltip.Trigger asChild>
              <span className="cursor-help underline decoration-navy-blue-9 decoration-dotted underline-offset-4">
                {t(scopedTKey("issued.circa.label"))}
              </span>
            </Tooltip.Trigger>
            <Tooltip.Content>{t(scopedTKey("issued.circa.tooltip"))}</Tooltip.Content>
          </Tooltip.Root>
        </label>
      )}
    </div>
  );
};

export const Issued = ({ control }: { control: Control }) => {
  const { t } = useTranslation();
  const { config, scopedTKey } = useSourceFormContext();
  const originalDate = Form.useFormField(control, "originalDate");
  const issuedYear = Form.useFormField(control, "issued.year");
  const status = Form.useFormField(control, "status");

  const hide = status.value === "in-press";
  const showOriginalDate = originalDate.value != null;

  const handleShowOriginalPublicationDateChange = (checked: CheckedState) => {
    if (checked) {
      originalDate.update({});
    } else {
      originalDate.update(undefined);
    }
  };

  if (hide) {
    return null;
  }

  return (
    <Fieldset id="issued" fields={["issued", "originalDate"]} onLegendClick={issuedYear.focus}>
      {config.fields.issued && (
        <fieldset className="space-y-1">
          {showOriginalDate && <div className="text-sm">{t(scopedTKey("issued.issued.legend"))}</div>}
          <Row path="issued" form={control} />
        </fieldset>
      )}
      {config.fields.originalDate && (
        <label className="flex items-center space-x-2 text-sm">
          <Checkbox
            checked={showOriginalDate}
            onCheckedChange={handleShowOriginalPublicationDateChange}
            size="sm"
          />
          <span>{t(scopedTKey("issued.originalDate.show"))}</span>
        </label>
      )}
      {showOriginalDate && (
        <fieldset className="flex flex-col gap-2">
          <div className="text-sm">{t(scopedTKey("issued.originalDate.legend"))}</div>
          <Row path="originalDate" form={control} />
        </fieldset>
      )}
    </Fieldset>
  );
};
