import { Season, Seasons, SourceDate } from "@cgs/types";
import { hasOwnProperty } from ".";

export const sourceDateToDate = (sourceDate: Partial<DeepNullable<SourceDate>>): Date | null => {
  if (!hasOwnProperty(sourceDate, "year") || typeof sourceDate.year !== "number") {
    return null;
  }
  const date = new Date();
  if (sourceDate.year < 0) {
    date.setFullYear(sourceDate.year + 1);
  } else {
    date.setFullYear(sourceDate.year);
  }
  if (typeof sourceDate.month === "number") {
    date.setMonth(sourceDate.month - 1);
  }
  if (typeof sourceDate.day === "number") {
    date.setDate(sourceDate.day);
  }
  if (date.toString() === "Invalid Date") {
    return null;
  }
  if (sourceDate.year < 0 && date.getFullYear() !== sourceDate.year + 1) {
    return null;
  }
  if (sourceDate.year >= 0 && date.getFullYear() !== sourceDate.year) {
    return null;
  }
  if (typeof sourceDate.month === "number" && date.getMonth() !== sourceDate.month - 1) {
    return null;
  }
  if (typeof sourceDate.day === "number" && date.getDate() !== sourceDate.day) {
    return null;
  }
  return date;
};
export const isSeason = (season: unknown): season is Season => {
  return Seasons.includes(season as Season);
};
