import { HistoryEntry, Message } from "../../common/types";
import { Header } from "../Popup";
import { usePopupPageContext } from "../../popup/PopupPageState";
import { CiteSection } from "../CiteSection";
import { CitationResponse, Source } from "@cgs/types";
import Edited from "../Popup/Edited";
import { AISourceBanner } from "@cgs/ui";
import { useEffect, useState } from "react";
import { sendMessage } from "../../common/messaging";
import { CitationStyle } from "@cgs/citation-engine/types";

export const ViewEntry = ({
  source,
  isEditedSource,
  citationResponse,
  onCloseViewEntry,
  onEnterSourceEditMode,
  onAddToList,
}: HistoryEntry & {
  onEnterSourceEditMode: (source?: Source) => void;
  citationResponse?: CitationResponse;
  onCloseViewEntry: () => void;
  onAddToList: () => void;
}) => {
  const [response, setResponse] = useState<CitationResponse | undefined>(undefined);

  useEffect(() => {
    setResponse(citationResponse);
  }, [citationResponse]);

  const handelCitationStyleChange = async (citationStyle: CitationStyle) => {
    if (source) {
      const response: Message = await sendMessage({
        type: "citationRequest",
        source,
        citationStyle,
        destination: "page",
      });

      if (response.type === "citationResponse") {
        setResponse(response);
      }
    }
  };

  const { locale } = usePopupPageContext();

  return (
    <div className="relative h-screen">
      <div className="sticky z-inline h-full bg-white">
        <div className="flex h-full flex-col">
          <div className="flex grow flex-col">
            <Edited onNavigateToHistory={onCloseViewEntry} isEditedSource={isEditedSource} />
            <Header
              source={source}
              showUrlActionButton
              onEnterSourceEditMode={onEnterSourceEditMode}
              onAddToList={onAddToList}
            />
            <hr className="border-navy-blue-6" />
            <div className="grow p-5">
              <CiteSection
                showCitationStyleSelect={true}
                citation={response?.citation}
                locale={locale}
                options={response?.options}
                bibEntry={response?.bibEntry}
                onCitationStyleChange={handelCitationStyleChange}
              />
            </div>
            {source?.origin === "openai" && <AISourceBanner />}
          </div>
        </div>
      </div>
    </div>
  );
};
