import { Fieldset } from "../components/Fieldset";
import { Checkbox, CheckedState } from "../../Checkbox";
import { useSourceFormContext } from "../SourceForm";
import * as Form from "../../Form";
import { TextInput } from "../../TextInput";
import { PlaceInput } from "../components/PlaceInput";
import { Control } from "../types";
import { useTranslation } from "react-i18next";

export const Publisher = ({ control }: { control: Control }) => {
  const { t } = useTranslation();
  const { scopedTKey, config } = useSourceFormContext();
  const publisher = Form.useFormField(control, "publisher");
  const publisherPlace = Form.useFormField(control, "publisherPlace");
  const showPublisherPlace = publisherPlace.value != null;

  const handleShowPublisherPlaceChange = (checked: CheckedState) => {
    publisherPlace.update(checked ? {} : undefined);
  };

  return (
    <Fieldset id="publisher" fields={["publisher", "publisherPlace"]} onLegendClick={publisher.focus}>
      {config.fields.publisher && (
        <Form.Element issue={publisher.issue}>
          {showPublisherPlace && (
            <label className="text-sm" htmlFor={publisher.id}>
              {t(scopedTKey("publisher.publisherName.label"))}
            </label>
          )}
          <TextInput
            value={publisher.value}
            onValueChange={publisher.update}
            invalid={!!publisher.issue}
            id={publisher.id}
            placeholder={t(scopedTKey("publisher.publisherName.placeholder"), "")}
            ref={publisher.ref}
            aria-label={showPublisherPlace ? undefined : t(scopedTKey("publisher.publisherName.label"))}
          />
        </Form.Element>
      )}
      {config.fields.publisherPlace && (
        <>
          <label className="flex items-center space-x-2 text-sm">
            <Checkbox checked={showPublisherPlace} onCheckedChange={handleShowPublisherPlaceChange} size="sm" />
            <span>{t(scopedTKey("publisher.publisherPlace.show"))}</span>
          </label>
          {showPublisherPlace && (
            <Form.Element issue={publisherPlace.issue}>
              <PlaceInput
                onValueChange={publisherPlace.update}
                value={publisherPlace.value}
                idPrefix={publisherPlace.id}
              />
            </Form.Element>
          )}
        </>
      )}
    </Fieldset>
  );
};
