import { ComponentPropsWithoutRef } from "react";
import { useSourceFormContext, Commendation } from "../../../";
import * as Tooltip from "../../../Tooltip";
import { useTranslation } from "react-i18next";
import { NonEmptyArray, Source } from "@cgs/types";
import { CircleQuestion } from "../../../Icon";

type FieldsetProps = ComponentPropsWithoutRef<"fieldset"> & {
  id: string;
  fields: NonEmptyArray<keyof Source["data"]>;
  onLegendClick?: () => void;
};

const commendationRanking: Record<Commendation, number> = {
  optional: 0,
  recommended: 1,
  required: 2,
};

export const Fieldset = ({ children, id, fields, onLegendClick, ...otherProps }: FieldsetProps) => {
  const { t } = useTranslation();
  const { config, scopedTKey } = useSourceFormContext();

  // Only show this fieldset if at least one of the fields is present in the config
  if (!Object.keys(config.fields).some((field) => fields.includes(field as keyof Source["data"]))) {
    return null;
  }

  const legend = t(scopedTKey(`${id}.legend`));
  const tip = t(scopedTKey(`${id}.tip`), "");

  // Determine the highest commendation level of the fields in this fieldset
  const highestCommendation = fields.reduce<Commendation>((highest, field) => {
    const commendation = config.fields[field];
    if (commendation == null) {
      return highest;
    }
    return commendationRanking[commendation] > commendationRanking[highest] ? commendation : highest;
  }, "optional");

  return (
    <fieldset
      className="lg:grid-rows-0 group grid grid-cols-1 items-stretch gap-2 lg:grid-cols-4 lg:gap-4"
      {...otherProps}
    >
      <div className="col-span-1 flex max-h-9 items-center justify-between gap-3">
        <div>
          <legend className="text-sm font-semibold" onClick={onLegendClick}>
            {legend}
          </legend>
          {["recommended", "required"].includes(highestCommendation) && (
            <div className="text-xs text-navy-blue-11">{t(scopedTKey(`fieldset.${highestCommendation}`))}</div>
          )}
        </div>
        {tip && (
          <Tooltip.Root delayDuration={0}>
            <Tooltip.Trigger className="p-2" type="button">
              <CircleQuestion className="h-3 fill-navy-blue-11 hover:fill-navy-blue-12" />
            </Tooltip.Trigger>
            <Tooltip.Content side="top">
              <Tooltip.Arrow />
              {tip}
            </Tooltip.Content>
          </Tooltip.Root>
        )}
      </div>
      <div className="space-y-4 lg:col-span-3">{children}</div>
    </fieldset>
  );
};
