import { Fieldset } from "../components/Fieldset";
import { YearInput } from "../components/YearInput";
import { Control } from "../types";
import * as Form from "../../Form";
import { useSourceFormContext } from "../SourceForm";
import { useTranslation } from "react-i18next";

export const Submitted = ({ control }: { control: Control }) => {
  const { t } = useTranslation();
  const { scopedTKey } = useSourceFormContext();
  const submitted = Form.useFormField(control, "submitted");
  const year = Form.useFormField(control, "submitted.year");

  return (
    <Fieldset id="submitted" fields={["submitted"]} onLegendClick={year.focus}>
      <Form.Element issue={submitted.issue || year.issue}>
        <YearInput
          value={year.value}
          onChange={year.update}
          invalid={!!(submitted.issue || year.issue)}
          aria-label={t(scopedTKey("submitted.year.label"))}
          ref={year.ref}
          id={year.id}
        />
      </Form.Element>
    </Fieldset>
  );
};
