export function getConfig(type: SourceType): Config {
  return {
    ...configs[type],
    fields: {
      type: "required",
      language: "optional",
      note: "optional",
      image: "optional",
      attribution: "optional",
      comment: "optional",
      ...configs[type].fields,
    },
  };
}
