import {
  AddToListMessage,
  CitationRequestMessage,
  CiteMessage,
  OtherWorksMessage,
  FetchGoogleDocMessage,
  Message,
  SummaryMessage,
  TextCaseMessage,
  AddToDocsMessage,
  AmplitudeVariantRequestMessage,
} from "./types";

type MessagesSendingResponse =
  | CiteMessage
  | AddToListMessage
  | SummaryMessage
  | CitationRequestMessage
  | OtherWorksMessage
  | TextCaseMessage
  | FetchGoogleDocMessage
  | AddToDocsMessage
  | AmplitudeVariantRequestMessage;

export async function sendMessage<T extends MessagesSendingResponse>(message: T): Promise<Message>;

export async function sendMessage<T extends Exclude<Message, MessagesSendingResponse>>(
  message: T,
): Promise<undefined>;

export async function sendMessage(message: Message): Promise<Message | undefined> {
  const response: unknown = await chrome.runtime.sendMessage(message);

  if (chrome.runtime.lastError) {
    throw chrome.runtime.lastError;
  }

  return response as Message | undefined;
}
