import * as CheckboxPrimitive from "@radix-ui/react-checkbox";
import classNames from "classnames";

export type CheckedState = CheckboxPrimitive.CheckedState;

export type CheckboxProps = {
  size?: "xs" | "sm" | "md" | "lg";
  hasError?: boolean;
} & CheckboxPrimitive.CheckboxProps;

export const Checkbox = ({
  size = "md",
  hasError = false,
  className,
  checked,
  ...otherProps
}: CheckboxProps): JSX.Element => {
  return (
    <CheckboxPrimitive.Root
      {...otherProps}
      checked={checked}
      className={classNames(
        className,
        "block rounded border border-navy-blue-7 bg-white text-white shadow-sm hover:border-navy-blue-8 disabled:opacity-40 state-checked:border-transparent state-checked:bg-blue-9 state-checked:hover:bg-blue-10 state-indeterminate:border-transparent state-indeterminate:bg-blue-9 state-indeterminate:hover:bg-blue-10",
        {
          "h-3 w-3": size === "xs",
          "h-4 w-4": size === "sm",
          "h-5 w-5": size === "md",
          "h-6 w-6": size === "lg",
          "border-2 border-red-9 hover:border-red-10 state-checked:bg-red-9 state-checked:hover:bg-red-10":
            hasError,
        },
      )}
    >
      <CheckboxPrimitive.Indicator>
        <svg width="100%" height="100%" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path
            d={checked === true ? "M4.5 9 L7.5 12 L13.5 6" : checked === "indeterminate" ? "M4.5 9 L13.5 9" : ""}
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
};
