import { camelCase, isEmptyContributor, schemas } from "@cgs/utils";
import { ValidationMode, useForm, useFormField } from "../Form";
import { getConfig } from "../..";
import { useCallback, useMemo } from "react";
import { AutociteSupportedSourceTypes, Source, SourceType } from "@cgs/types";
import { ScopedTKey } from "./types";

export function useSourceForm(defaultValues: Source["data"], validationMode: ValidationMode) {
  const form = useForm(
    schemas.sourceData,
    {
      language: "en",
      ...defaultValues,
    },
    validationMode,
  );

  /**
   * The type of source being created or edited.
   */
  const { value: type } = useFormField(form.control, "type");

  /**
   * Returns the scoped translation key for the given key.
   */
  const scopedTKey = useCallback<ScopedTKey>(
    (key) => {
      return [`universalSourceForm.overwrites.${camelCase(type)}.${key}`, `universalSourceForm.defaults.${key}`];
    },
    [type],
  );

  /**
   * The configuration for the form.
   */
  const config = useMemo(() => getConfig(type), [type]);

  /**
   * Whether or not the current source type supports autocite.
   */
  const supportsAutocite = useMemo(
    () => AutociteSupportedSourceTypes.some((supportedType) => supportedType === type),
    [type],
  );

  /**
   * Resets the form to the given values. It will clean up the data and transform it to the correct format for the source type.
   */
  const reset = useCallback(
    (values: Source["data"]) => {
      form.actions.reset(clean(values, type));
      form.actions.validateChange();
    },
    [form.actions, type],
  );

  /**
   * Changes the type of the source. It will clean up the data and transform it to the correct format for the new source type.
   */
  const changeType = useCallback(
    (newType: SourceType) => {
      form.actions.reset(clean(form.actions.getValues(), newType));
    },
    [form.actions],
  );

  /**
   * Handles the form submission. It will sanitize the data and call the given callback with the sanitized values.
   */
  const handleSubmit = useCallback(
    (onValid: (values: Source["data"]) => void) =>
      form.actions.handleSubmit((values) => {
        onValid(sanitize(values));
      }),
    [form.actions],
  );

  return {
    control: form.control,
    type,
    changeType,
    scopedTKey,
    config,
    reset,
    supportsAutocite,
    handleSubmit,
  };
}

/**
 * Filter out empty contributors, trim the url and remove null values.
 */
const sanitize = (data: Source["data"]): Source["data"] => {
  const contributors = data.contributors?.filter((contributor) => !isEmptyContributor(contributor));

  const sanatizedData = {
    ...data,
    contributors,
  };

  return JSON.parse(
    JSON.stringify(sanatizedData, (_key, value) => {
      if (typeof value === "string") {
        return value.trim();
      }

      return value === null ? undefined : value;
    }),
  );
};

/**
 * Clean up the source data by removing fields that are not relevant to the source type.
 */
function clean(sourceData: Source["data"], type: Source["data"]["type"]): Source["data"] {
  const fieldKeys = Object.keys(getConfig(type).fields);

  const data = Object.fromEntries(
    Object.entries(sourceData).filter(([key]) => fieldKeys.includes(key as keyof Source["data"])),
  );

  return {
    ...data,
    type,
  };
}
