import { HistoryEntry } from "../../common/types";
import { HistoryEntryListItem } from "./HistoryEntryListItem";
import { useMemo } from "react";

type Props = {
  date: Date;
  selectedHistories: Array<HistoryEntry["id"]>;
  onToggleHistoryEntry: (id: HistoryEntry["id"], checked: boolean) => void;
  onViewEntry: (entry: HistoryEntry) => void;
  entries: Array<HistoryEntry>;
};

const calculateDaysAgo = (zeroedDate: Date) => {
  // Take the difference between today's date and the specified date and divide by milliseconds per day.
  // Round to nearest whole number to deal with DST.
  const diff = Math.round(Math.abs((new Date().setHours(0, 0, 0, 0) - zeroedDate.getTime()) / (1000 * 3600 * 24)));
  switch (diff) {
    case 0:
      return "Today";
    case 1:
      return "Yesterday";
    default:
      return `${diff} days ago`;
  }
};
export const ListGroup = ({ date, entries, selectedHistories, onToggleHistoryEntry, onViewEntry }: Props) => {
  const dateDisplayString = useMemo(() => {
    // Create a new date object with the same date as the input date, but with the time set to midnight.
    // And only mutate the new date object, not the input date object
    const zeroedDate = new Date(date);
    zeroedDate.setHours(0, 0, 0, 0);
    const daysAgo = calculateDaysAgo(zeroedDate);
    const formattedDate = zeroedDate.toLocaleString(undefined, {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
    });
    return `${daysAgo} - ${formattedDate}`;
  }, [date]);

  return (
    <div className="flex flex-col gap-3">
      <div className="text-gray-500 text-sm">{dateDisplayString}</div>
      <hr className="border-navy-blue-6" />
      {entries.map((entry) => (
        <HistoryEntryListItem
          isSelected={selectedHistories.includes(entry.id)}
          onToggleSelect={onToggleHistoryEntry}
          onSetViewedEntry={() => onViewEntry(entry)}
          key={entry.id}
          {...entry}
        />
      ))}
    </div>
  );
};
