import { CSSProperties, KeyboardEvent } from "react";
import { BibliographyEntry as TBibliographyEntry, CopyTrigger, BibStyle, CitationStyleOptions } from "@cgs/types";
import { sanitize } from "@cgs/utils/web";
import { Tooltip } from "@cgs/ui";
import { useTranslation } from "react-i18next";

type BibliographyEntryProps = {
  bibliographyEntry: TBibliographyEntry;
  onCopyBibliography: (trigger: CopyTrigger) => void;
  citationStyleOptions: CitationStyleOptions;
};

function getInlineStyle(
  bibStyle: BibStyle,
  indentMultiplier = 1,
): CSSProperties & {
  "--margin-left": string;
  "--text-indent"?: string;
} {
  return {
    "--margin-left": `calc(${bibStyle.marginLeft} * ${indentMultiplier})`,
    "--text-indent": bibStyle.textIndent && `calc(${bibStyle.textIndent} * ${indentMultiplier})`,
  };
}

export const BibliographyEntry = ({
  bibliographyEntry,
  onCopyBibliography,
  citationStyleOptions,
}: BibliographyEntryProps) => {
  const { t } = useTranslation();

  if (bibliographyEntry.text == null) {
    return null;
  }

  const handleKeyDown = (event: KeyboardEvent) => {
    if (event.key !== "Enter" && event.key !== " " && event.key !== "Spacebar") {
      return;
    }
    onCopyBibliography("selection");
    event.preventDefault();
  };

  return (
    <Tooltip.Root>
      <Tooltip.Trigger asChild>
        <div
          className="group"
          role="button"
          onCopy={() => onCopyBibliography("selection")}
          onClick={() => onCopyBibliography("button")}
          onKeyDown={handleKeyDown}
        >
          <div className="group-hover:bg-blue-5">
            <div
              style={getInlineStyle(citationStyleOptions.bibliographyStyle)}
              className="ml-[calc(var(--margin-left)_/_2)] appearance-none break-words box-decoration-clone indent-[calc(var(--text-indent)_/_2)] text-sm transition-colors [&_span.url]:break-all"
              dangerouslySetInnerHTML={{ __html: sanitize(bibliographyEntry.text) }} // eslint-disable-line react/no-danger
            />
          </div>
        </div>
      </Tooltip.Trigger>
      <Tooltip.Content className="text-xs text-navy-blue-11">{t("general.copyToClipboard")}</Tooltip.Content>
    </Tooltip.Root>
  );
};
