import { useCallback, useEffect, useMemo } from "react";
import * as Form from "../../Form";
import * as Select from "../../Select";
import { TextInput } from "../../TextInput";
import { Control, ScopedTKey } from "../types";
import { formatMonth, getDatesInMonth, months } from "@cgs/utils";
import { Fieldset } from "../components/Fieldset";
import { Locale, SourceDate } from "@cgs/types";
import { Button } from "../../Button";
import { useTranslation } from "react-i18next";

export const Accessed = ({
  control,
  scopedTKey,
  locale,
}: {
  value?: SourceDate;
  control: Control;
  scopedTKey: ScopedTKey;
  locale: Locale;
}) => {
  const { t } = useTranslation();
  const accessed = Form.useFormField(control, "accessed");
  const raw = Form.useFormField(control, "accessed.raw");
  const year = Form.useFormField(control, "accessed.year");
  const month = Form.useFormField(control, "accessed.month");
  const day = Form.useFormField(control, "accessed.day");

  const days = useMemo(() => {
    if (year.value === undefined || month.value === undefined) {
      return [];
    }
    return getDatesInMonth(new Date(year.value, month.value - 1)).map((d) => d.getDate());
  }, [month, year]);

  const setToToday = useCallback(() => {
    const today = new Date();
    accessed.update({ year: today.getFullYear(), month: today.getMonth() + 1, day: today.getDate() });
  }, [accessed]);

  const clear = useCallback(() => {
    accessed.update(undefined);
  }, [accessed]);

  const handleChange = useCallback(
    (key: keyof SourceDate) => (update: string) => {
      const numbersOnly = update.replace(/\D/g, "");
      accessed.update({
        ...accessed.value,
        [key]: numbersOnly !== "" ? Number(numbersOnly) : undefined,
      });
    },
    [accessed],
  );

  // Clear the day field if the day is invalid for the selected month/year
  useEffect(() => {
    if (day.value && !days.includes(day.value)) {
      day.update(undefined);
    }
  }, [day, days]);

  // Clear all fields if year is not set
  useEffect(() => {
    if (!raw.value && year.value === undefined) {
      clear();
    }
  }, [clear, raw, year]);

  // In an older version it was possible to set an invalid date. During a migration, we saved invalid dates as raw strings.
  // If the date is invalid, we show the raw string instead of the date picker.
  if (raw.value) {
    return (
      <Fieldset id="accessed" fields={["accessed"]} onLegendClick={raw.focus}>
        <div className="flex items-center space-x-4">
          <Form.Element issue={raw.issue}>
            <TextInput
              value={raw.value || ""}
              onValueChange={raw.update}
              placeholder={t(scopedTKey("accessed.raw.placeholder"), { defaultValue: "" })}
              aria-label={t(scopedTKey("accessed.raw.label"))}
              invalid={!!raw.issue}
              ref={raw.ref}
              id={raw.id}
            />
          </Form.Element>
          <Button onClick={clear} variant="link" size="sm" color="blue">
            {t(scopedTKey("accessed.useDatepicker"))}
          </Button>
        </div>
      </Fieldset>
    );
  }

  return (
    <Fieldset id="accessed" fields={["accessed"]} onLegendClick={year.focus}>
      <div className="space-y-2">
        <div className="grid grow grid-cols-3 gap-4">
          <Form.Element issue={year.issue}>
            <TextInput
              value={year.value !== undefined ? String(year.value) : ""}
              onValueChange={handleChange("year")}
              aria-label={t(scopedTKey("accessed.year.label"))}
              placeholder={t(scopedTKey("accessed.year.placeholder"), { defaultValue: "" })}
              invalid={!!year.issue}
              ref={year.ref}
              id={year.id}
            />
          </Form.Element>
          <Form.Element issue={month.issue}>
            <Select.Root
              value={month.value !== undefined ? String(month.value) : ""}
              onValueChange={handleChange("month")}
              disabled={year.value === undefined}
            >
              <Select.Trigger
                shouldFitContainer
                aria-label={t("accessed.month.label")}
                ref={month.ref}
                id={month.id}
                size="sm"
              />
              <Select.Content>
                {months.map((month) => (
                  <Select.Item key={month} value={String(month + 1)}>
                    {formatMonth(month, locale)}
                  </Select.Item>
                ))}
              </Select.Content>
            </Select.Root>
          </Form.Element>
          <Form.Element issue={day.issue}>
            <Select.Root
              value={day.value !== undefined ? String(day.value) : ""}
              onValueChange={handleChange("day")}
              disabled={year.value === undefined || month.value === undefined}
            >
              <Select.Trigger
                shouldFitContainer
                aria-label={t("accessed.day.label")}
                ref={day.ref}
                id={day.id}
                size="sm"
              />
              <Select.Content>
                {days.map((day) => (
                  <Select.Item key={day} value={String(day)}>
                    {day}
                  </Select.Item>
                ))}
              </Select.Content>
            </Select.Root>
          </Form.Element>
        </div>
        <div className="flex items-center gap-2">
          <Button type="button" onClick={setToToday} variant="link" size="sm" color="blue">
            {t(scopedTKey("accessed.setToToday"))}
          </Button>
          {(year.value !== undefined || month.value !== undefined || day.value !== undefined) && (
            <Button onClick={clear} variant="link" size="sm" color="blue">
              {t(scopedTKey("accessed.clear"))}
            </Button>
          )}
        </div>
      </div>
    </Fieldset>
  );
};
