import { BibliographyEntry, Citation, CitationStyleOptions, Locale, Source } from "@cgs/types";
import { Message } from "../common/types";
import { MaintenanceModeError, NetworkError } from "../common/errors";
import { ReactNode, createContext, useContext } from "react";

type PopupPageState = {
  source?: Source;
  currentPageError?: {
    type:
      | "ContentTooLargeError"
      | "InvalidResponseError"
      | "ExtractSourceError"
      | "ContentScriptNotAvailableError";
    message?: string;
  };
  citationInfo?: {
    citation: Citation;
    bibEntry: BibliographyEntry;
    options: CitationStyleOptions;
  };
};

type PopupPageContext = PopupPageState & {
  locale: Locale;
};

const PopupPageContext = createContext<PopupPageContext | undefined>(undefined);

const PopupPageProvider = ({ children, value }: { children: ReactNode; value: PopupPageContext }) => {
  return <PopupPageContext.Provider value={value}>{children}</PopupPageContext.Provider>;
};

const usePopupPageContext = () => {
  const context = useContext(PopupPageContext);
  if (context === undefined) {
    throw new Error("usePopupPageContextContext must be used within a PopupPageProvider");
  }
  return context;
};

type EditSource = {
  type: "editSource";
  source: Source;
};
const popupPageReducer = (state: PopupPageState, action: Message | EditSource): PopupPageState => {
  switch (action.type) {
    case "editSource": {
      return { ...state, source: action.source };
    }
    case "citeResponse": {
      const { source } = action;
      return {
        ...state,
        source,
      };
    }
    case "citationResponse": {
      if (action.destination !== "page") {
        return state;
      }
      const { citation, bibEntry, options } = action;
      return {
        ...state,
        citationInfo: {
          citation,
          bibEntry,
          options,
        },
      };
    }
    case "error": {
      const { errorType, errorMessage } = action;
      switch (errorType) {
        case "ContentTooLargeError":
        case "ExtractSourceError":
        case "ContentScriptNotAvailableError":
        case "InvalidResponseError":
          return { ...state, currentPageError: { type: errorType, message: errorMessage } };
        case "MaintenanceModeError":
          throw new MaintenanceModeError();
        case "NetworkError":
          throw new NetworkError(errorMessage || "network error");
        default:
          throw new Error(errorMessage);
      }
    }
    default:
      return state;
  }
};

export { usePopupPageContext, PopupPageContext, popupPageReducer, PopupPageProvider };
