import { useCallback, useEffect, useMemo, useState } from "react";
import { HistoryEntry, Message } from "../../common/types";
import { fetchHistory, saveHistory } from "../../common/utils";
import { useSettingsContext } from "../../settings/SettingsContext";
import { sendMessage } from "../../common/messaging";
import { CitationResponse } from "@cgs/types";

export const useHistory = () => {
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [filterString, setFilterString] = useState<string>("");
  const [viewedEntry, setViewedEntry] = useState<
    (HistoryEntry & { citationResponse?: CitationResponse }) | undefined
  >(undefined);
  const [selected, setSelected] = useState<Array<HistoryEntry["id"]>>([]);
  const {
    settings: { citationStyle },
  } = useSettingsContext();
  const [isLoading, setIsLoading] = useState<boolean>(true);

  const totalHistories = history.length;

  const fetchAndSortHistory = useCallback(async () => {
    setIsLoading(true);
    const updatedHistory = await fetchHistory();
    setHistory(updatedHistory);
    setIsLoading(false);
    return updatedHistory;
  }, []);

  useEffect(() => {
    if (viewedEntry) {
      (async () => {
        const response: Message = await sendMessage({
          type: "citationRequest",
          source: viewedEntry.source,
          citationStyle: citationStyle,
          destination: "history",
        });

        if (response.type === "citationResponse" && response.destination === "history") {
          setViewedEntry({
            ...viewedEntry,
            citationResponse: {
              citation: response.citation,
              bibEntry: response.bibEntry,
              options: response.options,
            },
          });
        }
      })();
    }
    // citation style changhe is handled in callback in ViewEntry
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    void fetchAndSortHistory();
  }, [fetchAndSortHistory]);

  const dailyHistoryCollections = useMemo(
    () =>
      history
        .filter((response) => JSON.stringify(response).toLowerCase().includes(filterString.toLocaleLowerCase()))
        .reduce<Record<string, Array<HistoryEntry>>>((acc, entry) => {
          // Group by date in the browser timezone
          const asDate = new Date(entry.timestamp);
          const [dd, mm, yyyy] = [
            asDate.getDate(),
            asDate.getMonth() + 1, // Months are 0-indexed lol
            asDate.getFullYear(),
          ];
          const date = `${yyyy}-${mm}-${dd}`;
          return {
            ...acc,
            [date]: (acc[date] ?? []).concat(entry),
          };
        }, {}),
    [history, filterString],
  );

  const onToggleHistoryEntry = (id: HistoryEntry["id"], checked: boolean) => {
    if (checked) {
      setSelected((prevSelected) => [...prevSelected, id]);
    } else {
      setSelected((prevSelected) => prevSelected.filter((i) => i !== id));
    }
  };

  const onSelectAllHistoryEntries = () => setSelected(history.map((entry) => entry.id));

  const onDeselectAllHistoryEntries = () => setSelected([]);

  const onDeleteHistoryEntries = useCallback(
    async (ids: HistoryEntry["id"][]) => {
      const updatedHistory = history.filter((entry) => !ids.includes(entry.id));
      await saveHistory(updatedHistory);
      // clear session storage for removed history items
      for (const id of ids) {
        const [tab] = await chrome.tabs.query({ url: id });
        if (tab && tab.id) {
          chrome.storage.session.remove(tab.id.toString());
        }
      }
      setSelected([]);
      await fetchAndSortHistory();
    },
    [history, fetchAndSortHistory],
  );

  const onViewEntry = async (entry: HistoryEntry) => {
    setViewedEntry(entry);

    const response: Message = await sendMessage({
      type: "citationRequest",
      source: entry.source,
      citationStyle: citationStyle,
      destination: "history",
    });

    if (response && response.type === "citationResponse" && response.destination === "history") {
      setViewedEntry({
        ...entry,
        citationResponse: {
          citation: response.citation,
          bibEntry: response.bibEntry,
          options: response.options,
        },
      });
    }
  };

  const onCloseViewEntry = () => setViewedEntry(undefined);

  return {
    history,
    refetchHistory: fetchAndSortHistory,
    isLoading,
    totalHistories,
    filterString,
    onFilterStringChange: setFilterString,
    dailyHistoryCollections,
    selectedHistories: selected,
    onToggleHistoryEntry,
    onSelectAllHistoryEntries,
    onDeselectAllHistoryEntries,
    onDeleteHistoryEntries,
    onViewEntry,
    onCloseViewEntry,
    viewedEntry,
  };
};
