import { Button } from "../";
import classNames from "classnames";
import { useTranslation } from "react-i18next";

type TextCaseSuggestionProps = {
  id: string;
  suggestion: string | undefined;
  isLoading: boolean;
  onApply: (suggestion: string) => void;
};

export const TextCaseSuggestion = ({ id, suggestion, isLoading, onApply }: TextCaseSuggestionProps) => {
  const { t } = useTranslation();

  if (!suggestion) {
    return null;
  }

  return (
    <div
      className="mx-2 flex flex-col items-start gap-2 rounded-b-md border-x border-b border-navy-blue-7 p-4 text-blue-12 shadow-sm"
      role="status"
      id={id}
      aria-busy={isLoading}
    >
      <div className="inline-flex items-center space-x-1 text-xs text-navy-blue-11">
        {t("textCaseSuggestion.heading")}
      </div>
      <div className={classNames("text-sm", isLoading && "animate-pulse")}>{suggestion}</div>
      <Button onClick={() => onApply(suggestion)} size="xs" variant="solid" color="blue" disabled={isLoading}>
        {t("textCaseSuggestion.apply")}
      </Button>
    </div>
  );
};
