import React, { useEffect, useState } from "react";
import { useTranslation, withTranslation, WithTranslation } from "react-i18next";
import { Sentry } from "../../common/sentry";
import { MaintenanceModeError, NetworkError } from "../../common/errors";
import { Locale } from "@cgs/types";
import { isLocale } from "@cgs/app/src/common/validation";
import { camelCase } from "@cgs/utils";
import { Logo } from "../Logo";
import { Button } from "@cgs/ui";

interface ErrorBoundaryProps extends WithTranslation {
  children: React.ReactNode;
}

interface ErrorBoundaryState {
  error: Error | null;
}

export const contactUrlMap: Record<Locale, string> = {
  "de-DE": "https://www.scribbr.de/kontakt/",
  "en-US": "https://www.scribbr.com/contact/",
  "es-ES": "https://www.scribbr.es/contacto/",
  "fr-FR": "https://www.scribbr.fr/contact/",
  "nl-NL": "https://www.scribbr.nl/contact/",
};

export const Error = ({ error }: { error?: "MaintenanceModeError" | "NetworkError" }) => {
  const [showContactButton, setShowContactButton] = useState(false);
  const { t, i18n } = useTranslation();

  const locale: Locale = isLocale(i18n.language) ? i18n.language : "en-US";
  const errorTranslationKey = error ? camelCase(error) : error;
  const translationBaseKey = ["errorPage", errorTranslationKey].filter(Boolean).join(".");

  useEffect(() => {
    setShowContactButton(error === "NetworkError");
  }, [error]);

  return (
    <section className="flex flex-col divide-y divide-navy-blue-4 overflow-hidden bg-white text-sm text-navy-blue-12">
      <header className="flex h-[44px] items-center px-5 py-3">
        <Logo className="h-6" />
      </header>
      <div className="flex h-[556px] flex-col items-center justify-center space-y-4 px-5 py-16">
        <div className="flex flex-col items-center space-y-2 text-center">
          <h1 className="font-display text-xl font-bold">{t(`${translationBaseKey}.title`)}</h1>
          <p className="text-sm">{t(`${translationBaseKey}.description`)}</p>
        </div>
        {showContactButton && (
          <Button
            variant="solid"
            color="blue"
            size="sm"
            as="a"
            href={contactUrlMap[locale]}
            target="_blank"
            rel="noreferrer"
          >
            {t("errorPage.contactButton")}
          </Button>
        )}
      </div>
    </section>
  );
};

class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = {
    error: null,
  };

  static getDerivedStateFromError(error: Error) {
    return { error };
  }

  componentDidCatch(error: Error, _errorInfo: React.ErrorInfo) {
    Sentry.captureException(error);
  }

  render() {
    if (this.state.error) {
      const error = (() => {
        switch (this.state.error.constructor) {
          case MaintenanceModeError:
            return "MaintenanceModeError";
          case NetworkError:
            return "NetworkError";
        }
        return undefined;
      })();

      return <Error error={error} />;
    }

    return this.props.children;
  }
}

const Wrapped = withTranslation()(ErrorBoundary);

export { Wrapped as ErrorBoundary };
