import { Button, SourceForm, TextCaseFetcher, useSourceForm } from "@cgs/ui";
import { getCitationStyleOptions } from "@cgs/citation-engine/common";
import { usePopupPageContext } from "../../popup/PopupPageState";
import { useSettingsContext } from "../../settings/SettingsContext";
import { Source } from "@cgs/types";
import { useCallback, useState } from "react";
import { useTranslation } from "react-i18next";
import { useHistory } from "../History/useHistory";
import { sendMessage } from "../../common/messaging";
import { editSourceInHistory, getActiveTab } from "../../common/utils";

type EditSourceProps = {
  onSourceEdit: (source: Source) => void;
  onExitEditSourceMode: () => void;
  source: Source;
};
export const EditSource = ({ onSourceEdit, source, onExitEditSourceMode }: EditSourceProps) => {
  const { t } = useTranslation();
  const { locale } = usePopupPageContext();
  const {
    settings: { citationStyle },
  } = useSettingsContext();
  const { history } = useHistory();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const citationStyleOptions = getCitationStyleOptions(citationStyle);

  const textCaseFetcher: TextCaseFetcher = useCallback(async (input, locale, textCase) => {
    const response = await sendMessage({ type: "textCase", params: { input, locale, textCase } });
    if (response.type === "textCaseResponse") {
      return response.output;
    }
    return input;
  }, []);

  const form = useSourceForm(source.data, "onChange");

  const handleValidSubmit = async (data: Source["data"]) => {
    setIsSubmitting(true);
    const tab = await getActiveTab();

    const historySource = history.find(({ id }) => id === tab.url)?.source;
    if (!historySource) {
      throw new Error("No source found in history");
    }

    const updatedSource = { ...historySource, data };
    await editSourceInHistory(updatedSource, tab.url);
    setIsSubmitting(false);
    onSourceEdit(updatedSource);
    onExitEditSourceMode();
  };

  return (
    <div className="relative">
      <div className="sticky z-inline h-full bg-white">
        <div className="flex h-full flex-col">
          <div className="sticky top-0 z-front flex h-12 items-center justify-between gap-x-6 border-b border-b-navy-blue-6 bg-blue-3 px-6">
            <span>{t("editSource.title")}</span>
            <div className="flex gap-x-3">
              <Button size="sm" variant="outline" onClick={() => onExitEditSourceMode()}>
                {t("editSource.actions.cancel")}
              </Button>
              <Button type="submit" form="sourceForm" size="sm" variant="solid" color="blue">
                {t("editSource.actions.save")}
              </Button>
            </div>
          </div>
          <div className="p-5">
            <SourceForm
              citationStyle={citationStyle}
              textCaseFetcher={textCaseFetcher}
              id="sourceForm"
              isExistingSource
              onSubmit={form.handleSubmit(handleValidSubmit)}
              citationStyleOptions={citationStyleOptions}
              locale={locale}
              isSubmitting={isSubmitting}
              logEvent={async (event) => await sendMessage({ type: "logEvent", event })}
              {...form}
            />
          </div>
        </div>
      </div>
    </div>
  );
};
