import { Tooltip } from "../../index";
import { ReactNode } from "react";
import classNames from "classnames";

type ItemProps = {
  children: ReactNode;
  tooltip?: string;
  startIcon?: SVGComponent;
  endIcon?: SVGComponent;
  logEvent?: () => void;
  href?: string;
  onClick?: () => void;
  color?: "blue" | "orange";
};

export function Item({
  startIcon: StartIcon,
  endIcon: EndIcon,
  tooltip,
  logEvent,
  children,
  href,
  onClick,
  color = "blue",
}: ItemProps) {
  const Content = () => (
    <>
      {StartIcon && <StartIcon className="h-text fill-current" />}
      <span>{children}</span>
      {EndIcon && <EndIcon className="h-text fill-current" />}
    </>
  );

  const className = classNames(
    "inline-flex items-center space-x-2 truncate rounded-full px-4 py-2 text-sm font-semibold",
    (
      {
        blue: "bg-blue-3 hover:bg-blue-4",
        orange: "text-white bg-orange-9 hover:bg-orange-10",
      } satisfies Record<typeof color, string>
    )[color],
  );

  const wrappedElement = (() => {
    if (href) {
      return (
        <a href={href} className={className} target="_blank" rel="noreferrer" onClick={logEvent}>
          <Content />
        </a>
      );
    }
    return (
      <button
        onClick={() => {
          onClick?.();
          logEvent?.();
        }}
        className={className}
      >
        <Content />
      </button>
    );
  })();

  return (
    <Tooltip.Root>
      <Tooltip.Trigger asChild>{wrappedElement}</Tooltip.Trigger>
      {tooltip && <Tooltip.Content className="truncate">{tooltip}</Tooltip.Content>}
    </Tooltip.Root>
  );
}

export function Root({ children }: { children?: ReactNode }) {
  return <div className="flex flex-wrap gap-x-3">{children}</div>;
}
