import { Line, LineProps } from "./Line";

type LinesProps = React.HTMLAttributes<HTMLDivElement> & {
  count: number;
  LineProps?: LineProps;
};

export const Lines = ({ count, LineProps, children, ...props }: LinesProps) => {
  return (
    <div {...props}>
      {[...Array(count)].map((_, index) => (
        <Line key={index} {...LineProps} />
      ))}
    </div>
  );
};
