import { useCallback, useEffect, useReducer, useState } from "react";
import { useTranslation } from "react-i18next";
import { Locale, UserLevel, ScribbrEnv, Source } from "@cgs/types";
import { TooltipProvider } from "@radix-ui/react-tooltip";
import { useSettingsContext } from "../settings/SettingsContext";
import { Button, Icon, Tabs } from "@cgs/ui";
import * as TabsPrimitive from "@radix-ui/react-tabs";
import { PopupPageProvider, popupPageReducer } from "./PopupPageState";
import { CurrentPageTab } from "./CurrentPageTab";
import { HistoryTab } from "./HistoryTab";
import { DOMAIN, HOSTNAMES_TO_OPEN_ON_HISTORY_TAB } from "../common/constants";
import { useSessionStorageContext } from "../components/SessionStorageProvider";
import { sendMessage } from "../common/messaging";
import { useHistory } from "../components/History/useHistory";
import { EditSource } from "../components/EditSource/EditSource";
import { List, Message, privacyPolicyUrl, Summary } from "../common/types";
import { Logo } from "../components/Logo";
import { getHoustonHost, getScribbrHost } from "@cgs/utils";
import { CreateListDialog } from "../components/CreateListDialog/CreateListDialog";
import { useToast } from "../components/Toast";
import AuthDialog from "../components/AuthDialog/AuthDialog";
import { CitationStyle } from "@cgs/citation-engine/types";

export type Tab = "currentPage" | "history";

export const PopupPage = ({ env }: { env: ScribbrEnv }) => {
  // defaulting to english for MVP
  const locale: Locale = "en-US";
  const { i18n, t } = useTranslation();
  const [state, dispatch] = useReducer(popupPageReducer, {});
  const [selectedTab, setSelectedTab] = useState<Tab>("currentPage");
  const { userInfo } = useSessionStorageContext();
  const {
    settings: { citationStyle, summarizerMode },
  } = useSettingsContext();
  const historyProps = useHistory();
  const { refetchHistory, onCloseViewEntry, history, onDeleteHistoryEntries } = historyProps;
  const [sourceEditing, setSourceEditing] = useState<Source | undefined>(state?.source);
  const [isSourceEditMode, setIsSourceEditMode] = useState(false);
  const [summary, setSummary] = useState<Summary>({
    isLoading: false,
    response: {
      abstractive: undefined,
      extractive: undefined,
    },
    summaryError: undefined,
  });
  const [createListDialogOpen, setCreateListDialogOpen] = useState(false);
  const [authDialogOpen, setAuthDialogOpen] = useState(false);
  const toast = useToast();

  // on mount, fetch the user info and run the intial citation
  useEffect(() => {
    (async () => {
      await sendMessage({ type: "fetchUserInfo" });
      const response: Message = await sendMessage({ type: "cite", citationStyle });
      dispatch(response);
      await refetchHistory();
      if (response && response.type === "citeResponse") {
        const citeResponse: Message = await sendMessage({
          type: "citationRequest",
          source: response.source,
          citationStyle,
          destination: "page",
        });
        dispatch(citeResponse);
      }
    })();

    // citationStyle argument is just used for amplitude logging
    // we don't want to re-trigger this effect hook whenever it's changing
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [refetchHistory]);

  useEffect(() => {
    // additionally, set the default tab to history if applicable
    chrome.tabs.query({ active: true, currentWindow: true }, ([activeTab]) => {
      if (!activeTab || !activeTab.url) {
        return;
      }
      const hostname = new URL(activeTab.url).hostname;

      if (HOSTNAMES_TO_OPEN_ON_HISTORY_TAB.includes(hostname)) {
        setSelectedTab("history");
      }
    });
  }, []);

  const handleSummarize = useCallback(async () => {
    setSummary((prevState) => ({
      ...prevState,
      isLoading: true,
      summaryError: undefined,
    }));

    const response: Message = await sendMessage({
      type: "summarize",
      mode: summarizerMode,
      doi: state.source?.data.doi,
    });

    if (response.type === "summaryResponse") {
      setSummary((prevState) => ({
        isLoading: false,
        response: {
          ...prevState.response,
          [response.mode]: response.summary,
        },
        summaryError: undefined,
      }));
    }

    if (response.type === "summaryError") {
      setSummary({
        isLoading: false,
        response: { abstractive: undefined, extractive: undefined },
        summaryError: response.error,
      });
    }
  }, [state.source?.data.doi, summarizerMode]);

  const handelCitationStyleChange = async (citationStyle: CitationStyle) => {
    if (state.source) {
      const response: Message = await sendMessage({
        type: "citationRequest",
        source: state.source,
        citationStyle,
        destination: "page",
      });
      dispatch(response);
    }
  };

  // Fetch folders on user info change
  useEffect(() => {
    if (userInfo && userInfo.level === UserLevel.REGISTERED) {
      sendMessage({ type: "fetchFolders" });
    }
  }, [userInfo]);

  // Change language
  useEffect(() => {
    i18n.changeLanguage(locale);
  }, [locale, i18n]);

  const handleEnterSourceEditMode = (source?: Source) => {
    setIsSourceEditMode(true);
    setSourceEditing(source);
  };

  const handleExitEditSourceMode = async () => {
    setIsSourceEditMode(false);
    setSourceEditing(undefined);
    onCloseViewEntry();
  };

  const handleSourceEdit = async (source: Source) => {
    dispatch({ type: "editSource", source });
    setSelectedTab("currentPage");
    await sendMessage({ type: "logEvent", event: { name: "Citation Generator Source Edited" } });
    await refetchHistory();
  };

  const handleResetToOriginalSource = async () => {
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (!tab?.url) {
      return;
    }

    await onDeleteHistoryEntries([tab.url]);
    const response: Message = await sendMessage({ type: "cite", citationStyle });
    dispatch(response);
    await sendMessage({
      type: "logEvent",
      event: { name: "Citation Generator Reset To Original Source Clicked" },
    });
  };

  const handleTabChange = (value: string) => {
    // exit edit mode when switching tabs
    setIsSourceEditMode(false);
    // update the selected tab
    setSelectedTab(value as Tab);
  };

  const value = { ...state, locale };

  const tabs: Array<{ value: Tab; Icon: SVGComponent; logEvent: () => void }> = [
    {
      value: "currentPage",
      Icon: Icon.Window,
      logEvent: async () =>
        await sendMessage({
          type: "logEvent",
          event: { name: "Citation Generator Browser Extension History Tab Closed" },
        }),
    },
    {
      value: "history",
      Icon: Icon.ClockRotateLeft,
      logEvent: async () =>
        await sendMessage({
          type: "logEvent",
          event: { name: "Citation Generator Browser Extension History Tab Opened" },
        }),
    },
  ];

  const handleCreateListDialogOpenChange = (open: boolean) => {
    if (userInfo?.level === UserLevel.REGISTERED) {
      setCreateListDialogOpen(open);
    } else {
      setAuthDialogOpen(true);
    }
  };

  const handleAuthDialogOpenChange = (open: boolean) => {
    setAuthDialogOpen(open);
  };
  const handleAddToList = async (list?: List) => {
    if (!state.source) {
      throw new Error("No source to add to list");
    }

    const response: Message = await sendMessage({
      type: "addToList",
      source: state.source,
      list,
    });

    await sendMessage({ type: "fetchFolders" });

    if (response.type === "addSourceResponse") {
      toast(
        response.ok ? "Source added to list" : "Error adding source to list",
        response.ok ? "success" : "error",
      );
    }
  };

  return (
    <PopupPageProvider value={value}>
      <TooltipProvider>
        <AuthDialog env={env} open={authDialogOpen} onOpenChange={handleAuthDialogOpenChange} />
        <TabsPrimitive.Root
          className="flex h-full overflow-x-hidden"
          value={selectedTab}
          onValueChange={handleTabChange}
          orientation="vertical"
        >
          <div className="sticky top-0 flex flex-1 flex-col border-r border-navy-blue-6">
            <div className="flex h-12 items-center border-b border-b-navy-blue-6 px-3">
              <Logo className="h-5" />
            </div>
            <div className="flex grow flex-col gap-y-4 border-b border-b-navy-blue-6 pb-4 pt-3">
              <TabsPrimitive.List className="flex grow flex-col gap-y-1">
                {tabs.map(({ value, Icon, logEvent }) => (
                  <TabsPrimitive.Trigger
                    key={value}
                    className="group relative flex items-center gap-x-4 px-4 py-1.5 text-left text-sm font-semibold text-navy-blue-11 hover:bg-navy-blue-2 state-active:text-blue-9"
                    value={value}
                    onClick={logEvent}
                  >
                    <div className="absolute left-0 h-full w-1 rounded-r-sm group-data-[state=active]:bg-blue-9" />
                    <Icon className="w-4 fill-navy-blue-11 group-data-[state=active]:fill-blue-9" />
                    {t(`sidebar.tabs.${value}`)}
                  </TabsPrimitive.Trigger>
                ))}
              </TabsPrimitive.List>
              <div className="flex flex-col gap-y-1 px-4">
                <a
                  href={chrome.runtime.getURL("settings.html")}
                  target="_blank"
                  rel="noreferrer"
                  aria-label={t("sidebar.footer.settings")}
                  className="text-sm text-navy-blue-11 hover:text-navy-blue-12"
                >
                  {t("sidebar.footer.settings")}
                </a>
                <a
                  href={`${privacyPolicyUrl[locale]}?scr_source=citation-generator-browser-extension`}
                  target="_blank"
                  rel="noreferrer"
                  className="text-sm text-navy-blue-11 hover:text-navy-blue-12"
                >
                  {t("sidebar.footer.privacyPolicy")}
                </a>
                <a
                  href={`${getScribbrHost(DOMAIN, env)}/citation/generator`}
                  target="_blank"
                  rel="noreferrer"
                  className="text-sm text-navy-blue-11 hover:text-navy-blue-12"
                >
                  {t("sidebar.footer.citationGenerator")}
                </a>
              </div>
            </div>
            {userInfo?.level !== UserLevel.REGISTERED && (
              <div className="flex flex-col gap-y-3 rounded-lg p-4">
                <p className="text-sm font-semibold text-blue-12">{t("sidebar.auth.description")}</p>
                <div className="flex gap-x-3">
                  <Button
                    as="a"
                    variant="solid"
                    size="sm"
                    color="blue"
                    href={`${getHoustonHost(DOMAIN, env)}/account/login/?source=extension`} // TODO: create landing page, set redirectTo cookie???
                    target="_blank"
                    rel="noreferrer"
                  >
                    {t("sidebar.auth.login")}
                  </Button>
                  <Button
                    as="a"
                    size="sm"
                    href={`${getHoustonHost(DOMAIN, env)}/account/sign-up/?source=extension`} // TODO: create landing page, set redirectTo cookie???
                    target="_blank"
                    rel="noreferrer"
                  >
                    {t("sidebar.auth.signup")}
                  </Button>
                </div>
              </div>
            )}
          </div>
          <div className="flex w-[595px] flex-col">
            <CreateListDialog
              open={createListDialogOpen}
              onOpenChange={handleCreateListDialogOpenChange}
              onAddToList={handleAddToList}
              env={env}
            />
            {isSourceEditMode && sourceEditing ? (
              <EditSource
                source={sourceEditing}
                onSourceEdit={handleSourceEdit}
                onExitEditSourceMode={handleExitEditSourceMode}
              />
            ) : (
              <>
                <Tabs.Content value="currentPage" className="h-full">
                  <CurrentPageTab
                    summary={summary}
                    history={history}
                    onSummarize={handleSummarize}
                    onEnterSourceEditMode={handleEnterSourceEditMode}
                    onResetToOriginalSource={handleResetToOriginalSource}
                    onAddToList={() => handleCreateListDialogOpenChange(true)}
                    onCitationStyleChange={handelCitationStyleChange}
                  />
                </Tabs.Content>
                <Tabs.Content value="history" className="h-full">
                  <HistoryTab
                    {...historyProps}
                    onEnterSourceEditMode={handleEnterSourceEditMode}
                    onAddToList={() => handleCreateListDialogOpenChange(true)}
                  />
                </Tabs.Content>
              </>
            )}
          </div>
        </TabsPrimitive.Root>
      </TooltipProvider>
    </PopupPageProvider>
  );
};
