import { ComponentPropsWithoutRef, forwardRef, useCallback } from "react";
import classNames from "classnames";

type InputAttributes = ComponentPropsWithoutRef<"input">;

export type TextInputProps = InputAttributes & {
  type?: "text" | "number" | "tel" | "password" | "email" | "search";
  invalid?: boolean;
  onValueChange?: (value: string) => void;
};

export const TextInput = forwardRef<HTMLInputElement, TextInputProps>(function TextInput(
  { invalid, className, onChange, onValueChange, ...otherProps },
  ref,
) {
  const inputClassName = classNames(
    "w-full block shadow-sm rounded-md border bg-white disabled:opacity-40 placeholder:text-navy-blue-8 focus:outline-2 appearance-none h-9 px-3 text-sm",
    invalid
      ? "border-red-9 hover:outline-red-10 focus:outline-red-9 focus:border-red-9"
      : "border-navy-blue-7 hover:border-navy-blue-8 focus:outline-blue-9 focus:border-blue-9",
    className,
  );

  const handleChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      onValueChange?.(event.currentTarget.value);
      onChange?.(event);
    },
    [onValueChange, onChange],
  );

  return (
    <input {...(otherProps as InputAttributes)} className={inputClassName} ref={ref} onChange={handleChange} />
  );
});
