import { forwardRef } from "react";
import { formatMonth, months, isSeason } from "@cgs/utils";
import { Season, Seasons } from "@cgs/types";
import * as Select from "../../../Select";
import { useSourceFormContext } from "../../SourceForm";
import { useTranslation } from "react-i18next";

type MonthOrSeasonProps = Omit<Select.RootProps, "value" | "onValueChange"> &
  Omit<Select.TriggerProps, "onChange" | "value"> & {
    /** A number representing a month, or a Season represeting a season. Months are zero-based. */
    value?: number | Season | null;
    /** Event handler called when the value changes. */
    onChange: (value: number | Season | undefined) => void;
    /** Whether the input is disabled or not. */
    disabled?: boolean;
  };

export const MonthOrSeasonInput = forwardRef<HTMLButtonElement, MonthOrSeasonProps>(function MonthOrSeasonProps(
  { defaultValue, value, onChange, disabled, ...otherProps },
  ref,
) {
  const { t } = useTranslation();
  const { scopedTKey } = useSourceFormContext();
  const { locale } = useSourceFormContext();

  const handleValueChange = (value: string) => {
    if (!onChange) {
      return;
    }
    if (value === "-") {
      return onChange(undefined);
    }
    if (isSeason(value)) {
      return onChange(value);
    }
    onChange(Number(value));
  };

  return (
    <Select.Root value={value !== undefined ? String(value) : "-"} onValueChange={handleValueChange}>
      <Select.Trigger disabled={disabled} {...otherProps} ref={ref} shouldFitContainer />
      <Select.Content>
        <Select.Item value="-">{t(scopedTKey("monthOrSeasonInput.options.none"))}</Select.Item>
        <Select.Group>
          <Select.Label>{t(scopedTKey("monthOrSeasonInput.groups.months"))}</Select.Label>
          {months.map((month) => (
            <Select.Item data-testid="select-option" key={month} value={String(month + 1)}>
              {formatMonth(month, locale)}
            </Select.Item>
          ))}
        </Select.Group>
        <Select.Group>
          <Select.Label>{t(scopedTKey("monthOrSeasonInput.groups.seasons"))}</Select.Label>
          {Seasons.map((season) => (
            <Select.Item key={season} value={season}>
              {t(scopedTKey(`monthOrSeasonInput.options.${season}`))}
            </Select.Item>
          ))}
        </Select.Group>
      </Select.Content>
    </Select.Root>
  );
});
