import { forwardRef, useCallback, useEffect, useMemo, useState } from "react";
import { AngleDown, Trash, GripVertical, User, Building } from "../../Icon";
import * as Form from "../../Form";
import * as Select from "../../Select";
import { TextInput } from "../../TextInput";
import classNames from "classnames";
import { SourceContributor, SourceContributorRoles, CitationStyleOptions } from "@cgs/types";
import { Control, ScopedTKey } from "../types";
import { Fieldset } from "../components/Fieldset";
import { Button } from "../../Button";
import * as SegmentedButton from "../../SegmentedButton";
import { useSortable, DndContext, DropEvent } from "../../Dnd";
import { ZodIssue } from "zod";
import { newID, UnreachableCaseError, camelCase } from "@cgs/utils";
import { useTranslation } from "react-i18next";
import { useSourceFormContext } from "../SourceForm";

type Roles = {
  recommended: Array<{ role: SourceContributor["role"]; text: string }>;
  other: Array<{ role: SourceContributor["role"]; text: string }>;
};

const InputRow = forwardRef<
  HTMLInputElement,
  {
    value?: string;
    onValueChange: (value: string) => void;
    scopedTKey: ScopedTKey;
    id: string;
    isRecommended?: boolean;
    label: string;
    issue?: ZodIssue;
  }
>(function InputRow({ value, onValueChange, scopedTKey, id, isRecommended, label, issue }, ref) {
  const { t } = useTranslation();

  return (
    <>
      <div>
        <label htmlFor={id} className="text-sm">
          {label}
        </label>
        {isRecommended && <div className="text-xs text-navy-blue-11">{t(scopedTKey("fieldset.recommended"))}</div>}
      </div>
      <Form.Element issue={issue}>
        <TextInput id={id} value={value || ""} onValueChange={onValueChange} invalid={!!issue} ref={ref} />
      </Form.Element>
    </>
  );
});

const ContributorsItem = ({
  id,
  index,
  roles,
  givenName,
  scopedTKey,
  defaultIsExpanded = false,
  control,
  isDraggable,
  isFirst,
  isLast,
  onRemove,
}: {
  id: ID;
  index: number;
  roles: Roles;
  givenName: CitationStyleOptions["givenName"];
  scopedTKey: ScopedTKey;
  defaultIsExpanded: boolean;
  control: Control;
  isDraggable: boolean;
  isFirst: boolean;
  isLast: boolean;
  onRemove: () => void;
}) => {
  const { t } = useTranslation();

  const [isExpanded, setIsExpanded] = useState(defaultIsExpanded);
  const { isDragging, attributes, setNodeRef } = useSortable({ id });

  const type = Form.useFormField(control, `contributors.${index}.type`);
  const role = Form.useFormField(control, `contributors.${index}.role`);
  const organizationName = Form.useFormField(control, `contributors.${index}.name`);
  const title = Form.useFormField(control, `contributors.${index}.title`);
  const initials = Form.useFormField(control, `contributors.${index}.initials`);
  const given = Form.useFormField(control, `contributors.${index}.given`);
  const particle = Form.useFormField(control, `contributors.${index}.particle`);
  const family = Form.useFormField(control, `contributors.${index}.family`);
  const suffix = Form.useFormField(control, `contributors.${index}.suffix`);
  const screenName = Form.useFormField(control, `contributors.${index}.screenName`);

  const previewName = useMemo(() => {
    switch (type.value) {
      case "organization":
        if (organizationName.value && screenName.value) {
          return `${organizationName.value} (${screenName.value})`;
        }
        return organizationName.value || screenName.value;
      case "person":
        const givenName =
          initials.value && given.value ? `${given.value} (${initials.value})` : given.value || initials.value;
        const name = [title.value, givenName, particle.value, family.value, suffix.value]
          .filter(Boolean)
          .join(" ");
        if (screenName.value) {
          return name ? `${name} (${screenName.value})` : screenName.value;
        }
        return name;
      default:
        throw new UnreachableCaseError(type.value);
    }
  }, [
    type.value,
    organizationName.value,
    screenName.value,
    initials.value,
    given.value,
    title.value,
    particle.value,
    family.value,
    suffix.value,
  ]);

  useEffect(() => {
    if (isExpanded) {
      switch (type.value) {
        case "organization":
          organizationName.focus();
          break;
        case "person":
          title.focus();
          break;
        default:
          throw new UnreachableCaseError(type.value);
      }
    }
  }, [isExpanded, organizationName, title, type.value]);

  useEffect(() => {
    if (isDragging) {
      setIsExpanded(false);
    }
  }, [isDragging]);

  const accordionHeaderId = `${id}-header`;
  const accordionPanelId = `${id}-panel`;

  const issue =
    type.issue ||
    role.issue ||
    organizationName.issue ||
    title.issue ||
    initials.issue ||
    given.issue ||
    particle.issue ||
    family.issue ||
    suffix.issue ||
    screenName.issue;

  return (
    <li
      {...(isDraggable ? attributes : undefined)}
      // this is required for the Dnd to work
      data-id={id}
      ref={setNodeRef}
      className={classNames(
        "group/contributor relative -mt-px border border-navy-blue-6 transition-colors first:mt-0 hover:z-inline",
        isExpanded ? "z-inline border-navy-blue-7 bg-white" : "",
        issue ? "border-l-red-11" : "hover:border-navy-blue-8",
        isFirst && "rounded-t-md",
        isLast && "rounded-b-md",
      )}
      aria-label={previewName}
    >
      {issue && <div className="absolute bottom-0 left-0 top-0 w-px bg-red-11" />}
      <div
        className={classNames(
          "flex h-9 items-stretch transition-[height] duration-300",
          isFirst && "rounded-t-md",
          isLast && "rounded-b-md",
        )}
      >
        <div className="w-9">
          {isDraggable && (
            <button
              className="grid h-full w-full shrink-0 cursor-move touch-none place-items-center text-navy-blue-11 opacity-0 hover:text-navy-blue-12 group-focus-within/contributor:opacity-100 group-hover/contributor:opacity-100"
              type="button"
              aria-label={t(scopedTKey("contributors.reorder"))}
            >
              <GripVertical className="h-3 fill-current" />
            </button>
          )}
        </div>
        <button
          type="button"
          className="flex grow items-center space-x-3 overflow-hidden"
          aria-label={t(scopedTKey("contributors.edit"), { name: previewName || "" })}
          onClick={() => setIsExpanded(!isExpanded)}
          aria-expanded={isExpanded ? "true" : "false"}
          aria-controls={accordionPanelId}
          id={accordionHeaderId}
        >
          <div className="min-w-0 grow space-x-3 truncate text-left text-sm">{previewName}</div>
          <AngleDown
            className={classNames("h-3 shrink-0 transform fill-navy-blue-11 transition-transform", {
              "rotate-180": isExpanded,
            })}
          />
        </button>
        <button
          className="grid w-9 shrink-0 touch-none place-items-center text-navy-blue-11 opacity-0 hover:text-navy-blue-12 group-focus-within/contributor:opacity-100 group-hover/contributor:opacity-100"
          type="button"
          onClick={onRemove}
          aria-label={t(scopedTKey("contributors.remove"))}
        >
          <Trash className="h-3 fill-current" />
        </button>
      </div>
      {isExpanded && (
        <>
          <hr className="ml-9 mr-5" />
          <div
            className="grid grid-cols-[max-content_1fr] items-center gap-3 pb-5 pl-9 pr-5 pt-3"
            role="region"
            id={accordionPanelId}
            aria-labelledby={accordionHeaderId}
          >
            <div className="col-start-2">
              <Form.Element issue={type.issue}>
                <SegmentedButton.Root
                  value={type.value}
                  onValueChange={type.update}
                  size="sm"
                  aria-label={t("contributors.type.label")}
                  className="col-start-2"
                  id={type.id}
                >
                  <SegmentedButton.Item value="person">
                    {t(scopedTKey("contributors.type.options.person"))}
                  </SegmentedButton.Item>
                  <SegmentedButton.Item value="organization">
                    {t(scopedTKey("contributors.type.options.organization"))}
                  </SegmentedButton.Item>
                </SegmentedButton.Root>
              </Form.Element>
            </div>
            {type.value === "organization" && (
              <InputRow
                scopedTKey={scopedTKey}
                id={organizationName.id}
                label={t(scopedTKey("contributors.name.label"))}
                value={organizationName.value}
                onValueChange={organizationName.update}
                issue={organizationName.issue}
                ref={organizationName.ref}
                isRecommended
              />
            )}
            {type.value === "person" && (
              <>
                <InputRow
                  scopedTKey={scopedTKey}
                  id={title.id}
                  label={t(scopedTKey("contributors.title.label"))}
                  value={title.value}
                  onValueChange={title.update}
                  issue={title.issue}
                  ref={title.ref}
                />
                <InputRow
                  scopedTKey={scopedTKey}
                  id={initials.id}
                  label={t(scopedTKey("contributors.initials.label"))}
                  isRecommended={givenName === "initials"}
                  value={initials.value}
                  onValueChange={initials.update}
                  issue={initials.issue}
                  ref={initials.ref}
                />
                <InputRow
                  scopedTKey={scopedTKey}
                  id={given.id}
                  label={t(scopedTKey("contributors.given.label"))}
                  isRecommended={givenName === "full"}
                  value={given.value}
                  onValueChange={given.update}
                  issue={given.issue}
                  ref={given.ref}
                />
                <InputRow
                  scopedTKey={scopedTKey}
                  id={particle.id}
                  label={t(scopedTKey("contributors.particle.label"))}
                  value={particle.value}
                  onValueChange={particle.update}
                  issue={particle.issue}
                  ref={particle.ref}
                />
                <InputRow
                  scopedTKey={scopedTKey}
                  id={family.id}
                  label={t(scopedTKey("contributors.family.label"))}
                  value={family.value}
                  onValueChange={family.update}
                  issue={family.issue}
                  ref={family.ref}
                  isRecommended
                />
                <InputRow
                  scopedTKey={scopedTKey}
                  id={suffix.id}
                  label={t(scopedTKey("contributors.suffix.label"))}
                  value={suffix.value}
                  onValueChange={suffix.update}
                  issue={suffix.issue}
                  ref={suffix.ref}
                />
              </>
            )}
            <InputRow
              scopedTKey={scopedTKey}
              id={screenName.id}
              label={t(scopedTKey("contributors.screenName.label"))}
              value={screenName.value}
              onValueChange={screenName.update}
              ref={screenName.ref}
            />
            <div>
              <label htmlFor={role.id} className="text-sm">
                {t(scopedTKey("contributors.role.label"))}
              </label>
              <div className="text-xs text-navy-blue-11">{t(scopedTKey("fieldset.recommended"))}</div>
            </div>
            <Form.Element issue={role.issue}>
              <Select.Root value={role.value} onValueChange={role.update}>
                <Select.Trigger id={role.id} ref={role.ref} size="sm" />
                <Select.Content>
                  <Select.Group>
                    <Select.Label>{t(scopedTKey("contributors.role.groups.recommended"))}</Select.Label>
                    {roles.recommended.map(({ role, text }) => (
                      <Select.Item key={role} value={role}>
                        {text}
                      </Select.Item>
                    ))}
                  </Select.Group>
                  <Select.Group>
                    <Select.Label>{t(scopedTKey("contributors.role.groups.other"))}</Select.Label>
                    {roles.other.map(({ role, text }) => (
                      <Select.Item key={role} value={role}>
                        {text}
                      </Select.Item>
                    ))}
                  </Select.Group>
                </Select.Content>
              </Select.Root>
            </Form.Element>
          </div>
        </>
      )}
    </li>
  );
};

export const Contributors = ({
  control,
  scopedTKey,
  givenName,
}: {
  control: Control;
  scopedTKey: ScopedTKey;
  givenName: CitationStyleOptions["givenName"];
}) => {
  const { t } = useTranslation();
  const { fields, append, move } = Form.useFormFieldArray(control, "contributors");
  const { config } = useSourceFormContext();
  const lastContributor = Form.useFormField(control, `contributors.${fields.length - 1}`);
  const [elementDraggingId, setElementDraggingId] = useState<ID>();

  const roles = useMemo<Roles>(() => {
    const recommendedRoles = config.options?.recommendedRoles || [];
    const recommended = recommendedRoles.map((role) => {
      return {
        role,
        text: t(scopedTKey(`contributors.role.options.${camelCase(role)}`)),
      };
    });
    const other = SourceContributorRoles.filter((role) => !recommendedRoles.includes(role)).map((role) => {
      return {
        role,
        text: t(scopedTKey(`contributors.role.options.${camelCase(role)}`)),
      };
    });
    return {
      recommended: recommended.sort((a, b) => a.text.localeCompare(b.text)),
      other: other.sort((a, b) => a.text.localeCompare(b.text)),
    };
  }, [config.options?.recommendedRoles, scopedTKey, t]);

  const defaultRole: SourceContributor["role"] =
    lastContributor.value?.role || config.options?.recommendedRoles?.[0] || "author";

  const handleDrop = useCallback(
    ({ activeId, overId }: DropEvent) => {
      if (activeId !== overId) {
        const oldIndex = fields.findIndex((field) => field.id === activeId);
        const newIndex = fields.findIndex((field) => field.id === overId);
        move(oldIndex, newIndex);
      }
    },
    [fields, move],
  );

  const handleDragStart = (id: ID) => {
    setElementDraggingId(id);
  };

  const add = useCallback(
    (type: SourceContributor["type"]) => {
      const id = newID();
      append(id, {
        type,
        role: defaultRole,
      });
      setLastAddedID(id);
    },
    [append, defaultRole],
  );

  const [lastAddedId, setLastAddedID] = useState<ID | null>(null);

  return (
    <Fieldset id="contributors" fields={["contributors"]}>
      <div>
        <ol className="isolate mt-0 rounded-md shadow-sm">
          <DndContext.Provider
            value={{ onDrop: handleDrop, onDragStart: handleDragStart, data: fields, elementDraggingId }}
          >
            {fields.map((field, index) => (
              <ContributorsItem
                key={field.id}
                index={index}
                id={field.id}
                roles={roles}
                scopedTKey={scopedTKey}
                onRemove={field.remove}
                givenName={givenName}
                defaultIsExpanded={field.id === lastAddedId}
                control={control}
                isDraggable={fields.length > 1}
                isFirst={index === 0}
                isLast={index === fields.length - 1}
              />
            ))}
          </DndContext.Provider>
        </ol>
        <div className={classNames("flex items-center space-x-4", { "mt-4": fields.length > 0 })}>
          <Button onClick={() => add("person")} startIcon={User} size="sm">
            {t(scopedTKey("contributors.addPerson"))}
          </Button>
          <Button onClick={() => add("organization")} startIcon={Building} size="sm">
            {t(scopedTKey("contributors.addOrganization"))}
          </Button>
        </div>
      </div>
    </Fieldset>
  );
};
