import { Tabs } from "@cgs/ui";
import { useTranslation } from "react-i18next";
import { SummarySection } from "../SummarySection";
import { ReactNode, useMemo, useState } from "react";
import { Summary, Tab, tabs } from "../../common/types";
import { useSettingsContext } from "../../settings/SettingsContext";
import { BibliographyEntry, Citation, CitationStyleOptions, Locale, ScribbrEnv, Source } from "@cgs/types";
import { CiteSection } from "../CiteSection";
import { OtherWorksSection } from "../OtherWorksSection/OtherWorksSection";
import { CitationStyle } from "@cgs/citation-engine/types";

const isTab = (value: string): value is Tab => tabs.includes(value as Tab);

type Section = {
  name: Tab;
  content: ReactNode;
};
export const TabSection = ({
  bibEntry,
  citation,
  options,
  source,
  locale,
  env,
  summary,
  onSummarize,
  onCitationStyleChange,
}: {
  bibEntry?: BibliographyEntry;
  citation?: Citation;
  options?: CitationStyleOptions;
  source?: Source;
  locale: Locale;
  env: ScribbrEnv;
  summary: Summary;
  onSummarize: () => void;
  onCitationStyleChange: (style: CitationStyle) => void;
}) => {
  const { settings, saveSettings } = useSettingsContext();
  const { t } = useTranslation();
  const [selectedTab, setSelectedTab] = useState<Tab>(settings.selectedTab);

  const handleTabChange = (value: string) => {
    if (!isTab(value)) {
      throw new Error(`Invalid tab: ${value}`);
    }
    setSelectedTab(value);
    saveSettings({ selectedTab: value });
  };

  const sections = useMemo(() => {
    const sections: Section[] = [
      {
        name: tabs[0],
        content: (
          <CiteSection
            locale={locale}
            bibEntry={bibEntry}
            citation={citation}
            options={options}
            onCitationStyleChange={onCitationStyleChange}
          />
        ),
      },
      {
        name: tabs[1],
        content: (
          <SummarySection
            env={env}
            citation={citation}
            citationStyle={settings.citationStyle}
            source={source}
            summary={summary}
            onSummarize={onSummarize}
          />
        ),
      },
    ];

    if (source?.data.doi) {
      sections.push({
        name: tabs[2],
        content: <OtherWorksSection doi={source.data.doi} />,
      });
    }

    return sections;
  }, [bibEntry, citation, locale, options, settings, source, env, summary, onSummarize, onCitationStyleChange]);

  return (
    <Tabs.Root value={selectedTab} onValueChange={handleTabChange} className="flex grow flex-col">
      <Tabs.List bordered alignOffset={20} className="shrink-0">
        {sections.map(({ name }) => (
          <Tabs.Trigger
            key={name}
            value={name}
            onClick={async () =>
              await chrome.runtime.sendMessage({
                type: "logEvent",
                event: {
                  name: "Citation Generator Source Tab Clicked",
                  data: {
                    tab: name,
                  },
                },
              })
            }
          >
            {t(`homePage.tabs.${name}`)}
          </Tabs.Trigger>
        ))}
      </Tabs.List>
      <div>
        {sections.map(({ name, content }) => (
          <Tabs.Content key={name} value={name} className="space-y-5 p-5">
            {content}
          </Tabs.Content>
        ))}
      </div>
    </Tabs.Root>
  );
};
