import { createContext, useCallback, useContext, useEffect, useState } from "react";
import { Settings, defaultSettings } from "../common/types";

export type SettingsContextProps = {
  settings: Settings;
  saveSettings: (
    settings: Partial<Settings> | ((prevState: Settings) => Partial<Settings>),
    cb?: (settings: Settings) => void,
  ) => void;
};

const SettingsContext = createContext<SettingsContextProps>({
  settings: defaultSettings,
  saveSettings: () => {},
});

export function useSettingsContext() {
  const context = useContext(SettingsContext);
  if (context == null) {
    throw new Error("useSettingsContext must be used within a SettingsContext.Provider");
  }
  return context;
}

export const SettingsProvider = ({ fallback, children }: { fallback?: Settings; children: React.ReactNode }) => {
  const [settings, setSettings] = useState<Settings | undefined>(fallback);

  useEffect(() => {
    chrome.storage.local.get("settings", ({ settings: storedSettings }) => {
      setSettings({ ...defaultSettings, ...storedSettings });
    });
    const storageOnChanged = (changes: { [key: string]: chrome.storage.StorageChange }) => {
      const newSettings = changes.settings?.newValue;
      if (newSettings) {
        setSettings(newSettings);
      }
    };
    chrome.storage.onChanged.addListener(storageOnChanged);
    return () => chrome.storage.onChanged.removeListener(storageOnChanged);
  }, []);

  const saveSettings: SettingsContextProps["saveSettings"] = useCallback(
    async (updatedSettings, cb) => {
      if (!settings) {
        return;
      }

      const newSettings: Settings = {
        ...settings,
        ...(typeof updatedSettings === "function" ? updatedSettings(settings) : updatedSettings),
      };
      await chrome.storage.local.set({ settings: newSettings });
      setSettings(newSettings);
      cb?.(settings);
    },
    [settings],
  );

  if (!settings) {
    // do not render children when settings are not loaded yet
    return null;
  }

  return <SettingsContext.Provider value={{ settings, saveSettings }}>{children}</SettingsContext.Provider>;
};
