import { KeyboardEvent } from "react";
import { useTranslation } from "react-i18next";
import { Citation, CopyTrigger } from "@cgs/types";
import { isUnverifiedCitationStyle } from "@cgs/citation-engine/common";
import { sanitize } from "@cgs/utils/web";
import { Tooltip } from "@cgs/ui";
import { writeToClipboard, citationToClipboardItem } from "@cgs/utils/common";
import { useToast } from "../Toast";
import { useSettingsContext } from "../../settings/SettingsContext";
import { sendMessage } from "../../common/messaging";

const CitationExample = ({ citation, onCopy }: { citation: string; onCopy?: (success: boolean) => void }) => {
  const { settings } = useSettingsContext();

  const toast = useToast();
  const { t } = useTranslation();
  const copyCitation = async (trigger: CopyTrigger) => {
    await writeToClipboard(citationToClipboardItem(citation));
    onCopy?.(true);
    toast(t("clipboard.copied"));
    await sendMessage({
      type: "logEvent",
      event: {
        name: "Citation Generator Citation Copied",
        data: {
          citation_style: settings.citationStyle[0],
          citation_style_variation: settings.citationStyle[1],
          location: "CitationExamples",
          trigger,
        },
      },
    });
  };
  const handleKeyDown = (event: KeyboardEvent) => {
    if (event.key !== "Enter" && event.key !== " " && event.key !== "Spacebar") {
      return;
    }
    handleCopyToClipboard("selection");
    event.preventDefault();
  };

  const handleCopyToClipboard = (trigger: CopyTrigger) => {
    copyCitation(trigger);
  };

  return (
    <Tooltip.Root>
      <Tooltip.Trigger asChild>
        <div
          role="button"
          tabIndex={0}
          className="group/button"
          onClick={() => handleCopyToClipboard("button")}
          onKeyDown={handleKeyDown}
          onCopy={async () =>
            await sendMessage({
              type: "logEvent",
              event: {
                name: "Citation Generator Citation Copied",
                data: {
                  citation_style: settings.citationStyle[0],
                  citation_style_variation: settings.citationStyle[1],
                  location: "CitationExamples",
                  trigger: "selection",
                },
              },
            })
          }
        >
          <span
            className="inline appearance-none break-words box-decoration-clone text-left text-sm transition-colors group-hover/button:bg-blue-5 [&_span.url]:break-all [&_span]:contents"
            dangerouslySetInnerHTML={{ __html: sanitize(citation) }} // eslint-disable-line react/no-danger
          />
        </div>
      </Tooltip.Trigger>
      <Tooltip.Content className="text-xs text-navy-blue-11">{t("general.copyToClipboard")}</Tooltip.Content>
    </Tooltip.Root>
  );
};

export const CitationExamples = ({
  citation,
  onCopy,
}: {
  citation: Citation;
  onCopy?: (success: boolean) => void;
}) => {
  const { settings } = useSettingsContext();

  return (
    <table>
      <tbody>
        {citation
          .filter((example, index) => {
            if (isUnverifiedCitationStyle(settings.citationStyle)) {
              // filter subsequent if same as first for unverified styles
              return index === 0 || example.citation !== citation[0].citation;
            } else {
              return true;
            }
          })
          .map((example) => (
            <tr key={example.citation} className="group">
              <th className="p-0 pt-1 text-left align-top font-normal group-first:pt-0">
                {example.description !== undefined ? (
                  <Tooltip.Root>
                    <Tooltip.Trigger className="inline whitespace-nowrap text-left text-sm font-semibold text-navy-blue-11 underline decoration-dotted">
                      {example.title}
                    </Tooltip.Trigger>
                    <Tooltip.Content
                      className="max-w-xs bg-navy-blue-12 fill-navy-blue-12 px-3 py-2 text-sm text-white"
                      side="top"
                    >
                      {example.description}
                    </Tooltip.Content>
                  </Tooltip.Root>
                ) : (
                  <span className="inline whitespace-nowrap text-left text-sm font-semibold text-navy-blue-11">
                    {example.title}
                  </span>
                )}
              </th>
              <td className="p-0 pl-3 pt-1 align-top group-first:pt-0">
                <CitationExample citation={example.citation} onCopy={onCopy} />
              </td>
            </tr>
          ))}
      </tbody>
    </table>
  );
};
