import { produce } from "immer";
import { useEffect, useId, useRef } from "react";
import { ZodIssue, ZodType, TypeOf, ZodIssueCode } from "zod";
import { createWithEqualityFn } from "zustand/traditional";
import { shallow } from "zustand/shallow";
import _get from "lodash/get";
import _set from "lodash/set";
import { newID } from "@cgs/utils";
import {
  ArrayKey,
  ArrayPathImpl,
  ExtractState,
  Focusable,
  IsTuple,
  Path,
  PathValue,
  State,
  TupleKeys,
  Unpacked,
  ValidationMode,
} from "./types";

export const useForm = <S extends ZodType, V extends TypeOf<S>>(
  schema: S,
  initialValues: V,
  validationMode: ValidationMode = "onSubmit",
) => {
  const id = useId();
  const refs = useRef<Partial<Record<Path<V>, Focusable | null>>>({});
  const control = useRef(
    createWithEqualityFn<State<S>>(
      (set, get) => ({
        id,
        values: initialValues,
        issues: [],
        isSubmitted: false,
        schema,
        actions: {
          update: (path, value) => {
            set(
              produce((draft) => {
                _set(draft.values, path, value);
              }),
            );
            get().actions.validateChange();
          },
          appendToArray: (path, value) => {
            set(
              produce((draft) => {
                const array = _get(draft.values, path);
                if (Array.isArray(array)) {
                  array.push(value);
                } else {
                  _set(draft.values, path, [value]);
                }
              }),
            );
            get().actions.validateChange();
          },
          removeFromArray: (path, index) => {
            set(
              produce((draft) => {
                const array = _get(draft.values, path);
                if (!Array.isArray(array)) {
                  throw new Error(`Path is not an array: ${path}`);
                }
                array.splice(index, 1);
              }),
            );
            get().actions.validateChange();
          },
          moveInArray: (path, from, to) => {
            set(
              produce((draft) => {
                const array = _get(draft.values, path);
                if (!Array.isArray(array)) {
                  throw new Error(`Path is not an array: ${path}`);
                }
                const [item] = array.splice(from, 1);
                array.splice(to, 0, item);
              }),
            );
            get().actions.validateChange();
          },
          reset: (values) => {
            set(
              produce((draft) => {
                draft.values = values;
                draft.isSubmitted = false;
              }),
            );
            get().actions.validateChange();
          },
          validate: () => {
            const result = schema.safeParse(get().values);
            set(
              produce((draft) => {
                draft.issues = result.success ? [] : result.error.issues;
              }),
            );
            return result.success;
          },
          validateChange: () => {
            if (validationMode === "onChange" || get().isSubmitted) {
              get().actions.validate();
            }
          },
          getValues: () => get().values,
          handleSubmit: (onValid, onInvalid) => (e) => {
            set(
              produce((draft) => {
                draft.isSubmitted = true;
              }),
            );

            const isValid = get().actions.validate();
            if (isValid) {
              onValid(get().values);
            } else {
              const [firstIssueWithRef] = get()
                .issues.reduce(
                  (acc, issue) => {
                    const ref = refs.current[issue.path.join(".") as Path<V>];
                    if (ref) {
                      acc.push({ issue, ref });
                    }
                    return acc;
                  },
                  [] as Array<{ issue: ZodIssue; ref: Focusable }>,
                )
                .sort((a, b) => {
                  if (a.ref.compareDocumentPosition(b.ref) & 2) {
                    return 1;
                  }
                  return -1;
                });
              firstIssueWithRef?.ref.focus();
              onInvalid?.();
            }

            e.preventDefault();
          },
          ref: (path) => (ref) => {
            refs.current[path] = ref;
          },
          focus: (path) => {
            refs.current[path]?.focus();
          },
        },
      }),
      Object.is,
    ),
  ).current;
  const actions = control((state) => state.actions);

  return { control, actions };
};

export const useFormField = <
  C extends ReturnType<typeof useForm>["control"],
  S extends TypeOf<ExtractState<C>["schema"]>,
  P extends Path<S>,
  V extends PathValue<S, P>,
>(
  control: C,
  path: P,
) => {
  return control(
    (state) => {
      const id = `${state.id}-${path}`;
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const update = (update: V) => state.actions.update(path, update as any); // Using the right type here is hard
      const issue = state.issues.find((issue) => issue.path.join(".") === path);
      const ref = state.actions.ref(String(path));
      const focus = () => state.actions.focus(String(path));
      const value = _get(state.values, path) as V;

      return { id, value, issue, update, ref, focus };
    },
    (a, b) => {
      return (
        a.id === b.id &&
        shallow(a.value, b.value) &&
        ((a.issue === undefined && b.issue === undefined) ||
          (a.issue?.code === ZodIssueCode.custom &&
            b.issue?.code === ZodIssueCode.custom &&
            a.issue?.params?.code === b.issue?.params?.code) ||
          a.issue?.code === b.issue?.code)
      );
    },
  );
};

export const useFormFieldArray = <
  C extends ReturnType<typeof useForm>["control"],
  S extends ExtractState<C>,
  P extends ArrayPath<S["values"]>,
  V extends PathValue<S["values"], P>,
  I extends Unpacked<V>,
>(
  control: C,
  path: P,
) => {
  // Generate a unique id for each item in the array, which is used for the `key` prop
  const initialItems = _get(control.getState().values, path) || [];
  if (!Array.isArray(initialItems)) {
    throw new Error(`initialItems is not an array: ${path}`);
  }

  const ids = useRef<Array<ID>>(initialItems.map(newID));

  const setIds = (cb: (ids: Array<ID>) => Array<ID>) => {
    ids.current = cb(ids.current);
  };

  useEffect(() =>
    control.subscribe((state) => {
      const newItems = _get(state.values, path) || [];
      if (!Array.isArray(newItems)) {
        throw new Error(`newItems is not an array: ${path}`);
      }
      setIds((ids) => {
        if (ids.length === newItems.length) {
          return ids;
        }
        if (ids.length > newItems.length) {
          return [...ids].slice(0, newItems.length);
        }
        return [...ids, ...new Array(newItems.length - ids.length).fill("").map(newID)];
      });
    }),
  );

  return control(
    (state) => {
      const fields = ids.current.map((id, index) => {
        const remove = () => {
          setIds((ids) => {
            const newIds = [...ids];
            newIds.splice(index, 1);
            return newIds;
          });
          state.actions.removeFromArray(path, index);
        };
        return { id, remove };
      });

      const append = (id: ID, item: I) => {
        setIds((ids) => [...ids, id]);
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        state.actions.appendToArray(path, item as any); // Using the right type here is hard
      };

      const move = (from: number, to: number) => {
        setIds((ids) => {
          const newIds = [...ids];
          const [item] = newIds.splice(from, 1);
          if (!item) {
            throw new Error(`Item not found at index ${from}`);
          }
          newIds.splice(to, 0, item);
          return newIds;
        });
        state.actions.moveInArray(path, from, to);
      };

      return { fields, append, move };
    },
    (a, b) => {
      // Only re-render if the fields length change, or if the order of the fields change.
      return (
        a.fields.length == b.fields.length &&
        a.fields.every((field, index) => {
          const otherField = b.fields[index];
          if (!otherField) {
            return false;
          }
          return field.id === otherField.id;
        })
      );
    },
  );
};

/**
 * Type which eagerly collects all paths through a type which point to an array
 * type.
 * @typeParam T - type which should be introspected
 * @example
 * ```
 * Path<{foo: {bar: string[], baz: number[]}}> = 'foo.bar' | 'foo.baz'
 * ```
 */
export type ArrayPath<T> =
  T extends ReadonlyArray<infer V>
    ? IsTuple<T> extends true
      ? {
          [K in TupleKeys<T>]-?: ArrayPathImpl<K & string, T[K]>;
        }[TupleKeys<T>]
      : ArrayPathImpl<ArrayKey, V>
    : {
        [K in keyof T]-?: ArrayPathImpl<K & string, T[K]>;
      }[keyof T];
