import {
  createContext,
  DragEventHandler,
  FocusEventHandler,
  LiHTMLAttributes,
  useContext,
  useRef,
  useState,
} from "react";

type DndContextType = {
  onDrop: (e: DropEvent) => void;
  onDragStart: (id: ID) => void;
  elementDraggingId: ID | undefined;
  data: Array<{ id: string }>;
};

export const DndContext = createContext<DndContextType | null>(null);

export type DropEvent = {
  activeId: string;
  overId: string;
};

export const useDndContext = () => {
  const context = useContext(DndContext);
  if (!context) {
    throw new Error("useDndContext must be used within a DndContext.Provider");
  }
  return context;
};

export const useSortable = ({ id }: { id: ID }) => {
  const { onDrop, onDragStart, data, elementDraggingId } = useDndContext();
  const [isDragging, setIsDragging] = useState(false);
  const [node, setNode] = useState<HTMLLIElement | null>(null);
  const border = useRef<["border-b-[3px]", "border-b-blue-9"] | ["border-t-2", "border-t-blue-9"]>([
    "border-b-[3px]",
    "border-b-blue-9",
  ]);
  const [draggable, setDraggable] = useState(true);

  const handleDragStart: DragEventHandler<HTMLLIElement> = (e) => {
    if (node) {
      onDragStart(id);
      setIsDragging(true);
      e.dataTransfer.effectAllowed = "move";
      e.dataTransfer.setData("text/plain", id);
    }
  };

  const handleDragOver: DragEventHandler<HTMLLIElement> = (e) => {
    e.preventDefault();

    if (node) {
      const draggingIndex = data.findIndex((item) => item.id === elementDraggingId);
      const overIndex = data.findIndex((item) => item.id === id);

      border.current =
        draggingIndex > overIndex ? ["border-t-2", "border-t-blue-9"] : ["border-b-[3px]", "border-b-blue-9"];

      e.currentTarget.classList.add(border.current[0], border.current[1]);
      e.dataTransfer.dropEffect = "move";
    }
  };

  const handleDragEnter: DragEventHandler<HTMLLIElement> = (e) => {
    e.preventDefault();
  };

  const handleDragLeave: DragEventHandler<HTMLLIElement> = (e) => {
    if (node) {
      e.currentTarget.classList.remove(border.current[0], border.current[1]);
    }
  };

  const handleDrop: DragEventHandler<HTMLLIElement> = (e) => {
    e.preventDefault();
    e.stopPropagation();
    const activeId = e.dataTransfer.getData("text/plain");
    const overId = e.currentTarget.dataset.id;

    if (overId) {
      onDrop({ activeId, overId });
    }

    if (node) {
      node.classList.remove(border.current[0], border.current[1]);
    }
  };
  const handleDragEnd: DragEventHandler<HTMLLIElement> = () => {
    if (node) {
      node.classList.remove(border.current[0], border.current[1]);
      setIsDragging(false);
    }
  };

  const handleFocus: FocusEventHandler<HTMLLIElement> = (event) => {
    // If the input is focused, we don't want to trigger the drag event
    if (event.target.tagName === "INPUT" && document.activeElement === event.target) {
      setDraggable(false);
    } else {
      setDraggable(true);
    }
  };

  const attributes: LiHTMLAttributes<HTMLLIElement> = {
    draggable,
    onDragStart: handleDragStart,
    onDragEnd: handleDragEnd,
    onDragOver: handleDragOver,
    onDrop: handleDrop,
    onDragEnter: handleDragEnter,
    onDragLeave: handleDragLeave,
    onFocus: handleFocus,
  };

  return { isDragging, attributes, setNodeRef: setNode };
};
