import { useTranslation } from "react-i18next";
import { ArrowLeft } from "@cgs/ui/components/Icon";
import { Button } from "@cgs/ui";
import classNames from "classnames";

type EditedProps = {
  isEditedSource?: boolean;
  onNavigateToHistory?: () => void;
  onResetToOriginalSource?: () => void;
};
function Edited({ onNavigateToHistory, onResetToOriginalSource, isEditedSource }: EditedProps) {
  const { t } = useTranslation();

  return (
    <div className="flex h-12 items-center gap-x-3 border-b border-b-navy-blue-6 px-2">
      {onNavigateToHistory && (
        <Button onClick={onNavigateToHistory} size="sm" startIcon={ArrowLeft} variant="ghost">
          {t("edited.history")}
        </Button>
      )}
      {isEditedSource && (
        <>
          <span className={classNames("ml-auto text-sm text-navy-blue-11", { "mr-3": !onResetToOriginalSource })}>
            {t("edited.note")}
          </span>
          {onResetToOriginalSource && (
            <Button variant="ghost" size="sm" color="blue" onClick={onResetToOriginalSource}>
              {t("edited.reset")}
            </Button>
          )}
        </>
      )}
    </div>
  );
}

export default Edited;
