import { z } from "zod";
import { fixedDate, flexDate, id, organization, person, range } from ".";
import { SourceType, SourceTypes } from "@cgs/types";
import { newCustomIssue } from "../utils";
import { isUrl, isDoiCode } from "../..";

export const sourceData = z
  .object({
    title: z.string().trim(),
    language: z.string(),
    subtitle: z.string(),
    description: z.string().trim(),
    eventTitle: z.string(),
    publisherPlace: z.object({
      country: z.string(),
      region: z.string(),
      locality: z.string(),
    }),
    eventPlace: z.object({
      country: z.string(),
      region: z.string(),
      locality: z.string(),
    }),
    archive: z.string(),
    archivePlace: z.object({
      country: z.string(),
      region: z.string(),
      locality: z.string(),
    }),
    issue: z.string(),
    content: z.string().trim(),
    section: z.string(),
    accessed: fixedDate,
    submitted: flexDate,
    url: z.string().superRefine((value, ctx) => {
      if (value.length <= 0) {
        return;
      }

      if (!isUrl(value)) {
        ctx.addIssue(newCustomIssue("invalid_url"));
      }
    }),
    doi: z.string().superRefine((doi, ctx) => {
      if (doi.length <= 0) {
        return;
      }
      if (!isDoiCode(doi)) {
        ctx.addIssue(newCustomIssue("invalid_doi"));
      }
    }),
    pdfUrl: z.string().superRefine((value, ctx) => {
      if (value.length <= 0) {
        return;
      }

      if (!isUrl(value)) {
        ctx.addIssue(newCustomIssue("invalid_url"));
      }
    }),
    version: z.string(),
    genre: z.string(),
    number: z.string(),
    episode: z.string(),
    season: z.string(),
    medium: z.string(),
    edition: z.string(),
    status: z.enum(["published", "in-press", "unpublished"]),
    volume: z.union([z.string(), range(z.string())]),
    page: z.union([z.string(), range(z.string())]),
    issued: flexDate,
    originalDate: flexDate,
    contributors: z.array(z.union([organization, person])),
    publisher: z.string(),
    authority: z.string(),
    composed: z.union([flexDate, range(flexDate)]),
    jurisdiction: z.string(),
    containerTitle: z.string().trim(),
    collectionTitle: z.string().trim(),
    source: z.string(),
    note: z.string(),
    image: z.string().url(),
    comment: z.string(),
  })
  .deepPartial()
  .merge(
    z.object({
      type: z.enum(SourceTypes),
    }),
  )
  .superRefine(({ type, title }, ctx) => {
    const sourceTypes: SourceType[] = [
      "journal-article",
      "online-news-article",
      "website",
      "print-magazine-article",
      "online-magazine-article",
      "book-chapter",
      "book",
      "video",
      "print-encyclopedia-entry",
      "online-encyclopedia-entry",
      "print-dictionary-entry",
      "online-dictionary-entry",
      "podcast",
      "film",
      "tv-show",
      "report",
      "press-release",
      "thesis",
      "conference-proceeding",
      "conference-session",
      "software",
      "forum-post",
      "presentation-slides",
      "patent",
      "wiki-entry",
    ];
    if (!sourceTypes.includes(type)) {
      return;
    }
    if (!title) {
      ctx.addIssue(newCustomIssue("required", ["title"]));
    }
  })
  .superRefine(({ type, title, description }, ctx) => {
    const sourceTypes: SourceType[] = [
      "newspaper-article",
      "webpage",
      "blog-post",
      "speech",
      "image",
      "artwork",
      "data-set",
      "speech",
      "image",
      "artwork",
    ];
    if (!sourceTypes.includes(type)) {
      return;
    }
    if (!title && !description) {
      ctx.addIssue(newCustomIssue("required", ["title"]));
      ctx.addIssue(newCustomIssue("required", ["description"]));
    }
  })
  .superRefine(({ type, containerTitle }, ctx) => {
    const sourceTypes: SourceType[] = [
      "journal-article",
      "newspaper-article",
      "online-news-article",
      "print-magazine-article",
      "book-chapter",
      "blog-post",
      "print-encyclopedia-entry",
      "print-dictionary-entry",
    ];
    if (!sourceTypes.includes(type)) {
      return;
    }
    if (!containerTitle) {
      ctx.addIssue(newCustomIssue("required", ["containerTitle"]));
    }
  })
  .superRefine(({ type, collectionTitle }, ctx) => {
    const sourceTypes: SourceType[] = ["podcast-episode", "tv-show-episode"];
    if (!sourceTypes.includes(type)) {
      return;
    }
    if (!collectionTitle) {
      ctx.addIssue(newCustomIssue("required", ["collectionTitle"]));
    }
  })
  .superRefine(({ type, content }, ctx) => {
    const sourceTypes: SourceType[] = ["social-media-post", "comment"];
    if (!sourceTypes.includes(type)) {
      return;
    }
    if (!content) {
      ctx.addIssue(newCustomIssue("required", ["content"]));
    }
  });

export const source = z.object({
  id,
  data: sourceData,
  origin: z.literal("openai").optional(),
  createdAt: z
    // Support date strings: https://github.com/colinhacks/zod#dates
    .preprocess((arg) => {
      if (typeof arg === "string" || arg instanceof Date) {
        return new Date(arg);
      }
      return;
    }, z.date())
    .optional(),
});
