import { useId, useState } from "react";
import { useTranslation, Trans } from "react-i18next";
import { SegmentedButton, Icon } from "@cgs/ui";
import { Citation, ScribbrEnv, Source, SummarizerMode } from "@cgs/types";
import { getCitationStyleTranslation } from "../../common/utils";
import { CitationStyleSelect } from "../CitationStyleSelect";
import { CitationStyle } from "@cgs/citation-engine/types";
import { useSettingsContext } from "../../settings/SettingsContext";
import { Summary } from "./Summary";
import { sendMessage } from "../../common/messaging";
import { getScribbrHost } from "@cgs/utils";
import { DOMAIN } from "../../common/constants";
import { Summary as SummaryType } from "../../common/types";

type SummarizeSectionProps = {
  citation?: Citation;
  source?: Source;
  citationStyle: CitationStyle;
  env: ScribbrEnv;
  summary: SummaryType;
  onSummarize: () => void;
};

export const SummarySection = ({
  env,
  citation,
  source,
  citationStyle,
  summary,
  onSummarize,
}: SummarizeSectionProps) => {
  const {
    settings: { summarizerMode },
    saveSettings,
  } = useSettingsContext();
  const { t } = useTranslation();

  const handleSummarizerModeChange = async (value: SummarizerMode) => {
    saveSettings({ summarizerMode: value });

    await sendMessage({
      type: "logEvent",
      event: {
        name: "Citation Generator Summary Mode Changed",
        data: {
          mode: value,
        },
      },
    });
  };

  return (
    <>
      <>
        <div className="flex justify-between">
          <SegmentedButton.Root value={summarizerMode} onValueChange={handleSummarizerModeChange} size="sm">
            <SegmentedButton.Item value="extractive" icon={Icon.List}>
              {t("summarizeSection.filters.extractive")}
            </SegmentedButton.Item>
            <SegmentedButton.Item value="abstractive" icon={Icon.AlignLeft}>
              {t("summarizeSection.filters.abstractive")}
            </SegmentedButton.Item>
          </SegmentedButton.Root>
          <CitationStyleSelect
            citationStyle={citationStyle}
            onCitationStyleChange={(citationStyle) => saveSettings({ citationStyle })}
            size="sm"
            contentAlign="end"
            variant="ghost"
          >
            {getCitationStyleTranslation(citationStyle, t, "short")}
          </CitationStyleSelect>
        </div>
        <small className="flex gap-3 rounded bg-yellow-3 p-3 text-xs text-yellow-12">
          <Icon.Lightbulb className="h-text shrink-0 fill-current" />
          <div>
            <Trans
              i18nKey={`summarizeSection.notes.${summarizerMode}`}
              defaults="This is an AI-generated summary. Please read the original content for details. If you choose to use this summary, it's important to credit the AI-generated content and the author of the work summarized by including proper citations. <learn-more-link>Learn more</learn-more-link>"
              components={{
                "learn-more-link": (
                  <a
                    href={`${getScribbrHost(DOMAIN, env)}/category/citing-sources`}
                    target="_blank"
                    className="font-semibold"
                    rel="noreferrer"
                  />
                ),
              }}
            />
          </div>
        </small>
        <Summary citation={citation} summarizerMode={summarizerMode} summary={summary} onSummarize={onSummarize} />
      </>
      {source && <RateThis mode={summarizerMode} source={source} />}
    </>
  );
};

function RateThis({ mode, source }: { mode: SummarizerMode; source: Source }) {
  const { t } = useTranslation(undefined, { keyPrefix: "summarizeSection.rateThis" });
  const id = useId();
  const [rated, setRated] = useState(false);

  const rate = async (rating: boolean) => {
    const hostname = source.data.url && new URL(source.data.url).hostname;

    await sendMessage({
      type: "logEvent",
      event: {
        name: "Citation Generator Content Rated",
        data: {
          type: "summary",
          rating,
          mode,
          hostname,
        },
      },
    });

    setRated(true);
  };

  return (
    <div className="flex h-6 items-center justify-center gap-2 text-xs text-navy-blue-11">
      {rated ? (
        <div role="alert">{t("thanks")}</div>
      ) : (
        <>
          <div id={id}>{t("question")}</div>
          <div
            className="group inline-flex items-stretch rounded border text-navy-blue-11 shadow-sm hover:border-navy-blue-7"
            role="group"
            aria-labelledby={id}
          >
            <button
              className="grid h-6 w-6 place-items-center hover:text-green-9"
              aria-label={t("yes")}
              onClick={() => rate(true)}
            >
              <Icon.ThumbsUp className="h-3 fill-current" />
            </button>
            <div className="w-px bg-navy-blue-6 group-hover:bg-navy-blue-7" />
            <button
              className="grid h-6 w-6 place-items-center hover:text-red-9"
              aria-label={t("no")}
              onClick={() => rate(false)}
            >
              <Icon.ThumbsDown className="h-3 fill-current" />
            </button>
          </div>
        </>
      )}
    </div>
  );
}
