import { Locale, SourceType, TextCase } from "@cgs/types";
import { CitationStyle } from "../types";
import { UnreachableCaseError } from "@cgs/utils";
import { isPromotedCitationStyle } from ".";

const DEFAULT_TITLE_TEXT_CASE: TextCase = "sentence-case";

export function getSourceTitleTextCase(citationStyle: CitationStyle, locale: Locale, sourceType: SourceType) {
  if (!isPromotedCitationStyle(citationStyle)) {
    return DEFAULT_TITLE_TEXT_CASE;
  }

  const citationStyleId = citationStyle[0];

  switch (citationStyleId) {
    case "mla": {
      if (locale === "en-US") {
        return "title-case";
      }

      return "sentence-case";
    }
    case "ama": {
      if (["image", "artwork", "film", "report"].includes(sourceType)) {
        return "title-case";
      }

      return "sentence-case";
    }
    case "acs": {
      if (["image", "artwork", "film", "report"].includes(sourceType)) {
        return "title-case";
      }

      return "sentence-case";
    }
    case "chicago-author-date":
    case "chicago-fullnote-bibliography": {
      if (sourceType === "patent") {
        return "sentence-case";
      }

      return "title-case";
    }
    case "turabian-author-date": {
      if (sourceType === "patent") {
        return "sentence-case";
      }

      return "title-case";
    }

    case "asa":
    case "turabian-fullnote-bibliography": {
      return "title-case";
    }

    case "apa":
    case "cse-author-date":
    case "cse":
    case "deutsche-zitierweise":
    case "harvard-cite-them-right":
    case "harvard-deakin-university":
    case "harvard-zitierweise":
    case "ieee":
    case "vancouver-author-date":
    case "vancouver": {
      return "sentence-case";
    }

    // To make sure we don't verify the text casing of promoted citation styles.
    default: {
      throw new UnreachableCaseError(citationStyleId);
    }
  }
}
