import { useMemo } from "react";
import * as Select from "../../../Select";
import { useSourceFormContext } from "../../SourceForm";
import { getCountryNames, isCountryCode } from "@cgs/utils";
import { useTranslation } from "react-i18next";

type LocationSelectProps = {
  value?: string;
  onValueChange?: (value: string) => void;
};

export const CountrySelect = ({ value, onValueChange }: LocationSelectProps) => {
  const { t } = useTranslation();
  const { scopedTKey, locale } = useSourceFormContext();

  const countryOptions = useMemo(() => {
    return Object.entries(getCountryNames(locale))
      .map(([code, name]) => {
        return {
          code,
          name,
        };
      })
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [locale]);

  return (
    <Select.Root value={value || "-"} onValueChange={onValueChange}>
      <Select.Trigger shouldFitContainer />
      <Select.Content>
        <Select.Item value="-">{t(scopedTKey("countrySelect.placeholder"))}</Select.Item>
        {countryOptions.map(({ code, name }) => (
          <Select.Item value={code} key={code}>
            {name}
          </Select.Item>
        ))}
        {value && value !== "-" && !isCountryCode(value) && <Select.Item value={value}>{value}</Select.Item>}
      </Select.Content>
    </Select.Root>
  );
};
