import { useCallback, useEffect, useRef, useState, createContext, useContext, useMemo } from "react";
import { MapEventListener, ObservableMap, isAbortError, signals } from "@cgs/utils";
import { Draft, freeze, produce } from "immer";

export type PrefetchedData = Record<string, unknown>;
const PrefetchedContext = createContext<PrefetchedData | undefined>(undefined);
export const Prefetched = PrefetchedContext.Provider;

type Fetcher<T> = (signal: AbortSignal) => Promise<T>;
type CachedFetcher<T> = {
  currentFetch: Promise<T>;
  fetcher: Fetcher<T>;
};
export type Options = {
  skipCache?: boolean;
  keepPreviousData?: boolean;
  defer?: boolean;
};

/* eslint-disable @typescript-eslint/no-explicit-any */
const fetcherCache = new Map<string, CachedFetcher<any>>();
const dataCache = new ObservableMap<string, any>();
/* eslint-enable @typescript-eslint/no-explicit-any */

export function resetCaches() {
  fetcherCache.clear();
  dataCache.clear();
}

export function useData<T>(
  key: string | null,
  fetcher: Fetcher<T>,
  options: Options = {},
): {
  data: T | undefined;
  error: unknown | undefined;
  isLoading: boolean;
  trigger: (abortSignal?: AbortSignal) => void;
} {
  const prefetchContext = useContext(PrefetchedContext);
  const cachedData =
    options.skipCache || key == null
      ? undefined
      : dataCache.has(key)
        ? dataCache.get(key)
        : prefetchContext?.[key];

  const [data, setData] = useState<T | undefined>(cachedData);
  const [error, setError] = useState<unknown | undefined>();
  const [isLoading, setIsLoading] = useState<boolean>(key != null && cachedData === undefined && !options.defer);

  const abortController = useMemo(() => {
    return new AbortController();
  }, [key]); // eslint-disable-line react-hooks/exhaustive-deps

  const trigger = useCallback(
    async (signal?: AbortSignal) => {
      if (key == null) {
        return;
      }

      if (cachedData) {
        setData(cachedData);
        fetcherCache.set(key, { currentFetch: Promise.resolve(cachedData), fetcher });
        return;
      }

      const currentFetch: Promise<T> =
        fetcherCache.get(key)?.currentFetch || fetcher(signals.any(abortController.signal, signal));
      fetcherCache.set(key, { currentFetch, fetcher });

      try {
        setIsLoading(true);
        const result = await currentFetch;
        setData(result);
        dataCache.set(key, freeze(result, true));
      } catch (e) {
        if (isAbortError(e)) {
          fetcherCache.delete(key);
        } else {
          setError(e);
        }
      } finally {
        if (options.skipCache) {
          fetcherCache.delete(key);
        }
        setIsLoading(false);
      }
    },
    [key, abortController], // eslint-disable-line react-hooks/exhaustive-deps
  );

  useEffect(() => {
    if (key == null) {
      return;
    }

    if (!options.keepPreviousData) {
      setData(cachedData);
      setError(undefined);
    }

    const listener: MapEventListener<T> = (event) => setData(event.newValue);
    dataCache.on(key, listener);

    return () => dataCache.off(key, listener);
  }, [key, cachedData, options.keepPreviousData]);

  useEffect(() => {
    if (!options.defer) {
      trigger();
    }

    return () => abortController.abort();
  }, [key, abortController]); // eslint-disable-line react-hooks/exhaustive-deps

  return { data, error, isLoading, trigger };
}

export function useReload() {
  const mutate = useMutate();
  const abortController = useRef<AbortController>();

  useEffect(() => () => abortController.current?.abort(), []);

  return useCallback(
    async (key: string) => {
      const loadData = fetcherCache.get(key);
      if (loadData == null) {
        return;
      }

      abortController.current = new AbortController();

      const currentFetch = loadData.fetcher(abortController.current.signal);
      fetcherCache.set(key, { currentFetch, fetcher: loadData.fetcher });

      try {
        const result = await currentFetch;
        mutate(key, result);
      } catch (e) {
        if (isAbortError(e)) {
          fetcherCache.delete(key);
        } else {
          throw e;
        }
      }
    },
    [mutate],
  );
}

export type Producer<T> = T | ((currentData: Draft<T>) => void) | undefined;

export function useMutate() {
  const prefetchContext = useContext(PrefetchedContext);

  return useCallback(
    <T>(key: string | RegExp, producer: Producer<T>) => {
      const updateCache = (key: string) => {
        if (producer === undefined) {
          fetcherCache.delete(key);
          dataCache.delete(key);
          return;
        }

        if (typeof producer === "function") {
          const currentData = dataCache.has(key) ? dataCache.get(key) : prefetchContext?.[key];
          if (currentData) {
            dataCache.set(key, produce(currentData, producer));
          }
          return;
        }

        dataCache.set(key, freeze(producer));
      };

      if (typeof key === "string") {
        updateCache(key);
      } else {
        for (const cacheKey of dataCache.keys()) {
          if (key.test(cacheKey)) {
            updateCache(cacheKey);
          }
        }
      }
    },
    [prefetchContext],
  );
}
