import { useSourceFormContext } from "../SourceForm";
import { ArrowRight } from "../../Icon";
import { Checkbox } from "../../Checkbox";
import * as Form from "../../Form";
import { TextInput } from "../../TextInput";
import { Fieldset } from "../components/Fieldset";
import { Control } from "../types";
import { useTranslation } from "react-i18next";

export const Page = ({ control }: { control: Control }) => {
  const { t } = useTranslation();
  const { scopedTKey } = useSourceFormContext();
  const { value, update, issue, ref, focus, id } = Form.useFormField(control, "page");
  const start = Form.useFormField(control, "page.start");
  const end = Form.useFormField(control, "page.end");

  const isRange = typeof value === "object" && value !== null;

  const handleStartChange = (newValue: string) => {
    update(isRange ? { start: newValue, end: value.end } : newValue);
  };
  const handleEndChange = (newValue: string) => {
    update({ start: isRange ? value.start : "", end: newValue });
  };
  const handleIsRangeChange = () => {
    update(isRange ? value.start || "" : { start: value || "", end: "" });
  };

  return (
    <Fieldset id="page" fields={["page"]} onLegendClick={isRange ? start.focus : focus}>
      <div className="flex items-center space-x-4">
        <div className="flex flex-1 items-center space-x-4">
          <div className="flex-1">
            <Form.Element issue={isRange ? start.issue : issue}>
              <TextInput
                value={(isRange ? start.value : value) || ""}
                onValueChange={handleStartChange}
                aria-label={t(scopedTKey(isRange ? "page.start.label" : "page.label"))}
                invalid={!!(isRange ? start.issue : issue)}
                ref={isRange ? start.ref : ref}
                id={isRange ? start.id : id}
              />
            </Form.Element>
          </div>
          {isRange && (
            <>
              <ArrowRight className="h-text shrink-0 fill-navy-blue-11" />
              <div className="flex-1">
                <Form.Element issue={end.issue}>
                  <TextInput
                    value={end.value || ""}
                    onValueChange={handleEndChange}
                    aria-label={t(scopedTKey("page.end.label"))}
                    invalid={!!end.issue}
                    ref={end.ref}
                    id={end.id}
                  />
                </Form.Element>
              </div>
            </>
          )}
        </div>
        <label className="flex shrink-0 items-center space-x-2 text-sm">
          <Checkbox checked={isRange} size="sm" onCheckedChange={handleIsRangeChange} />
          <span>{t(scopedTKey("page.range.label"))}</span>
        </label>
      </div>
    </Fieldset>
  );
};
