import classNames from "classnames";

export const Box = ({ children, ...props }: React.HTMLAttributes<HTMLDivElement>) => {
  const className = classNames(
    "animate-pulse bg-transparent border-navy-blue-4 border-2 rounded",
    props.className,
  );
  return (
    <div {...props} className={className}>
      {children}
    </div>
  );
};
