import * as Form from "../../Form";
import * as Select from "../../Select";
import { useSourceFormContext } from "../SourceForm";
import { Control } from "../types";
import { useTranslation } from "react-i18next";

export const Language = ({ control }: { control: Control }) => {
  const { t } = useTranslation();
  const { scopedTKey } = useSourceFormContext();
  const { value, update: setValue, ref, id } = Form.useFormField(control, "language");

  const handleValueChange = (value: string) => {
    if (value === "-") {
      return setValue(undefined);
    }
    setValue(value);
  };

  return (
    <div className="flex justify-end">
      <Select.Root value={value !== undefined ? value : "-"} onValueChange={handleValueChange} name="language">
        <Select.Trigger id={id} variant="link" size="sm" aria-label={t("language.label")} ref={ref} />
        <Select.Content>
          <Select.Item value="en">{t(scopedTKey("language.options.en"))}</Select.Item>
          <Select.Item value="-">{t(scopedTKey("language.options.nonEn"))}</Select.Item>
        </Select.Content>
      </Select.Root>
    </div>
  );
};
