import { Fieldset } from "../components/Fieldset";
import { Textarea } from "../../Textarea";
import * as Form from "../../Form";
import { Control } from "../types";

export const Content = ({ control }: { control: Control }) => {
  const content = Form.useFormField(control, "content");

  return (
    <Fieldset id="content" fields={["content"]} onLegendClick={content.focus}>
      <Form.Element issue={content.issue}>
        <Textarea
          value={content.value}
          onChange={(e) => content.update(e.currentTarget.value)}
          invalid={!!content.issue}
          ref={content.ref}
          id={content.id}
        />
      </Form.Element>
    </Fieldset>
  );
};
