import { Trans } from "react-i18next";
import { Skeleton } from "@cgs/ui";
import { Citation, SummarizerMode } from "@cgs/types";
import { sanitize } from "@cgs/utils/web";
import { sendMessage } from "../../common/messaging";
import { Summary as SummaryType } from "../../common/types";
import { useEffect } from "react";

type SummarizerProps = {
  citation?: Citation;
  summarizerMode: SummarizerMode;
  summary: SummaryType;
  onSummarize: () => void;
};

export const Summary = ({
  citation,
  summarizerMode,
  summary: { summaryError, isLoading, response },
  onSummarize,
}: SummarizerProps) => {
  const summary = response[summarizerMode];

  useEffect(() => {
    // if there is no summary, we should fetch it
    if (!summary) {
      onSummarize();
    }
  }, [onSummarize, summary]);
  const handleCopy = async () => {
    await sendMessage({
      type: "logEvent",
      event: {
        name: "Citation Generator Summary Copied",
        data: {
          trigger: "selection",
          mode: summarizerMode,
        },
      },
    });
  };

  if (summaryError !== undefined) {
    return (
      <div className="flex flex-col items-center justify-center gap-y-1">
        <h4 className="text-lg font-semibold text-navy-blue-12">{summaryError}</h4>
        <p className="text-navy-blue11 text-sm">
          <Trans i18nKey="serviceError.description" components={{ a: <a href="#" className="text-blue-9" /> }} />
        </p>
      </div>
    );
  }

  if (!summary || isLoading) {
    return (
      <Skeleton className="my-2 space-y-2">
        <Skeleton.Line />
        <Skeleton.Line />
        <Skeleton.Line className="w-1/2" />
      </Skeleton>
    );
  }

  return {
    extractive: (
      <ul className="ml-4 list-disc space-y-3 text-sm" onCopy={handleCopy}>
        {([] as Array<string>).concat(summary).map((p, i) => (
          <li key={i}>
            <span
              // eslint-disable-next-line react/no-danger
              dangerouslySetInnerHTML={{
                __html: sanitize(`“${p.trim()}”`),
              }}
            />
            {citation?.[0].citation && (
              <span
                // eslint-disable-next-line react/no-danger
                dangerouslySetInnerHTML={{
                  __html: ` ${sanitize(citation[0].citation)}`,
                }}
                className="text-navy-blue-11"
              />
            )}
          </li>
        ))}
      </ul>
    ),
    abstractive: (
      <div className="space-y-3 text-sm" onCopy={handleCopy}>
        {([] as Array<string>).concat(summary).map((p, i) => (
          // eslint-disable-next-line react/no-danger
          <p key={i} dangerouslySetInnerHTML={{ __html: sanitize(p) }} />
        ))}
      </div>
    ),
  }[summarizerMode];
};
