import { useSourceFormContext } from "../SourceForm";
import { Checkbox, CheckedState } from "../../Checkbox";
import * as Form from "../../Form";
import { Fieldset } from "../components/Fieldset";
import { Language } from "./Language";
import { TextInput } from "../../TextInput";
import { TextCaseSuggestion } from "../../TextCaseSuggestion";
import { useTextCase, TextCaseFetcher } from "../../../hooks";
import { Control } from "../types";
import { AmplitudeEvent, Locale } from "@cgs/types";
import { useTranslation } from "react-i18next";
import { useMemo } from "react";
import { getSourceTitleTextCase } from "@cgs/citation-engine/common";
import { CitationStyle } from "@cgs/citation-engine/types";

type TitleProps = {
  showLanguagePick: boolean;
  control: Control;
  locale: Locale;
  textCaseFetcher: TextCaseFetcher;
  citationStyle: CitationStyle;
  logEvent: (event: AmplitudeEvent) => void;
};

export const Title = ({
  control,
  locale,
  showLanguagePick,
  textCaseFetcher,
  citationStyle,
  logEvent,
}: TitleProps) => {
  const { t } = useTranslation();
  const { config, scopedTKey } = useSourceFormContext();
  const description = Form.useFormField(control, "description");
  const sourceType = Form.useFormField(control, "type");
  const language = Form.useFormField(control, "language");
  const subtitle = Form.useFormField(control, "subtitle");
  const title = Form.useFormField(control, "title");

  const showSubtitle = subtitle.value != null;
  const showDescription = description.value != null;
  const showLabels = showSubtitle || showDescription || !config.fields.title;

  const localeForTextCase = language.value === "en" ? "en-US" : locale;
  const textCase = useMemo(
    () => getSourceTitleTextCase(citationStyle, localeForTextCase, sourceType.value),
    // TODO: Remove this once the issue is fixed in TypeScript
    // https://github.com/microsoft/TypeScript/issues/45149
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    [citationStyle, localeForTextCase, sourceType.value],
  );
  const titleTextCase = useTextCase(title.value || "", localeForTextCase, textCase, textCaseFetcher, {
    keepPreviousData: true,
  });
  const subtitleTextCase = useTextCase(subtitle.value || "", localeForTextCase, textCase, textCaseFetcher, {
    keepPreviousData: true,
  });

  const handleShowSubtitleChange = (checked: CheckedState) => {
    subtitle.update(checked ? "" : undefined);
  };

  const handleShowDescriptionChange = (checked: CheckedState) => {
    description.update(checked ? "" : undefined);
  };

  const handleLegendClick = () => {
    if (config.fields.title) {
      return title.focus();
    }
    if (showSubtitle) {
      return subtitle.focus();
    }
    if (showDescription) {
      return description.focus();
    }
  };

  return (
    <Fieldset id="title" fields={["title", "description", "subtitle"]} onLegendClick={handleLegendClick}>
      {config.fields.title && (
        <Form.Element issue={title.issue}>
          {showLabels && (
            <label className="text-sm" htmlFor={title.id}>
              {t(scopedTKey("title.title.label"))}
            </label>
          )}
          <div>
            <TextInput
              value={title.value || ""}
              onValueChange={title.update}
              invalid={!!title.issue}
              id={title.id}
              ref={title.ref}
              aria-label={showLabels ? undefined : t(scopedTKey("title.title.label"))}
              aria-describedby={`${title.id}-case-check`}
            />
            <TextCaseSuggestion
              id={`${title.id}-case-check`}
              suggestion={titleTextCase.data}
              isLoading={titleTextCase.isLoading}
              onApply={(suggestion) => {
                title.update(suggestion);
                logEvent({
                  name: "Citation Generator Text Suggestion Applied",
                  data: {
                    textCase,
                    locale,
                  },
                });
              }}
            />
          </div>
        </Form.Element>
      )}
      {(config.fields.description || config.fields.subtitle) && (
        <div className="flex space-x-4">
          {config.fields.description && (
            <label className="flex items-center space-x-2 text-sm">
              <Checkbox checked={showDescription} onCheckedChange={handleShowDescriptionChange} size="sm" />
              <span>{t(scopedTKey("title.description.show"))}</span>
            </label>
          )}
          {config.fields.subtitle && (
            <label className="flex items-center space-x-2 text-sm">
              <Checkbox checked={showSubtitle} onCheckedChange={handleShowSubtitleChange} size="sm" />
              <span>{t(scopedTKey("title.subtitle.show"))}</span>
            </label>
          )}
          {showLanguagePick && <Language control={control} />}
        </div>
      )}
      {showSubtitle && (
        <Form.Element issue={subtitle.issue}>
          {showLabels && (
            <label className="text-sm" htmlFor={subtitle.id}>
              {t(scopedTKey("title.subtitle.label"))}
            </label>
          )}
          <div>
            <TextInput
              value={subtitle.value || ""}
              onValueChange={subtitle.update}
              invalid={!!subtitle.issue}
              id={subtitle.id}
              ref={subtitle.ref}
              aria-label={showLabels ? undefined : t(scopedTKey("title.subtitle.label"))}
            />
            <TextCaseSuggestion
              id={`${subtitle.id}-case-check`}
              suggestion={subtitleTextCase.data}
              isLoading={subtitleTextCase.isLoading}
              onApply={(suggestion) => {
                subtitle.update(suggestion);
                logEvent({
                  name: "Citation Generator Text Suggestion Applied",
                  data: {
                    textCase,
                    locale,
                  },
                });
              }}
            />
          </div>
        </Form.Element>
      )}
      {showDescription && (
        <Form.Element issue={description.issue}>
          {showLabels && (
            <label className="text-sm" htmlFor={description.id}>
              {t(scopedTKey("title.description.label"))}
            </label>
          )}
          <TextInput
            value={description.value || ""}
            onValueChange={description.update}
            invalid={!!description.issue}
            id={description.id}
            ref={description.ref}
            aria-label={showLabels ? undefined : t(scopedTKey("title.description.label"))}
          />
        </Form.Element>
      )}
    </Fieldset>
  );
};
