import { ComponentPropsWithoutRef, forwardRef, useContext, createContext, ElementRef } from "react";
import * as RadioGroupPrimitive from "@radix-ui/react-radio-group";
import classNames from "classnames";

type Size = "sm" | "md";
type Justify = "start" | "center" | "end";

type SegmentedButtonContextType = {
  size: Size;
};

const SegmentedButtonContext = createContext<SegmentedButtonContextType | null>(null);

type RootProps = ComponentPropsWithoutRef<typeof RadioGroupPrimitive.Root> & {
  size?: Size;
  justify?: Justify;
};

const useSegmentedButtonContext = () => {
  const context = useContext(SegmentedButtonContext);
  if (!context) {
    throw new Error("useSegmentedButtonContext must be used within a SegmentedButtonContext.Provider");
  }
  return context;
};

export const Root = forwardRef<ElementRef<typeof RadioGroupPrimitive.Root>, RootProps>(function Root(
  { children, size = "md", justify = "start", ...forwardedProps },
  ref,
) {
  return (
    <SegmentedButtonContext.Provider
      value={{
        size,
      }}
    >
      <RadioGroupPrimitive.Root {...forwardedProps} ref={ref}>
        <div
          className={classNames(
            "flex flex-wrap gap-1",
            { start: "justify-start", center: "justify-center", end: "justify-end" }[justify],
          )}
        >
          {children}
        </div>
      </RadioGroupPrimitive.Root>
    </SegmentedButtonContext.Provider>
  );
});

export const Item = forwardRef<
  ElementRef<typeof RadioGroupPrimitive.Item>,
  RadioGroupPrimitive.RadioGroupItemProps & { icon?: SVGComponent }
>(function Item({ className, children, icon: Icon, ...forwardedProps }, ref) {
  const { size } = useSegmentedButtonContext();

  return (
    <RadioGroupPrimitive.Item
      {...forwardedProps}
      ref={ref}
      className={classNames(
        "inline-flex min-w-0 items-center rounded-full font-semibold state-checked:bg-blue-3 state-checked:text-blue-12 state-checked:hover:bg-blue-4 state-unchecked:text-navy-blue-11 state-unchecked:hover:bg-navy-blue-4 state-unchecked:hover:text-navy-blue-12",
        {
          sm: "p-1 text-sm",
          md: "p-2 text-base",
        }[size],
        className,
      )}
    >
      {Icon && <Icon className="ml-2 h-text shrink-0 fill-current" />}
      <div className="mx-2 my-0.5 grow truncate">{children}</div>
      <RadioGroupPrimitive.Indicator />
    </RadioGroupPrimitive.Item>
  );
});
