import { forwardRef } from "react";
import { TextInput, TextInputProps } from "../../../TextInput";

type YearInputProps = Omit<TextInputProps, "value" | "onChange" | "type" | "max"> & {
  value?: number | null;
  onChange: (value: number | undefined) => void;
};

export const YearInput = forwardRef<HTMLInputElement, YearInputProps>(function YearInput(
  { value, onChange, ...otherProps },
  ref,
) {
  return (
    <TextInput
      value={value === undefined ? "-" : String(value)}
      onChange={(event) => {
        if (event.target.value === "-") {
          return onChange(undefined);
        }
        const output = Number(event.target.value);
        onChange(isNaN(output) ? undefined : output);
      }}
      ref={ref}
      type="number"
      {...otherProps}
    />
  );
});
