import { useSourceFormContext } from "../SourceForm";
import * as Form from "../../Form";
import { TextInput as Input } from "../../TextInput";
import { Fieldset } from "../components/Fieldset";
import { Control } from "../types";
import { useTranslation } from "react-i18next";
import { Source } from "@cgs/types";

type PickByType<T, Value> = {
  [P in keyof T as T[P] extends Value | undefined ? P : never]: T[P];
};

export const TextInput = ({
  field,
  control,
}: {
  field: keyof PickByType<Source["data"], string>;
  control: Control;
}) => {
  const { t } = useTranslation();
  const formField = Form.useFormField(control, field);
  const { scopedTKey } = useSourceFormContext();

  return (
    <Fieldset id={field} fields={[field]} onLegendClick={formField.focus}>
      <Form.Element issue={formField.issue}>
        <Input
          id={formField.id}
          value={formField.value || ""}
          onValueChange={formField.update}
          invalid={!!formField.issue}
          placeholder={t(scopedTKey(`${field}.placeholder`), "")}
          aria-label={t(scopedTKey(`${field}.label`))}
          ref={formField.ref}
        />
      </Form.Element>
    </Fieldset>
  );
};
