import * as Dialog from "@radix-ui/react-dialog";
import { Button, Icon, ListBox } from "@cgs/ui";
import { useTranslation } from "react-i18next";
import { Folder, List } from "../../common/types";
import { useSessionStorageContext } from "../SessionStorageProvider";
import { useMemo } from "react";
import classNames from "classnames";
import { DOMAIN } from "../../common/constants";
import { ScribbrEnv } from "@cgs/types";
import { getCreateNewListURL } from "../../common/utils";
import { sendMessage } from "../../common/messaging";

type CreateListDialogProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onAddToList: (list?: List) => void;
  env: ScribbrEnv;
};

export function CreateListDialog({ open, onOpenChange, onAddToList, env }: CreateListDialogProps) {
  const { t } = useTranslation();
  const { folders } = useSessionStorageContext();
  const rootFolder = folders?.find((folder) => folder.isRoot);

  const handleAddToList = (list?: List) => {
    onAddToList(list);
    onOpenChange(false);
  };

  if (!folders || !rootFolder) {
    return null;
  }

  return (
    <Dialog.Root open={open} onOpenChange={(open) => onOpenChange(open)}>
      <Dialog.Overlay className="fixed bottom-0 left-0 top-0 z-overlay w-full bg-navy-blue-12 opacity-50 state-open:animate-fade-in-50" />
      <Dialog.Content className="state-open:animate-slide-in-right fixed bottom-0 right-0 top-0 z-overlay flex w-2/5 max-w-sm flex-col gap-y-4 overflow-auto rounded-l-2xl bg-white shadow-xl">
        <div className="flex items-center justify-between gap-y-6 border-b border-b-navy-blue-6 px-6 py-2">
          <Dialog.Title className="text-sm font-semibold">{t("createListDialog.addToList")}</Dialog.Title>
          <Dialog.Close asChild>
            <Button variant="ghost" icon={Icon.XMark} size="sm" />
          </Dialog.Close>
        </div>
        <div className="flex h-full flex-col gap-y-5 px-2">
          <FolderList onAddToList={handleAddToList} />
        </div>
        <div className="border-t border-t-navy-blue-6 px-6 py-4">
          <Button
            as="a"
            shouldFitContainer
            href={getCreateNewListURL(DOMAIN, env, rootFolder.id)}
            target="_blank"
            variant="solid"
            color="blue"
            justify="center"
            size="sm"
            endIcon={Icon.ArrowUpRight}
          >
            {t("createListDialog.newList")}
          </Button>
        </div>
      </Dialog.Content>
    </Dialog.Root>
  );
}

const sortFoldersByListUpdatedAt = (folders?: Array<Folder>) => {
  return (folders || []).sort((a, b) => {
    const aMaxListUpdatedAt = Math.max(...a.lists.map((list) => new Date(list.updatedAt).getTime()));
    const bMaxListUpdatedAt = Math.max(...b.lists.map((list) => new Date(list.updatedAt).getTime()));
    return bMaxListUpdatedAt - aMaxListUpdatedAt;
  });
};

const FolderList = ({ onAddToList }: { onAddToList: CreateListDialogProps["onAddToList"] }) => {
  const { t } = useTranslation();
  const folders = sortFoldersByListUpdatedAt(useSessionStorageContext().folders);

  const lists = useMemo(() => folders.flatMap((folder) => folder.lists), [folders]);

  const handleOptionSelect = (id: string) => {
    const list = lists.find((list) => list.id === id);
    onAddToList(list);
  };

  return (
    <ListBox.Root
      className="flex flex-col gap-y-4"
      autoFocus
      elementToListenForEvents={document.body}
      options={lists}
      onOptionSelect={handleOptionSelect}
      selectOptionOnMouseOver
    >
      {lists.length === 0 && (
        <ListBox.Option
          className={classNames(
            "group flex h-[36px] cursor-pointer items-center justify-between gap-x-3 rounded-md py-1 pl-4 pr-1 text-sm font-semibold",
            "hover:bg-navy-blue-3",
            "transition-colors",
          )}
          key={"new-list"}
          id={"new-list"}
          aria-label={"Add to new list"}
        >
          {t("createListDialog.addToNewList")}
        </ListBox.Option>
      )}
      {folders.map((folder) => (
        <div key={folder.id}>
          <div className="truncate px-3 py-1 text-xs font-semibold text-navy-blue-11">
            {folder.isRoot ? t("createListDialog.myLists") : folder.name}
          </div>
          {folder.lists
            .sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime())
            .map((list) => (
              <ListBox.Option
                className={classNames(
                  "group flex cursor-pointer items-center justify-between gap-x-3 rounded-md py-1 pl-4 pr-1 text-sm font-semibold",
                  "aria-selected:bg-navy-blue-3",
                  "transition-colors",
                )}
                key={list.id}
                id={list.id}
                aria-label={list.settings.name}
              >
                <span className="truncate">{list.settings.name}</span>
                <Button
                  as="a"
                  href={list.link}
                  className={classNames("opacity-0", "group-aria-selected:opacity-100", "transition-opacity")}
                  variant="ghost"
                  target="_blank"
                  size="sm"
                  endIcon={Icon.ArrowUpRight}
                  onClick={() =>
                    sendMessage({
                      type: "logEvent",
                      event: { name: "Citation Generator Browser Extension List Viewed" },
                    })
                  }
                >
                  {t("createListDialog.view")}
                </Button>
              </ListBox.Option>
            ))}
        </div>
      ))}
    </ListBox.Root>
  );
};
