import { Locale, MAX_TEXT_CASER_LENGTH, TextCase } from "@cgs/types";
import { useDebounce, useData, Options } from "./";

const DEBOUNCE_INTERVAL = 500;

type Key = `${TextCase}.${Locale}.${string}`;

/**
 * Additional caching layer on top of `useData` so that we don't have to make a request when `text` is the text cased version.
 */
const cache = new Map<Key, string>();

export type TextCaseFetcher = (
  input: string,
  locale: Locale,
  textCase: TextCase,
  signal: AbortSignal,
) => Promise<string>;

export const useTextCase = (
  input: string,
  locale: Locale,
  textCase: TextCase,
  fetcher: TextCaseFetcher,
  options: Options = {},
) => {
  const key: Key = `${textCase}.${locale}.${input}`;
  const debouncedKey = useDebounce(key, cache.has(key) ? 0 : DEBOUNCE_INTERVAL);

  return useData(
    debouncedKey,
    async (signal) => {
      if (input.length > MAX_TEXT_CASER_LENGTH || !input) {
        return undefined;
      }

      const cached = cache.get(key);
      if (cached) {
        return cached !== input ? cached : undefined;
      }

      const output = await fetcher(input, locale, textCase, signal);

      cache.set(`${textCase}.${locale}.${input}`, output);
      cache.set(`${textCase}.${locale}.${output}`, output);

      return output !== input ? output : undefined;
    },
    options,
  );
};
