export class NetworkError extends Error {
  constructor(message: string) {
    super(message);
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class MaintenanceModeError extends Error {
  constructor() {
    super("Server is in maintenance mode");
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class ContentScriptNotAvailableError extends Error {
  constructor() {
    super("Content script is not available");
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export function isMaintenanceModeError(error: unknown): error is MaintenanceModeError {
  return error instanceof MaintenanceModeError;
}

export class GoogleUnauthorizedError extends Error {
  constructor() {
    super("Google unauthorized");
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class GoogleForbiddenError extends Error {
  constructor() {
    super("Google forbidden");
    Object.setPrototypeOf(this, new.target.prototype);
  }
}
