import { z } from "zod";
import { SourceContributorRoles } from "@cgs/types";
import { newCustomIssue } from "../utils";

export const person = z
  .object({
    type: z.literal("person"),
    role: z.enum(SourceContributorRoles),
    title: z.string().optional(),
    initials: z.string().optional(),
    given: z.string().optional(),
    particle: z.string().optional(),
    family: z.string().optional(),
    suffix: z.string().optional(),
    screenName: z.string().optional(),
  })
  .superRefine(({ initials, family, given }, ctx) => {
    if (initials && !family && !given) {
      ctx.addIssue(newCustomIssue("required", ["family"]));
    }
  });
