import { FormEventHandler, ReactNode, createContext, useContext } from "react";

import {
  Accessed,
  Composed,
  Content,
  Contributors,
  Page,
  Issued,
  Status,
  Submitted,
  TextInput,
  Title,
  Volume,
  Publisher,
  Event,
  Archive,
  Note,
  Type,
} from "./Fieldsets";
import * as Form from "../Form";
import { Button } from "../Button";
import { TextCaseFetcher } from "../../hooks";
import { AmplitudeEvent, CitationStyleOptions, Locale } from "@cgs/types";
import { Config } from "./config";
import { Control, ScopedTKey } from "./types";
import { useTranslation } from "react-i18next";
import { CitationStyle } from "@cgs/citation-engine/types";

type SourceFormContextType = {
  config: Config;
  scopedTKey: ScopedTKey;
  locale: Locale;
};

type SourceFormProps = {
  citationStyle: CitationStyle;
  isExistingSource: boolean;
  citationStyleOptions: CitationStyleOptions;
  locale: Locale;
  textCaseFetcher: TextCaseFetcher;
  control: Control;
  scopedTKey: ScopedTKey;
  config: Config;
  onSubmit: FormEventHandler<HTMLFormElement>;
  isSubmitting?: boolean;
  id?: string;
  logEvent: (event: AmplitudeEvent) => void;
};

export const SourceFormContext = createContext<SourceFormContextType | null>(null);

export const useSourceFormContext = () => {
  const context = useContext(SourceFormContext);
  if (!context) {
    throw new Error("useSourceFormContext must be used within a SourceFormContext.Provider");
  }
  return context;
};

export const SourceForm = ({
  citationStyle,
  isExistingSource,
  citationStyleOptions,
  locale,
  textCaseFetcher,
  control,
  scopedTKey,
  config,
  isSubmitting,
  onSubmit,
  id,
  logEvent,
}: SourceFormProps) => {
  const { t } = useTranslation();

  const provide: SourceFormContextType = {
    config,
    scopedTKey,
    locale,
  };

  return (
    <SourceFormContext.Provider value={provide}>
      <Form.Root id={id} onSubmit={onSubmit} className="space-y-6">
        <Fieldsets>
          <Type control={control} />
        </Fieldsets>
        <Fieldsets>
          <Title
            citationStyle={citationStyle}
            textCaseFetcher={textCaseFetcher}
            locale={locale}
            showLanguagePick={citationStyleOptions.showLanguagePick}
            control={control}
            logEvent={logEvent}
          />
          <Content control={control} />
          <TextInput field="containerTitle" control={control} />
          <TextInput field="collectionTitle" control={control} />
        </Fieldsets>
        <Fieldsets>
          <Contributors scopedTKey={scopedTKey} control={control} givenName={citationStyleOptions?.givenName} />
        </Fieldsets>
        <Fieldsets>
          <TextInput field="edition" control={control} />
          <Volume control={control} />
          <TextInput field="issue" control={control} />
          <TextInput field="version" control={control} />
          <TextInput field="season" control={control} />
          <TextInput field="episode" control={control} />
          <TextInput field="number" control={control} />
          <TextInput field="section" control={control} />
        </Fieldsets>
        <Fieldsets>
          <TextInput field="jurisdiction" control={control} />
          <TextInput field="authority" control={control} />
        </Fieldsets>
        <Fieldsets>
          <TextInput field="medium" control={control} />
          <TextInput field="genre" control={control} />
          <Status control={control} />
          <Issued control={control} />
          <Accessed control={control} scopedTKey={scopedTKey} locale={locale} />
          <Composed control={control} />
          <Submitted control={control} />
        </Fieldsets>
        <Fieldsets>
          <Publisher control={control} />
          <Event control={control} />
          <Archive control={control} />
          <TextInput field="source" control={control} />
          <Page control={control} />
        </Fieldsets>
        <Fieldsets>
          <TextInput field="doi" control={control} />
          <TextInput field="pdfUrl" control={control} />
          <TextInput field="url" control={control} />
        </Fieldsets>
        <Note control={control} />
        <Button
          className="mt-9"
          variant="solid"
          color="blue"
          type="submit"
          loading={isSubmitting}
          disabled={isSubmitting}
        >
          {t(scopedTKey(isExistingSource ? "submitButton.update" : "submitButton.create"))}
        </Button>
      </Form.Root>
    </SourceFormContext.Provider>
  );
};

function Fieldsets({ children }: { children: ReactNode }) {
  return <div className="space-y-4 border-b pb-4 empty:hidden md:pb-6">{children}</div>;
}
