import { useTranslation } from "react-i18next";
import { Header, TabSection } from "../components/Popup";
import { usePopupPageContext } from "./PopupPageState";
import { ScribbrEnv, Source } from "@cgs/types";
import { AISourceBanner, Button } from "@cgs/ui";
import { contactUrlMap } from "../components/ErrorBoundary";
import { HistoryEntry, Summary } from "../common/types";
import Edited from "../components/Popup/Edited";
import { useEffect, useState } from "react";
import { getActiveTab } from "../common/utils";
import { CitationStyle } from "@cgs/citation-engine/types";

type CurrentPageTabProps = {
  onEnterSourceEditMode: (source?: Source) => void;
  onResetToOriginalSource: () => void;
  onAddToList: () => void;
  history: Array<HistoryEntry>;
  summary: Summary;
  onSummarize: () => void;
  onCitationStyleChange: (style: CitationStyle) => void;
};
export const CurrentPageTab = ({
  onEnterSourceEditMode,
  onResetToOriginalSource,
  history,
  summary,
  onSummarize,
  onAddToList,
  onCitationStyleChange,
}: CurrentPageTabProps) => {
  const { locale, source, citationInfo, currentPageError } = usePopupPageContext();
  const env = (process.env.SCRIBBR_ENV || "dev") as ScribbrEnv;
  const [tab, setTab] = useState<chrome.tabs.Tab>();

  useEffect(() => {
    (async () => {
      const tab = await getActiveTab();
      setTab(tab);
    })();
  }, []);

  if (currentPageError) {
    return <ErrorDisplay currentPageError={currentPageError} />;
  }

  const historyEntry = history.find((entry) => entry.id === tab?.url);

  return (
    <div className="flex h-full flex-col">
      {historyEntry?.isEditedSource && (
        <Edited isEditedSource={historyEntry?.isEditedSource} onResetToOriginalSource={onResetToOriginalSource} />
      )}
      <Header onEnterSourceEditMode={onEnterSourceEditMode} onAddToList={onAddToList} source={source} />
      <TabSection
        {...citationInfo}
        env={env}
        source={source}
        locale={locale}
        summary={summary}
        onSummarize={onSummarize}
        onCitationStyleChange={onCitationStyleChange}
      />
      {source?.origin === "openai" && <AISourceBanner />}
    </div>
  );
};

const ErrorDisplay = ({
  currentPageError,
}: Required<Pick<ReturnType<typeof usePopupPageContext>, "currentPageError">>) => {
  const { t } = useTranslation();

  // TODO: move error messages to loco
  const [heading, message] = (() => {
    switch (currentPageError.type) {
      case "ContentTooLargeError":
        return ["Page content is too large", "Try citing another page that has less content."];
      case "InvalidResponseError":
        return ["Page could not be cited", currentPageError.message || "Something went wrong."];
      case "ContentScriptNotAvailableError":
        return [
          t("errorPage.contentScriptNotAvailableError.title"),
          t("errorPage.contentScriptNotAvailableError.description"),
        ];
      case "ExtractSourceError":
        return [
          "Page could not be cited",
          "We could not extract a valid source for this page. Please try citing another page.",
        ];
    }
  })();

  return (
    <div className="flex h-full flex-col items-center justify-center space-y-4 p-5">
      <div className="flex w-full flex-col items-center space-y-2 text-center">
        <h1 className="font-display text-xl font-bold">{heading}</h1>
        <p className="w-full grow text-sm">{message}</p>
      </div>
      {currentPageError.type === "ContentScriptNotAvailableError" && (
        <Button
          variant="solid"
          color="blue"
          size="sm"
          as="a"
          href={contactUrlMap["en-US"]}
          target="_blank"
          rel="noreferrer"
        >
          {t("errorPage.contactButton")}
        </Button>
      )}
    </div>
  );
};
