import { ComponentPropsWithoutRef, forwardRef, useLayoutEffect, useRef, useState } from "react";
import classNames from "classnames";

type TextareaAttributes = ComponentPropsWithoutRef<"textarea">;

export type TextareaProps = {
  invalid?: boolean;
} & TextareaAttributes;

export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>((props, ref) => {
  const { invalid, className, onChange, ...otherProps } = props;
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const [value, setValue] = useState(props.value || "");

  useLayoutEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto";
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
      textareaRef.current.style.overflowY = "hidden";
    }
  }, [value]);

  return (
    <textarea
      {...(otherProps as TextareaAttributes)}
      className={classNames(
        "block w-full resize-none rounded-md border bg-white px-4 py-2 text-base shadow-sm placeholder:text-navy-blue-8 focus:outline-2 disabled:opacity-40",
        {
          "border-navy-blue-7 hover:border-navy-blue-8 focus:border-blue-9 focus:outline-blue-9": !invalid,
          "border-red-9 hover:outline-red-10 focus:border-red-9 focus:outline-red-9": invalid,
        },
        className,
      )}
      ref={(node) => {
        textareaRef.current = node;
        if (typeof ref === "function") {
          ref(node);
        }
      }}
      // To calculate the height of the textarea, we need to set the value to the current value.
      onChange={(event) => {
        setValue(event.target.value);
        if (typeof onChange === "function") {
          onChange(event);
        }
      }}
    />
  );
});

Textarea.displayName = "Textarea";
