const DOI_CODE_RGX = /(10\.\d{4,9}\/+[-._;()/:a-zA-Z0-9]+)\b/;
const IS_DOI_RGX = new RegExp(`^(?:doi:\\s*)?${DOI_CODE_RGX.source}\.?$`);
const IS_DOI_URL_RGX = new RegExp(
  `^(?:doi:\\s*)?(?:https?:\/\/)?(dx\.)?doi\.org\/${DOI_CODE_RGX.source}[./]*$`,
  "i",
);
const POP_PATH_PART_RGX = /.+\/.+(?=\/.+)/;

const FIND_ALL_DOIS_RGX = new RegExp(DOI_CODE_RGX.source, "g");

export function findDois(text: string): { doi: string; index: number; percentage: number }[] {
  const matches = text.match(FIND_ALL_DOIS_RGX);

  if (!matches || matches.length === 0) {
    return [];
  }

  return matches.map((match) => {
    const index = text.indexOf(match);
    const percentage = (index / text.length) * 100;

    return { doi: match, index, percentage };
  });
}

function sanitizeDoi(value: string) {
  let decoded = value;
  try {
    decoded = decodeURIComponent(value);
  } catch (e) {
    // ignore decoding errors, probably already decoded or just invalid
  }

  return decoded.replace(/\s+/g, "");
}

export function isDoi(value: string) {
  return IS_DOI_URL_RGX.test(value) || IS_DOI_RGX.test(value);
}

export function isDoiCode(value: string) {
  return IS_DOI_RGX.test(value);
}

export function extractDoiCode(s: unknown) {
  const doi = typeof s === "string" && sanitizeDoi(s);
  if (!doi) {
    return;
  }

  const match = doi.match(DOI_CODE_RGX);
  return match?.[1]?.replace(/\/+/g, "/");
}

export const doiToURL = (value?: string) => {
  const doi = value && sanitizeDoi(value) && extractDoiCode(value);
  if (!doi) {
    return undefined;
  }

  return `https://doi.org/${doi}`;
};

export function popPathPart(doi: string) {
  const match = doi.match(POP_PATH_PART_RGX);
  if (match && match[0]) {
    return match[0];
  }
  return undefined;
}
