import { z } from "zod";
import { newCustomIssue } from "../utils";
import { isValidDate } from "../validations";

export const flexDate = z
  .object({
    year: z.number(),
    month: z.number(),
    day: z.number(),
    raw: z.string(),
    season: z.enum(["spring", "summer", "fall", "winter"]),
    circa: z.boolean(),
  })
  .partial()
  .superRefine(({ year, month }, ctx) => {
    if (!year && month) {
      ctx.addIssue(newCustomIssue("required", ["year"]));
    }
  })
  .superRefine(({ year, month, day }, ctx) => {
    if (year && day && !month) {
      ctx.addIssue(newCustomIssue("required", ["month"]));
    }
  })
  .superRefine(({ month, season }, ctx) => {
    if (month && season) {
      ctx.addIssue(newCustomIssue("invalid_combination", ["month", "season"]));
    }
  })
  .superRefine(({ year, month, day }, ctx) => {
    if (!isValidDate(day, month, year)) {
      ctx.addIssue(newCustomIssue("invalid_date"));
    }
  });
