import classNames from "classnames";
import { ComponentPropsWithoutRef, ComponentPropsWithRef, ElementType, ForwardedRef, forwardRef } from "react";
import { Spinner } from "../Icon";

const element = "button";
type Element = typeof element;

export const ButtonColors = ["navy-blue", "orange", "blue", "yellow", "purple", "mint", "red", "green"] as const;
export type ButtonColor = (typeof ButtonColors)[number];

export const ButtonSizes = ["xs", "sm", "md", "lg"] as const;
export type ButtonSize = (typeof ButtonSizes)[number];

export const ButtonVariants = ["outline", "solid", "low-contrast", "high-contrast", "ghost", "link"] as const;
export type ButtonVariant = (typeof ButtonVariants)[number];

export const ButtonJustifies = ["start", "end", "center", "between", "around", "evenly"] as const;
export type ButtonJustify = (typeof ButtonJustifies)[number];

type FixedForwardRef = <T, P = object>(
  render: (props: P, ref: React.Ref<T>) => React.ReactNode,
) => (props: P & React.RefAttributes<T>) => JSX.Element;

const fixedForwardRef = forwardRef as FixedForwardRef;

type DistributiveOmit<T, TOmitted extends PropertyKey> = T extends unknown ? Omit<T, TOmitted> : never;

export type ButtonProps<Element extends ElementType = "button"> = ComponentPropsWithoutRef<Element> & {
  color?: ButtonColor;
  size?: ButtonSize;
  variant?: ButtonVariant;
  shouldFitContainer?: boolean;
  icon?: SVGComponent;
  startIcon?: SVGComponent;
  endIcon?: SVGComponent;
  loading?: boolean | undefined;
  justify?: ButtonJustify;
};

export const Button = fixedForwardRef(
  <TAs extends ElementType>(
    {
      as,
      size = "md",
      variant = "outline",
      color = "navy-blue",
      className,
      shouldFitContainer,
      children,
      icon: Icon,
      startIcon: StartIcon,
      endIcon: EndIcon,
      type,
      loading,
      disabled,
      justify = "around",
      ...otherProps
    }: { as?: TAs } & DistributiveOmit<ComponentPropsWithRef<ElementType extends TAs ? Element : TAs>, "as"> &
      ButtonProps<ElementType>,
    /* eslint-disable @typescript-eslint/no-explicit-any */
    forwardedRef: ForwardedRef<any>,
  ) => {
    const Comp = as || element;
    // if no `type` is provided for a button component, default to "button" type instead of "submit"
    if (!type && Comp === "button") {
      type = "button";
    }
    const iconClassName = classNames(
      "h-text shrink-0",
      {
        sm: "my-0.5",
        md: "my-13",
        lg: "my-1.5",
        xs: "my-2",
      }[size],
    );

    return (
      <Comp
        ref={forwardedRef}
        type={type}
        disabled={disabled || loading}
        className={classNames(
          "relative max-w-full items-center rounded-md border fill-current font-semibold transition-colors",
          shouldFitContainer ? "flex w-full" : "inline-flex",
          {
            xs: "text-xs",
            sm: "text-sm",
            md: "text-sm",
            lg: "text-md",
          }[size],
          variant !== "link" &&
            {
              xs: "h-6",
              sm: "h-9",
              md: "h-10",
              lg: "h-12",
            }[size],
          variant !== "link" &&
            (Icon
              ? {
                  xs: "w-6",
                  sm: "w-9",
                  md: "w-10",
                  lg: "w-12",
                }[size]
              : {
                  xs: "px-2",
                  sm: "px-3",
                  md: "px-4",
                  lg: "px-5",
                }[size]),
          {
            start: "justify-start",
            end: "justify-end",
            center: "justify-center",
            between: "justify-between",
            around: "justify-around",
            evenly: "justify-evenly",
          }[justify],
          {
            outline: "border-navy-blue-7 bg-white shadow-sm",
            solid: "border-transparent",
            "low-contrast": "border-transparent",
            "high-contrast": "border-transparent text-white",
            ghost: "border-transparent",
            link: "border-transparent hover-not-disabled:underline",
          }[variant],
          (
            {
              outline: {
                "navy-blue":
                  "text-navy-blue-11 hover-not-disabled:border-navy-blue-8 hover-not-disabled:bg-navy-blue-4 hover-not-disabled:text-navy-blue-12",
                orange:
                  "text-orange-11 hover-not-disabled:border-orange-8 hover-not-disabled:bg-orange-4 hover-not-disabled:text-orange-12",
                blue: "text-blue-11 hover-not-disabled:border-blue-8 hover-not-disabled:bg-blue-4 hover-not-disabled:text-blue-12",
                yellow:
                  "text-yellow-11 hover-not-disabled:border-yellow-8 hover-not-disabled:bg-yellow-4 hover-not-disabled:text-yellow-12",
                purple:
                  "text-purple-11 hover-not-disabled:border-purple-8 hover-not-disabled:bg-purple-4 hover-not-disabled:text-purple-12",
                mint: "text-mint-11 hover-not-disabled:border-mint-8 hover-not-disabled:bg-mint-4 hover-not-disabled:text-mint-12",
                red: "text-red-11 hover-not-disabled:border-red-8 hover-not-disabled:bg-red-4 hover-not-disabled:text-red-12",
                green:
                  "text-green-11 hover-not-disabled:border-green-8 hover-not-disabled:bg-green-4 hover-not-disabled:text-green-12",
              },
              solid: {
                "navy-blue": "bg-navy-blue-9 text-white hover-not-disabled:bg-navy-blue-10",
                orange: "bg-orange-9 text-white hover-not-disabled:bg-orange-10",
                blue: "bg-blue-9 text-white hover-not-disabled:bg-blue-10",
                yellow: "bg-yellow-9 text-white hover-not-disabled:bg-yellow-10",
                purple: "bg-purple-9 text-white hover-not-disabled:bg-purple-10",
                mint: "bg-mint-9 text-white hover-not-disabled:bg-mint-10",
                red: "bg-red-9 text-white hover-not-disabled:bg-red-10",
                green: "bg-green-9 text-white hover-not-disabled:bg-green-10",
              },
              "low-contrast": {
                "navy-blue": "bg-navy-blue-3 text-navy-blue-12 hover-not-disabled:bg-navy-blue-4",
                orange: "bg-orange-3 text-orange-12 hover-not-disabled:bg-orange-4",
                blue: "bg-blue-3 text-blue-12 hover-not-disabled:bg-blue-4",
                yellow: "bg-yellow-3 text-yellow-12 hover-not-disabled:bg-yellow-4",
                purple: "bg-purple-3 text-purple-12 hover-not-disabled:bg-purple-4",
                mint: "bg-mint-3 text-mint-12 hover-not-disabled:bg-mint-4",
                red: "bg-red-3 text-red-12 hover-not-disabled:bg-red-4",
                green: "bg-green-3 text-green-12 hover-not-disabled:bg-green-4",
              },
              "high-contrast": {
                "navy-blue": "bg-navy-blue-12",
                orange: "bg-orange-12",
                blue: "bg-blue-12",
                yellow: "bg-yellow-12",
                purple: "bg-purple-12",
                mint: "bg-mint-12",
                red: "bg-red-12",
                green: "bg-green-12",
              },
              ghost: {
                "navy-blue":
                  "text-navy-blue-11 hover-not-disabled:bg-navy-blue-4 hover-not-disabled:text-navy-blue-12",
                orange: "text-orange-11 hover-not-disabled:bg-orange-4 hover-not-disabled:text-orange-12",
                blue: "text-blue-11 hover-not-disabled:bg-blue-4 hover-not-disabled:text-blue-12",
                yellow: "text-yellow-11 hover-not-disabled:bg-yellow-4 hover-not-disabled:text-yellow-12",
                purple: "text-purple-11 hover-not-disabled:bg-purple-4 hover-not-disabled:text-purple-12",
                mint: "text-mint-11 hover-not-disabled:bg-mint-4 hover-not-disabled:text-mint-12",
                red: "text-red-11 hover-not-disabled:bg-red-4 hover-not-disabled:text-red-12",
                green: "text-green-11 hover-not-disabled:bg-green-4 hover-not-disabled:text-green-12",
              },
              link: {
                "navy-blue": "text-navy-blue-9",
                orange: "text-orange-9",
                blue: "text-blue-9",
                yellow: "text-yellow-9",
                purple: "text-purple-9",
                mint: "text-mint-9",
                red: "text-red-9",
                green: "text-green-9",
              },
            } satisfies Record<ButtonVariant, Record<ButtonColor, string>>
          )[variant][color],
          loading && "text-opacity-0 opacity-40",
          disabled && "opacity-40",
          className,
        )}
        {...otherProps}
      >
        {Icon && <Icon className={iconClassName} />}
        {StartIcon && (
          <StartIcon
            className={classNames(
              iconClassName,
              {
                xs: "mr-1",
                sm: "mr-2",
                md: "mr-3",
                lg: "mr-4",
              }[size],
            )}
          />
        )}
        {children && <span className="truncate">{children}</span>}
        {EndIcon && (
          <EndIcon
            className={classNames(
              iconClassName,
              {
                xs: "ml-1",
                sm: "ml-2",
                md: "ml-3",
                lg: "ml-4",
              }[size],
            )}
          />
        )}
        {loading && (
          <div className="absolute inset-0 flex items-center justify-center">
            <Spinner
              className={classNames(
                "h-text animate-spin",
                (
                  {
                    outline: {
                      "navy-blue": "text-navy-blue-11 hover:text-navy-blue-12",
                      orange: "text-orange-11 hover:text-orange-12",
                      blue: "text-blue-11 hover:text-blue-12",
                      yellow: "text-yellow-11 hover:text-yellow-12",
                      purple: "text-purple-11 hover:text-purple-12",
                      mint: "text-mint-11 hover:text-mint-12",
                      red: "text-red-11 hover:text-red-12",
                      green: "text-green-11 hover:text-green-12",
                    },
                    solid: {
                      "navy-blue": "text-white",
                      orange: "text-white",
                      blue: "text-white",
                      yellow: "text-white",
                      purple: "text-white",
                      mint: "text-white",
                      red: "text-white",
                      green: "text-white",
                    },
                    "high-contrast": {
                      "navy-blue": "text-white",
                      orange: "text-white",
                      blue: "text-white",
                      yellow: "text-white",
                      purple: "text-white",
                      mint: "text-white",
                      red: "text-white",
                      green: "text-white",
                    },
                    "low-contrast": {
                      "navy-blue": "",
                      orange: "text-navy-blue-12",
                      blue: "text-blue-12",
                      yellow: "text-yellow-12",
                      purple: "text-purple-12",
                      mint: "text-mint-12",
                      red: "text-red-12",
                      green: "text-green-12",
                    },
                    ghost: {
                      "navy-blue": "text-navy-blue-11 hover:text-navy-blue-12",
                      orange: "text-orange-11 hover:text-orange-12",
                      blue: "text-blue-11 hover:text-blue-12",
                      yellow: "text-yellow-11 hover:text-yellow-12",
                      purple: "text-purple-11 hover:text-purple-12",
                      mint: "text-mint-11 hover:text-mint-12",
                      red: "text-red-11 hover:text-red-12",
                      green: "text-green-11 hover:text-green-12",
                    },
                    link: {
                      "navy-blue": "text-navy-blue-11",
                      orange: "text-orange-11",
                      blue: "text-blue-11",
                      yellow: "text-yellow-11",
                      purple: "text-purple-11",
                      mint: "text-mint-11",
                      red: "text-red-11",
                      green: "text-green-11",
                    },
                  } satisfies Record<ButtonVariant, Record<ButtonColor, string>>
                )[variant][color],
                "text-opacity-100",
              )}
            />
          </div>
        )}
      </Comp>
    );
  },
);
