import { z } from "zod";

type Code =
  | "invalid_date"
  | "invalid_url"
  | "invalid_doi"
  | "required"
  | "invalid_combination"
  | "max_one_file"
  | "required_file"
  | "invalid_backup_file"
  | "file_too_large"
  | "invalid_id"
  | "invalid_citation_style"
  | "invalid_font"
  | "invalid_font_size"
  | "invalid_locale"
  | "invalid_word_processor";

export const newCustomIssue = (code: Code, path: Array<string | number> = []) => {
  return {
    code: z.ZodIssueCode.custom,
    path,
    params: {
      code,
    },
  };
};
