import { ComponentPropsWithoutRef, ReactNode } from "react";
import classNames from "classnames";
import { ZodIssue, ZodIssueCode } from "zod";
import { useTranslation } from "react-i18next";

export const Root = ({ children, noValidate = true, ...otherProps }: ComponentPropsWithoutRef<"form">) => {
  return (
    <form {...otherProps} noValidate={noValidate}>
      {children}
    </form>
  );
};

const Issue = ({ issue }: { issue: ZodIssue }) => {
  const { t } = useTranslation();

  const translationKey =
    issue.code === ZodIssueCode.custom && issue.params?.code
      ? `errors.custom.${issue.params.code}`
      : "type" in issue
        ? `errors.${issue.type}.${issue.code}`
        : null;
  const message = translationKey ? t(translationKey, { defaultValue: issue.message }) : issue.message;

  return (
    <p role="alert" className="text-xs text-red-11">
      {message}
    </p>
  );
};

export const Element = ({ issue, children }: { issue?: ZodIssue; children: ReactNode }) => {
  return (
    <div className="flex w-full flex-col gap-2">
      {children}
      {issue && <Issue issue={issue} />}
    </div>
  );
};

export const Label = ({
  htmlFor,
  srOnly,
  className,
  children,
}: {
  htmlFor?: string;
  srOnly?: boolean;
  className?: string;
  children: ReactNode;
}) => {
  return (
    <label
      className={classNames("inline-block text-sm font-semibold", srOnly && "sr-only", className)}
      htmlFor={htmlFor}
    >
      {children}
    </label>
  );
};
