import * as SelectPrimitive from "@radix-ui/react-select";
import classNames from "classnames";
import { ComponentProps, ElementRef, forwardRef, useContext, useMemo, createContext } from "react";
import { Button, ButtonProps } from "../Button";
import { useControllableState } from "@radix-ui/react-use-controllable-state";
import { AngleDown, AngleUp, Check } from "../Icon";

type SelectContextType = {
  title?: string;
  dirty: boolean;
} & (
  | { resettable: true; resetLabel: string; reset: () => void }
  | { resettable?: false; resetLabel?: never; reset?: never }
);

const SelectContext = createContext<SelectContextType | null>(null);

export const useSelectContext = () => {
  const context = useContext(SelectContext);
  if (!context) {
    throw new Error("useSelectContext must be used within a SelectContext.Provider");
  }
  return context;
};

export type RootProps = SelectPrimitive.SelectProps & {
  title?: string;
} & ({ resettable: true; resetLabel: string } | { resettable?: false; resetLabel?: never });

export const Root = ({ resettable, resetLabel, title, ...primitiveProps }: RootProps) => {
  const [value, setValue] = useControllableState({
    prop: primitiveProps.value,
    defaultProp: primitiveProps.defaultValue,
    onChange: primitiveProps.onValueChange,
  });
  const [open, setOpen] = useControllableState({
    prop: primitiveProps.open,
    defaultProp: primitiveProps.defaultOpen,
    onChange: primitiveProps.onOpenChange,
  });
  const provide: SelectContextType = useMemo(
    () => ({
      title,
      dirty: primitiveProps.value !== primitiveProps.defaultValue,
      ...(resettable
        ? {
            resettable,
            resetLabel,
            reset: () => {
              if (primitiveProps.defaultValue === undefined) {
                throw new Error("Select.Root must have a defaultValue to be resettable");
              }
              setValue(primitiveProps.defaultValue);
              setOpen(false);
            },
          }
        : { resettable }),
    }),
    [primitiveProps.defaultValue, primitiveProps.value, resetLabel, resettable, setOpen, setValue, title],
  );

  return (
    <SelectContext.Provider value={provide}>
      <SelectPrimitive.Root
        {...primitiveProps}
        value={value}
        onValueChange={setValue}
        open={open}
        onOpenChange={setOpen}
      />
    </SelectContext.Provider>
  );
};

export type TriggerProps = ButtonProps;

export const Trigger = forwardRef<
  HTMLButtonElement,
  Omit<ButtonProps, "endIcon"> & { endIcon?: NonNullable<ButtonProps["endIcon"]> | false }
>(function ButtonTrigger({ children, endIcon = AngleDown, ...otherProps }, forwardedRef) {
  return (
    <SelectPrimitive.Trigger asChild>
      <Button ref={forwardedRef} endIcon={endIcon || undefined} justify="between" {...otherProps}>
        {children ? (
          <SelectPrimitive.Value asChild>
            <span className="overflow-hidden text-ellipsis">{children}</span>
          </SelectPrimitive.Value>
        ) : (
          <SelectPrimitive.Value />
        )}
      </Button>
    </SelectPrimitive.Trigger>
  );
});

export const Content = forwardRef<
  ElementRef<typeof SelectPrimitive.Content>,
  ComponentProps<typeof SelectPrimitive.Content> & {
    portalContainer?: HTMLElement | null;
    disableZIndex?: boolean;
  }
>(function Content({ children, className, portalContainer, disableZIndex = false, ...otherProps }, forwardedRef) {
  const { title, resettable, resetLabel, reset, dirty } = useSelectContext();
  const showReset = resettable && dirty;

  return (
    <SelectPrimitive.Portal container={portalContainer}>
      <SelectPrimitive.Content
        className={classNames(
          "overflow-hidden rounded-lg bg-white shadow-lg",
          { "z-overlay": !disableZIndex },
          className,
        )}
        ref={forwardedRef}
        {...otherProps}
      >
        <SelectPrimitive.ScrollUpButton className="flex h-6 cursor-default items-center justify-center bg-white shadow">
          <AngleUp className="h-3 fill-navy-blue-11" />
        </SelectPrimitive.ScrollUpButton>
        <SelectPrimitive.Viewport>
          {(title || resettable) && (
            <div className="flex items-center justify-between space-x-3 border-b px-3 py-1.5">
              <span className="text-sm font-semibold">{title}</span>
              <div className={classNames({ "opacity-0": !showReset })}>
                <Button size="xs" onClick={reset} disabled={!showReset}>
                  {resetLabel}
                </Button>
              </div>
            </div>
          )}
          <div className="p-1">{children}</div>
        </SelectPrimitive.Viewport>
        <SelectPrimitive.ScrollDownButton className="flex h-6 cursor-default items-center justify-center bg-white shadow">
          <AngleDown className="h-3 fill-navy-blue-11" />
        </SelectPrimitive.ScrollDownButton>
      </SelectPrimitive.Content>
    </SelectPrimitive.Portal>
  );
});

export const Item = forwardRef<
  ElementRef<typeof SelectPrimitive.Item>,
  ComponentProps<typeof SelectPrimitive.Item>
>(function Item({ children, className, ...otherProps }, forwardedRef) {
  return (
    <SelectPrimitive.Item
      className={classNames(
        "relative flex select-none items-center rounded py-1.5 pl-9 pr-6 text-sm text-navy-blue-12 focus:bg-blue-4 focus:text-blue-12 data-disabled:pointer-events-none data-disabled:opacity-40",
        className,
      )}
      ref={forwardedRef}
      {...otherProps}
    >
      <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
      <SelectPrimitive.ItemIndicator className="absolute left-1 inline-flex w-6 items-center justify-center fill-current">
        <Check className="h-3" />
      </SelectPrimitive.ItemIndicator>
    </SelectPrimitive.Item>
  );
});

export const Separator = forwardRef<
  ElementRef<typeof SelectPrimitive.Separator>,
  ComponentProps<typeof SelectPrimitive.Separator>
>(function Seperator({ className, ...otherProps }, forwardedRef) {
  return (
    <SelectPrimitive.Separator
      className={classNames("my-1 h-px w-full bg-navy-blue-6", className)}
      ref={forwardedRef}
      {...otherProps}
    />
  );
});

export const Group = forwardRef<
  ElementRef<typeof SelectPrimitive.Group>,
  ComponentProps<typeof SelectPrimitive.Group>
>(function Group({ className, ...otherProps }, forwardedRef) {
  return <SelectPrimitive.Group className={classNames(className)} ref={forwardedRef} {...otherProps} />;
});

export const Label = forwardRef<
  ElementRef<typeof SelectPrimitive.Label>,
  ComponentProps<typeof SelectPrimitive.Label>
>(function Label({ className, ...otherProps }, forwardedRef) {
  return (
    <SelectPrimitive.Label
      className={classNames("py-2 pl-9 pr-6 text-xs text-navy-blue-11", className)}
      ref={forwardedRef}
      {...otherProps}
    />
  );
});
