import * as Form from "../../Form";
import * as SegmentedButton from "../../SegmentedButton";
import { useSourceFormContext } from "../SourceForm";
import { Fieldset } from "../components/Fieldset";
import { Control } from "../types";
import { Source } from "@cgs/types";
import { useTranslation } from "react-i18next";

export const Status = ({ control }: { control: Control }) => {
  const { t } = useTranslation();
  const { config, scopedTKey } = useSourceFormContext();
  const status = Form.useFormField(control, "status");
  const options = config.options?.statuses;

  if (options == null || options.length === 0) {
    return null;
  }

  return (
    <Fieldset id="status" fields={["status"]}>
      <Form.Element issue={status.issue}>
        <SegmentedButton.Root
          onValueChange={(update) => status.update(update as Source["data"]["status"])}
          value={status.value || undefined}
          size="sm"
        >
          {options.map((option) => (
            <SegmentedButton.Item key={option} value={option}>
              {t(scopedTKey(`status.options.${option}`))}
            </SegmentedButton.Item>
          ))}
        </SegmentedButton.Root>
      </Form.Element>
    </Fieldset>
  );
};
