import { forwardRef } from "react";
import { getDatesInMonth } from "@cgs/utils";
import * as Select from "../../../Select";
import { useSourceFormContext } from "../../SourceForm";
import { useTranslation } from "react-i18next";

type DayInputProps = {
  /** A number representing a day of the month. */
  value?: number | null;
  /** Event handler called when the value changes. */
  onChange: (value: number | undefined) => void;
  /** The year of the month. */
  year?: number | null;
  /** The month of the year, zero-based. */
  month?: number | null;
  /** Whether the input is disabled or not. */
  disabled?: boolean;
};

export const DayInput = forwardRef<HTMLButtonElement, DayInputProps>(function DayInput(
  { value, onChange, month, year, disabled, ...otherProps },
  ref,
) {
  const { t } = useTranslation();
  const { scopedTKey } = useSourceFormContext();

  const handleValueChange = (value: string) => {
    if (!onChange) {
      return;
    }
    onChange(value ? Number(value) : undefined);
  };

  const days = (() => {
    if (month == null || year == null) {
      return [];
    }
    const date = new Date(0);
    date.setFullYear(year);
    date.setMonth(month);
    return getDatesInMonth(date).map((d) => d.getDate());
  })();

  if (value && !days.includes(value)) {
    onChange(undefined);
  }

  return (
    <Select.Root value={value != null ? String(value) : "-"} onValueChange={handleValueChange} {...otherProps}>
      <Select.Trigger disabled={disabled} {...otherProps} ref={ref} size="sm" shouldFitContainer />
      <Select.Content>
        <Select.Item value="-">{t(scopedTKey("dayInput.options.none"))}</Select.Item>
        {days.map((day) => (
          <Select.Item key={day} value={String(day)}>
            {day}
          </Select.Item>
        ))}
      </Select.Content>
    </Select.Root>
  );
});
