import { useTranslation } from "react-i18next";
import { Control } from "../types";
import { Fieldset } from "../components/Fieldset";
import { useSourceFormContext } from "../SourceForm";
import * as Form from "../../Form";
import { Button } from "../../Button";
import { Textarea } from "../../Textarea";

export const Note = ({ control }: { control: Control }) => {
  const { t } = useTranslation();
  const { scopedTKey } = useSourceFormContext();
  const { value, update, focus, ref, issue, id } = Form.useFormField(control, "note");

  const showNote = value != null;

  const handleRemoveAnnotation = () => {
    update(undefined);
  };

  const handleAddNote = () => {
    update("");
  };

  return (
    <Fieldset id="note" fields={["note"]} onLegendClick={focus}>
      {!showNote ? (
        <Button onClick={handleAddNote} size="sm">
          {t(scopedTKey("note.add"))}
        </Button>
      ) : (
        <div className="space-y-2">
          <Form.Element issue={issue}>
            <Textarea
              value={value}
              onChange={(e) => update(e.currentTarget.value)}
              invalid={!!issue}
              aria-label={t(scopedTKey("note.label"))}
              ref={ref}
              id={id}
            />
          </Form.Element>
          <Button variant="link" onClick={handleRemoveAnnotation} justify="start" size="xs" color="blue">
            {t(scopedTKey("note.remove"))}
          </Button>
        </div>
      )}
    </Fieldset>
  );
};
