import { CitationStyleOptions } from "@cgs/types";
import { CitationStyle, PromotedCitationStyleId } from "../types";
import { isPromotedCitationStyle } from ".";

export function getCitationStyleOptions(citationStyle: CitationStyle) {
  if (!isPromotedCitationStyle(citationStyle)) {
    return defaultCitationStyleOptions;
  }

  const [citationStyleId] = citationStyle;
  return { ...defaultCitationStyleOptions, ...citationStyleOptions[citationStyleId] };
}

