function combineSignals(
  check: "every" | "some",
  ...signals: Array<AbortSignal | undefined>
): AbortSignal | undefined {
  const actualSignals = signals.filter((signal): signal is AbortSignal => signal != null);

  if (actualSignals.length <= 1) {
    return actualSignals[0];
  }

  const controller = new AbortController();
  const handleAbort = (reason: unknown) => {
    if (actualSignals[check]((signal) => signal?.aborted)) {
      controller.abort(reason);
    }
  };

  for (const signal of actualSignals) {
    if (signal.aborted) {
      handleAbort(signal.reason);
    }

    signal.addEventListener("abort", () => handleAbort(signal.reason), { once: true });
  }

  return controller.signal;
}

export interface CombineSignals {
  (signal: undefined, ...signals: Array<AbortSignal | undefined>): AbortSignal | undefined;
  (signal: AbortSignal, ...signals: Array<AbortSignal | undefined>): AbortSignal;
}

export const signals = {
  all: combineSignals.bind(combineSignals, "every") as CombineSignals,
  any: combineSignals.bind(combineSignals, "some") as CombineSignals,
};
