import {
  Domains,
  Locales,
  NonEmptyArray,
  ScribbrEnvs,
  SourceContributor,
  SourceOrganization,
  SourcePerson,
  Source,
} from "@cgs/types";
import { schemas } from ".";
import { picklist } from "valibot";
import { enumerate, isSourceType } from "../utils";
import { UnreachableCaseError } from "../errors";
import { isID } from "../id";

export function isNonEmptyArray<T>(array: Array<T>): array is NonEmptyArray<T> {
  return array.length > 0;
}

export function isAvailable<T>(value: T): value is NonNullable<T> {
  return value != null;
}

export function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value != null && !Array.isArray(value);
}

export function hasProperty<K extends string, T extends object>(
  k: K,
  o: T,
): o is T & Record<K, T extends { [x: string]: JSONValue } ? JSONValue : unknown> {
  return k in o;
}

type SourceContributorField<Type = SourceContributor> = Type extends unknown ? keyof Type : never;

function getFields(contributor: SourceContributor): Array<SourceContributorField> {
  const { type } = contributor;
  switch (type) {
    case "person":
      return enumerate<keyof SourcePerson>()(
        "role",
        "type",
        "suffix",
        "family",
        "particle",
        "given",
        "initials",
        "screenName",
        "title",
      );
    case "organization":
      return enumerate<keyof SourceOrganization>()("role", "type", "name", "screenName");
    default:
      throw new UnreachableCaseError(type);
  }
}

export function isEmptyContributor(
  contributor: SourceContributor,
  ignoreFields: Array<SourceContributorField> = ["role", "type"],
): boolean {
  return !Object.entries(contributor)
    .filter(([key]) => {
      const field = key as SourceContributorField;
      const fields = getFields(contributor);
      return !ignoreFields.includes(field) && fields.includes(field);
    })
    .some(([, value]) => Boolean(value));
}

export function oneOf<T extends Array<string> | ReadonlyArray<string>>(
  expected: T,
  msg?: string | ((expected: T) => string),
) {
  const error = typeof msg === "string" ? `Invalid ${msg}, expected one of ${expected}` : msg?.(expected);
  return picklist(expected, error);
}

export const locale = oneOf(Locales, "Locale");
export const domain = oneOf(Domains, "Domain");
export const scribbrEnv = oneOf(ScribbrEnvs, "env");
export function isValidDate(
  day: number | null | undefined,
  month: number | null | undefined,
  year: number | null | undefined,
) {
  if (year == null || month == null || day == null) {
    // do not validate if the date is not complete
    return true;
  }

  const monthLengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (year % 4 === 0) {
    monthLengths[1] = 29;
  }
  const monthLength = monthLengths[month - 1];
  return monthLength && day <= monthLength;
}

export function isValidSource(source: Source): boolean {
  const { success } = schemas.source.safeParse(source);
  return success;
}

export function isSource(source: unknown): boolean {
  if (!isObject(source) || !hasProperty("data", source)) {
    return false;
  }

  if (!hasProperty("id", source) || !isID(source.id)) {
    return false;
  }

  if (!isObject(source.data)) {
    return false;
  }

  if (
    !hasProperty("type", source.data) ||
    typeof source.data.type !== "string" ||
    !isSourceType(source.data.type)
  ) {
    return false;
  }

  return true;
}

export function isValidContributor(contributor: SourceContributor): boolean {
  const schema = contributor.type === "person" ? schemas.person : schemas.organization;
  const { success } = schema.safeParse(contributor);
  return success;
}
