import {
  Locale,
  Locales,
  FontSize,
  FontSizes,
  Font,
  Fonts,
  SourceType,
  SourceTypes,
  Domain,
  Domains,
} from "@cgs/types";

export function isSourceType(value: unknown): value is SourceType {
  return SourceTypes.some((sourceType) => sourceType === value);
}

export function isLocale(value: string | undefined): value is Locale {
  return Locales.includes(value as Locale);
}

export function isDomain(value: unknown): value is Domain {
  return Domains.includes(value as Domain);
}

export function isFontSize(value: string | number | undefined): value is FontSize {
  return FontSizes.includes(Number(value));
}

export function isFont(value: string | undefined): value is Font {
  return Fonts.includes(value as Font);
}
