import classNames from "classnames";

export type LineProps = React.HTMLAttributes<HTMLDivElement> & {
  size?: "sm" | "md" | "lg";
};

const DEFAULT_CLASSES = "animate-pulse bg-navy-blue-4 rounded-sm";

const sizeMap = {
  sm: "h-2.5",
  md: "h-3",
  lg: "h-3.5",
};

export const Line = ({ size = "md", children, ...props }: LineProps) => {
  return (
    <div {...props} className={classNames(DEFAULT_CLASSES, sizeMap[size], props.className)}>
      {children}
    </div>
  );
};
