const countryNames: Record<Locale, CountryNames> = {
  "en-US": english,
  "nl-NL": dutch,
  "de-DE": german,
  "fr-FR": french,
  "es-ES": spanish,
};

export function getCountryNames(locale: Locale) {
  return countryNames[locale];
}

export function getCountryName(countryCode: CountryCode, locale: Locale) {
  return countryNames[locale][countryCode];
}

export function isCountryCode(value: string): value is CountryCode {
  return CountryCodes.includes(value as CountryCode);
}
