import { Checkbox, Tooltip } from "@cgs/ui";
import { HistoryEntry } from "../../common/types";

export const HistoryEntryListItem = ({
  onToggleSelect,
  onSetViewedEntry,
  isSelected,
  ...entry
}: HistoryEntry & {
  onToggleSelect: (id: HistoryEntry["id"], checked: boolean) => void;
  isSelected: boolean;
  onSetViewedEntry: () => void;
}) => {
  const timestamp = new Date(entry.timestamp);
  const { title, url } = entry.source.data;
  return (
    <div className="flex flex-row items-center gap-x-3">
      <div>
        <Checkbox
          size="sm"
          checked={isSelected}
          onCheckedChange={(state) => {
            onToggleSelect(entry.id, state === "indeterminate" ? false : state);
          }}
        />
      </div>
      <button className="flex min-w-0 grow flex-row gap-x-3 text-start" onClick={onSetViewedEntry}>
        <Tooltip.Root>
          <Tooltip.Trigger asChild>
            <p className="text-sm tabular-nums leading-5 text-navy-blue-11 hover:cursor-pointer">
              {timestamp.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
            </p>
          </Tooltip.Trigger>
          <Tooltip.Content>{timestamp.toLocaleDateString()}</Tooltip.Content>
        </Tooltip.Root>
        <div className="flex min-w-0 grow flex-row gap-x-4 hover:cursor-pointer">
          <div className="w-2/3 min-w-0 text-sm leading-5 text-navy-blue-12">
            <Tooltip.Root>
              <Tooltip.Trigger asChild>
                <p className="truncate">{title}</p>
              </Tooltip.Trigger>
              <Tooltip.Content>{title}</Tooltip.Content>
            </Tooltip.Root>
          </div>
          <div className="w-1/3 min-w-0 text-sm leading-5 text-navy-blue-11">
            <Tooltip.Root>
              <Tooltip.Trigger asChild>
                <div className="truncate">{url && new URL(url).host}</div>
              </Tooltip.Trigger>
              <Tooltip.Content>{url}</Tooltip.Content>
            </Tooltip.Root>
          </div>
        </div>
      </button>
    </div>
  );
};
