import { ActionButtons as ActionButtonsComponent, ActionButtons, Icon, Skeleton } from "@cgs/ui";
import { camelCase, capitalize, doiToURL, extractDoiCode, isUrl } from "@cgs/utils";
import { useTranslation } from "react-i18next";
import { Source } from "@cgs/types";
import { sendMessage } from "../../common/messaging";

export const Header = ({
  source,
  showUrlActionButton = false,
  onEnterSourceEditMode,
  onAddToList,
}: {
  source?: Source;
  showUrlActionButton?: boolean;
  onEnterSourceEditMode: (source?: Source) => void;
  onAddToList: () => void;
}) => {
  const { t } = useTranslation();
  const title = source?.data.title || source?.data.description || source?.data.content;

  return (
    <header className="flex flex-col gap-y-6 p-6">
      <div>
        <h3 className="truncate font-semibold">{title ?? <Skeleton className="my-1" />} </h3>
        <div className="truncate text-sm text-navy-blue-11">
          {source?.data.type ? (
            capitalize(t(`sourceTypes.${camelCase(source.data.type)}`))
          ) : (
            <Skeleton className="my-[3px] w-1/4" />
          )}
        </div>
      </div>
      <ActionButtons.Root>
        <ActionButtons.Item color="orange" onClick={onAddToList}>
          {t("homePage.addToList")}
        </ActionButtons.Item>
        <ActionButtonsComponent.Item onClick={() => onEnterSourceEditMode(source)}>
          {capitalize(t("general.edit"))}
        </ActionButtonsComponent.Item>
        {source?.data.doi && (
          <ActionButtons.Item
            endIcon={Icon.ArrowUpRight}
            tooltip={extractDoiCode(source.data.doi)}
            href={doiToURL(source.data.doi)}
            logEvent={async () =>
              await sendMessage({
                type: "logEvent",
                event: {
                  name: "Citation Generator Source External Link Clicked",
                  data: {
                    type: "doi",
                    location: "Header",
                  },
                },
              })
            }
          >
            {t("general.doi")}
          </ActionButtons.Item>
        )}
        {isUrl(source?.data.pdfUrl) && (
          <ActionButtons.Item
            startIcon={Icon.CloudArrowDown}
            tooltip={source.data.pdfUrl}
            href={source.data.pdfUrl}
            logEvent={async () =>
              await sendMessage({
                type: "logEvent",
                event: {
                  name: "Citation Generator Source External Link Clicked",
                  data: { type: "pdf", location: "Header" },
                },
              })
            }
          >
            {t("general.pdf")}
          </ActionButtons.Item>
        )}
        {showUrlActionButton && isUrl(source?.data.url) && (
          <ActionButtons.Item
            endIcon={Icon.ArrowUpRight}
            tooltip={source.data.url}
            href={source.data.url}
            logEvent={async () =>
              await sendMessage({
                type: "logEvent",
                event: {
                  name: "Citation Generator Source External Link Clicked",
                  data: { type: "url", location: "Header" },
                },
              })
            }
          >
            {t("general.url")}
          </ActionButtons.Item>
        )}
      </ActionButtons.Root>
    </header>
  );
};
