import * as TabsPrimitive from "@radix-ui/react-tabs";
import classNames from "classnames";
import { forwardRef } from "react";

export const Root = TabsPrimitive.Root;

export const List = forwardRef<
  React.ElementRef<typeof TabsPrimitive.List>,
  React.ComponentProps<typeof TabsPrimitive.List> & { bordered?: boolean; alignOffset?: number }
>(function List(props, forwardedRef) {
  const { className, bordered, alignOffset, children, ...otherProps } = props;
  return (
    <TabsPrimitive.List
      {...otherProps}
      ref={forwardedRef}
      className={classNames("flex w-full snap-x snap-mandatory space-x-1 overflow-x-auto", className)}
      style={{
        paddingLeft: alignOffset,
        paddingRight: alignOffset,
        scrollPaddingLeft: alignOffset,
        scrollPaddingRight: alignOffset,
        boxShadow: bordered ? "inset 0 -1px 0 0 #DEE0E8" : undefined,
      }}
    >
      {children}
    </TabsPrimitive.List>
  );
});

export const Trigger = forwardRef<
  React.ElementRef<typeof TabsPrimitive.Trigger>,
  React.ComponentProps<typeof TabsPrimitive.Trigger>
>(function Trigger(props, forwardedRef) {
  const { className, children, ...otherProps } = props;
  return (
    <TabsPrimitive.Trigger
      {...otherProps}
      ref={forwardedRef}
      className={classNames(
        "shrink-0 snap-start border-b-2 border-transparent pb-1.5 text-sm font-semibold text-navy-blue-11 hover:text-navy-blue-12 state-active:border-blue-9 state-active:text-blue-9 data-disabled:text-navy-blue-7",
        className,
        { group: !otherProps.disabled },
      )}
    >
      <div className="rounded-md px-3 py-1.5 group-hover:bg-navy-blue-4 group-hover:text-navy-blue-12">
        {children}
      </div>
    </TabsPrimitive.Trigger>
  );
});

export const Content = TabsPrimitive.Content;
