import { camelCase, capitalize } from "@cgs/autocite-component/src/utils";
import { MAX_WORKS } from "@cgs/utils";
import { useTranslation } from "react-i18next";
import { Source } from "@cgs/types";
import { sendMessage } from "../../../common/messaging";
import { getContributorName } from "@cgs/utils/web/getContributors";

type CitedByWorksSectionProps = {
  sources: Array<Source>;
};
export const CitedByWorksSection = ({ sources }: CitedByWorksSectionProps) => {
  const { t } = useTranslation();

  const handleLinkClick = async () => {
    await sendMessage({
      type: "logEvent",
      event: { name: "Citation Generator Cited By Work Clicked" },
    });
  };

  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-col gap-y-6">
        <ul className="flex flex-col gap-y-4">
          {sources.map(({ id, data: { url, title, issued, type, contributors, publisher } }) => (
            <li className="truncate" key={id}>
              <a
                className="truncate text-sm hover:underline"
                href={url}
                target="_blank"
                rel="noreferrer"
                onClick={handleLinkClick}
              >
                {title}
              </a>
              <div className="space-x-1 truncate text-xs text-navy-blue-11">
                <span>{capitalize(t(`sourceTypes.${camelCase(type)}`))}</span>
                <span className="last-of-type:hidden">&middot;</span>
                {issued?.year && (
                  <>
                    <span>{issued.year}</span>
                    <span className="last-of-type:hidden">&middot;</span>
                  </>
                )}

                {contributors && (
                  <>
                    <span>{contributors.map((contributor) => getContributorName(contributor)).join(", ")}</span>
                    <span className="last-of-type:hidden">&middot;</span>
                  </>
                )}

                {publisher && (
                  <>
                    <span>{publisher}</span>
                    <span className="last-of-type:hidden">&middot;</span>
                  </>
                )}
              </div>
            </li>
          ))}
        </ul>
        {sources && sources.length > MAX_WORKS && (
          <small className="text-center text-sm text-navy-blue-11">
            {t("sourceSidebar.citedByWorksSection.maxWorks", { maxWorks: MAX_WORKS })}
          </small>
        )}
      </div>
    </div>
  );
};
