import * as ToastPrimitive from "@radix-ui/react-toast";
import { Icon } from "@cgs/ui";
import { newID } from "@cgs/utils";
import { createContext, useCallback, useContext, useMemo, useState } from "react";

type Toast = {
  message: string | React.ReactNode;
  type: "success" | "error";
  id: ID;
};

type ToastContext = (message: Toast["message"], type?: Toast["type"]) => void;
export type ToastArguments = Parameters<ToastContext>;
const ToastContext = createContext<ToastContext | null>(null);

export function useToast() {
  const context = useContext(ToastContext);
  if (context == null) {
    // return noop instead of throwing when not in provider
    return (_m: Toast["message"], _t?: Toast["type"]) => {};
  }
  return context;
}

function getIcon(type: Toast["type"] = "success") {
  switch (type) {
    case "success":
      return <Icon.CircleCheck className="h-5 fill-green-9" />;
    case "error":
      return <Icon.CircleExclamation className="h-5 fill-red-9" />;
  }
}

export function ToastProvider(props: { children: React.ReactNode }) {
  const { children } = props;
  const [toasts, setToasts] = useState<Array<Toast>>([]);

  const notify = useCallback(
    (message: Toast["message"], type: Toast["type"] = "success") => {
      const id = newID();
      setToasts((toasts) => [...toasts, { message, type, id }]);
    },
    [setToasts],
  );

  const value = useMemo(() => notify, [notify]);

  return (
    <ToastContext.Provider value={value}>
      {children}
      <ToastPrimitive.Provider label="bla">
        {toasts.map((toast) => {
          return (
            <ToastPrimitive.Root
              key={toast.id}
              className="align-center pointer-events-auto flex max-w-sm items-center space-x-4 rounded-lg bg-white px-4 py-3 shadow-xl state-open:animate-slide-in-top state-closed:animate-fade-out"
            >
              {getIcon(toast.type)}
              <ToastPrimitive.Title className="flex-1">{toast.message}</ToastPrimitive.Title>
            </ToastPrimitive.Root>
          );
        })}
        <ToastPrimitive.Viewport className="pointer-events-none fixed left-4 right-4 top-4 z-front flex flex-col items-center space-y-3" />
      </ToastPrimitive.Provider>
    </ToastContext.Provider>
  );
}
