// https://stackoverflow.com/questions/10306690/what-is-a-regular-expression-which-will-match-a-valid-domain-name-without-a-subd/#answer-41193739
const DOMAIN_RGX = /^(?=.{1,253}\.?$)(?:(?!-|[^.]+_)[A-Za-z0-9-_]{0,63}(?:\.|$)){2,}$/;

export function isUrl(s: unknown, protocols = ["http:", "https:"]): s is string {
  if (typeof s !== "string" || !s.includes(".")) {
    return false;
  }

  // strip trailing slashes
  const stripped = s.trim().replace(/(\/)+$/, "");

  const parsed = parseUrl(stripped);

  if (parsed == null) {
    return false;
  }

  return protocols.includes(parsed.protocol) && DOMAIN_RGX.test(parsed.hostname);
}

export const isS3Url = (s: string) => isUrl(s, ["s3:"]);

export function parseUrl(s: string) {
  try {
    return new URL(/^.*?:\/\//.test(s) ? s : `https://${s}`);
  } catch (e) {
    return undefined;
  }
}

export function getHostname(url: string): string | undefined {
  const parsed = parseUrl(url) || parseUrl(`https://${url}`);
  return parsed?.hostname;
}

export function extractUrl(s: string, protocols = ["http:", "https:"]) {
  const rgx = new RegExp(`(${protocols.join("|")})//[^\\s]+`, "i");
  const url = s.match(rgx);
  return url ? url[0] : undefined;
}
