import { CountrySelect } from "../CountrySelect";
import { SourcePlace } from "@cgs/types";
import * as Form from "../../../Form";
import { useSourceFormContext } from "../../SourceForm";
import { TextInput } from "../../../TextInput";
import { useTranslation } from "react-i18next";

export const PlaceInput = ({
  value,
  onValueChange,
  idPrefix,
}: {
  value?: SourcePlace;
  onValueChange: (value: SourcePlace) => void;
  idPrefix: string;
}): JSX.Element | null => {
  const { t } = useTranslation();
  const { scopedTKey } = useSourceFormContext();

  const handleCountryChange = (country: string) => {
    onValueChange({ ...value, country });
  };
  const handleRegionChange = (region: string) => {
    onValueChange({ ...value, region });
  };
  const handleLocalityChange = (locality: string) => {
    onValueChange({ ...value, locality });
  };

  return (
    <fieldset className="space-y-4">
      <Form.Element>
        <label className="text-sm">{t(scopedTKey("placeInput.country.label"))}</label>
        <CountrySelect value={value?.country || ""} onValueChange={handleCountryChange} />
      </Form.Element>
      <Form.Element>
        <label className="text-sm" htmlFor={`${idPrefix}.region`}>
          {t(scopedTKey("placeInput.region.label"))}
        </label>
        <TextInput
          value={value?.region || ""}
          onChange={(event) => handleRegionChange(event.currentTarget.value)}
          id={`${idPrefix}-region`}
        />
      </Form.Element>
      <Form.Element>
        <label className="text-sm" htmlFor={`${idPrefix}.locality`}>
          {t(scopedTKey("placeInput.locality.label"))}
        </label>
        <TextInput
          value={value?.locality || ""}
          onChange={(event) => handleLocalityChange(event.currentTarget.value)}
          id={`${idPrefix}-locality`}
        />
      </Form.Element>
    </fieldset>
  );
};
