import { useTranslation } from "react-i18next";
import {
  BibliographyEntry as BibEntry,
  CitationStyleOptions,
  CopyTrigger,
  Locale,
  defaultFont,
  defaultFontSize,
} from "@cgs/types";
import { BibliographyEntry } from "../BibliographyEntry";
import { bibliographyToClipboardItem, writeToClipboard } from "@cgs/utils/common";
import { getCitationStyleTranslation } from "../../common/utils";
import { useToast } from "../Toast";
import { CitationStyleSelect } from "../CitationStyleSelect";
import { useSettingsContext } from "../../settings/SettingsContext";
import { sendMessage } from "../../common/messaging";
import { CitationStyle } from "@cgs/citation-engine/types";

export const BibliographyEntrySection = ({
  citationStyleOptions,
  bibliographyEntry,
  locale,
  showCitationStyleSelect = true,
  onCopy,
  onCitationStyleChange,
}: {
  bibliographyEntry: BibEntry;
  citationStyleOptions: CitationStyleOptions;
  locale: Locale;
  onCitationStyleChange: (style: CitationStyle) => void;
  showCitationStyleSelect?: boolean;
  onCopy?: (success: boolean) => void;
}) => {
  const { settings, saveSettings } = useSettingsContext();

  const { t } = useTranslation();
  const toast = useToast();

  if (!bibliographyEntry || !citationStyleOptions) {
    return null;
  }

  const copyBibliography = async (trigger: CopyTrigger) => {
    if (trigger === "selection") {
      await sendMessage({
        type: "logEvent",
        event: {
          name: "Citation Generator Bibliography Entry Copied",
          data: {
            citation_style: settings.citationStyle[0],
            citation_style_variation: settings.citationStyle[1],
            location: "BibliographyEntrySection",
            trigger,
          },
        },
      });
    }

    await writeToClipboard(
      bibliographyToClipboardItem(
        [
          {
            text: bibliographyEntry.text,
            source: bibliographyEntry.source,
          },
        ],
        {
          font: defaultFont,
          fontSize: defaultFontSize,
        },
        citationStyleOptions,
      ),
    );

    onCopy?.(true);
    toast(t("clipboard.copied"));
    await sendMessage({
      type: "logEvent",
      event: {
        name: "Citation Generator Bibliography Entry Copied",
        data: {
          citation_style: settings.citationStyle[0],
          citation_style_variation: settings.citationStyle[1],
          location: "BibliographyEntrySection",
          trigger,
        },
      },
    });
  };

  const title = citationStyleOptions?.bibliographyEntryName[locale];

  return (
    <div className="space-y-2">
      <div className="flex flex-row items-center justify-between">
        <h2 className="text-sm font-semibold text-navy-blue-11">{title}</h2>
        {showCitationStyleSelect && (
          <CitationStyleSelect
            citationStyle={settings.citationStyle}
            onCitationStyleChange={(citationStyle) => {
              saveSettings({ citationStyle });
              onCitationStyleChange(citationStyle);
            }}
            size="sm"
            contentAlign="end"
            variant="ghost"
          >
            {getCitationStyleTranslation(settings.citationStyle, t, "short")}
          </CitationStyleSelect>
        )}
      </div>

      <BibliographyEntry
        bibliographyEntry={bibliographyEntry}
        onCopyBibliography={copyBibliography}
        citationStyleOptions={citationStyleOptions}
      />
    </div>
  );
};
