import { useHistory } from "../components/History/useHistory";
import { History } from "../components/History";
import { HISTORY_LIMIT } from "../common/constants";
import { Icon } from "@cgs/ui";
import classNames from "classnames";
import { Source } from "@cgs/types";

type HistoryTabProps = {
  onEnterSourceEditMode: (source?: Source) => void;
  onAddToList: () => void;
} & ReturnType<typeof useHistory>;
export const HistoryTab = ({
  onEnterSourceEditMode,
  viewedEntry,
  onCloseViewEntry,
  onAddToList,
  ...props
}: HistoryTabProps) => {
  return (
    <>
      <StorageSizeBanner totalHistories={props.totalHistories} />
      {viewedEntry ? (
        <History.ViewEntry
          {...viewedEntry}
          onCloseViewEntry={onCloseViewEntry}
          onEnterSourceEditMode={onEnterSourceEditMode}
          onAddToList={onAddToList}
        />
      ) : (
        <History.List {...props} />
      )}
    </>
  );
};

const StorageSizeBanner = ({ totalHistories }: { totalHistories: number }) => {
  if (totalHistories < HISTORY_LIMIT - 100) {
    return null;
  }
  const type = totalHistories < HISTORY_LIMIT ? "WARNING" : "ERROR";
  const [message, classes] =
    type === "WARNING"
      ? ["You have used 90% of your history limit", "border-yellow bg-yellow-3 text-yellow-12"]
      : [
          "You have used all of your history limit. New citattions will replace your oldest ones",
          "border-red bg-red-3 text-red-10",
        ];

  return (
    <div className={classNames("border-y px-3 py-2 text-xs", classes)}>
      <div className="align-center flex flex-row justify-center gap-2">
        <Icon.CircleExclamation
          className={classNames("h-4", type === "WARNING" ? "fill-yellow-10" : "fill-red-10")}
        />
        <div>{message}</div>
      </div>
    </div>
  );
};
