import { SourceContributor } from "@cgs/types";
import { UnreachableCaseError } from "../common";

export const getContributorName = (contributor: SourceContributor): string | undefined => {
  const { type } = contributor;
  switch (type) {
    case "person":
      return contributor.family || contributor.given || contributor.screenName;
    case "organization":
      return contributor.name || contributor.screenName;
    default: {
      throw new UnreachableCaseError(type);
    }
  }
};
