import { Icon, Skeleton } from "@cgs/ui";
import { BibliographyEntrySection } from "../BibliographyEntrySection";
import { CitationExamples } from "../CitationExamples";
import { BibliographyEntry, Citation, CitationStyleOptions, Locale } from "@cgs/types";
import { useState } from "react";
import { CitationStyle } from "@cgs/citation-engine/types";

type CiteSectionProps = {
  locale: Locale;
  onCopy?: (success: boolean) => void;
  citation?: Citation;
  bibEntry?: BibliographyEntry;
  options?: CitationStyleOptions;
  showCitationStyleSelect?: boolean;
  onCitationStyleChange: (style: CitationStyle) => void;
};

export const CiteSection = ({
  locale,
  onCopy,
  citation,
  bibEntry,
  options,
  showCitationStyleSelect = true,
  onCitationStyleChange,
}: CiteSectionProps) => {
  const [showLongRunningJobBanner, setShowLongRunningJobBanner] = useState(false);
  setTimeout(() => setShowLongRunningJobBanner(true), 5000);
  if (citation === undefined || bibEntry === undefined || options === undefined) {
    return (
      <Skeleton className="my-2 space-y-4">
        {showLongRunningJobBanner && <LongRunningCiteJobBanner />}
        <Skeleton.Line className="w-1/3" />
        <Skeleton className="space-y-2">
          <Skeleton.Line />
          <Skeleton.Line />
        </Skeleton>
        <Skeleton className="flex gap-2">
          <Skeleton.Line className="w-1/4" />
          <Skeleton.Line className="w-1/2" />
        </Skeleton>
      </Skeleton>
    );
  }

  return (
    <div className="space-y-5">
      <BibliographyEntrySection
        locale={locale}
        bibliographyEntry={bibEntry}
        citationStyleOptions={options}
        showCitationStyleSelect={showCitationStyleSelect}
        onCopy={onCopy}
        onCitationStyleChange={onCitationStyleChange}
      />
      {citation && <CitationExamples citation={citation} onCopy={onCopy} />}
    </div>
  );
};

const LongRunningCiteJobBanner = () => (
  <div className={"text-xs text-navy-blue-10"}>
    <div className="align-center flex flex-row justify-start gap-2">
      <Icon.CircleExclamation className={"h-4 fill-navy-blue-8"} />
      <div>Note: requests can take up to 30 seconds to complete.</div>
    </div>
  </div>
);
