import { Fieldset } from "../components/Fieldset";
import { useSourceFormContext } from "../SourceForm";
import * as Form from "../../Form";
import { TextInput } from "../../TextInput";
import { PlaceInput } from "../components/PlaceInput";
import { Control } from "../types";
import { useTranslation } from "react-i18next";

export const Archive = ({ control }: { control: Control }) => {
  const { t } = useTranslation();
  const { scopedTKey, config } = useSourceFormContext();
  const archive = Form.useFormField(control, "archive");
  const archivePlace = Form.useFormField(control, "archivePlace");

  return (
    <Fieldset id="archive" fields={["archive", "archivePlace"]} onLegendClick={archive.focus}>
      {config.fields.archive && (
        <Form.Element issue={archive.issue}>
          <label className="text-sm" htmlFor={archive.id}>
            {t(scopedTKey("archive.label"))}
          </label>
          <TextInput
            value={archive.value}
            onValueChange={archive.update}
            invalid={!!archive.issue}
            id={archive.id}
            ref={archive.ref}
          />
        </Form.Element>
      )}
      {config.fields.archivePlace && (
        <Form.Element issue={archivePlace.issue}>
          <PlaceInput onValueChange={archivePlace.update} value={archivePlace.value} idPrefix="archive-place" />
        </Form.Element>
      )}
    </Fieldset>
  );
};
