/** Gets all dates in a month. */
export const getDatesInMonth = (date: Date): Date[] => {
  const month = date.getMonth();
  const year = date.getFullYear();

  return new Array(31)
    .fill("")
    .map((_, i) => new Date(year, month, i + 1))
    .filter((v) => v.getMonth() === month);
};

/** Gets the name of a month .*/
export const formatMonth = (
  monthIndex: number,
  locales: string | string[],
  format: Intl.DateTimeFormatOptions["month"] = "long",
) => {
  const date = new Date(2022, monthIndex, 1);
  return date.toLocaleString(locales, {
    month: format,
  });
};

/** Months in a year, zero-based. */
export const months = Array(12)
  .fill("")
  .map((_, i) => i);
