import * as clipboard from "clipboard-polyfill";
import { BibliographyEntry, CitationStyleOptions, Font } from "@cgs/types";
import { getAnnotationStyle, splitParagraphs } from ".";

export type ClipboardData = [type: string, content: string];

export async function writeToClipboard(data: Array<ClipboardData>) {
  const clipboardItem = new clipboard.ClipboardItem(
    data.reduce(
      (acc, [type, content]) => {
        acc[type] = new Blob([content], { type });
        return acc;
      },
      {} as Record<string, Blob>,
    ),
  );

  await clipboard.write([clipboardItem]);
}

export function bibliographyToClipboardItem(
  entries: BibliographyEntry[],
  settings: { font: Font; fontSize: number },
  citationStyleOptions: CitationStyleOptions,
): Array<ClipboardData> {
  const plainTextParts: Array<string> = [];
  const wrapper = document.createElement("div");

  wrapper.style.marginTop = "0";
  wrapper.style.marginBottom = "0";

  wrapper.style.marginLeft = `-${citationStyleOptions.bibliographyStyle.marginLeft}`;

  for (const entry of entries) {
    if (!entry.text) {
      continue;
    }

    const p = document.createElement("p");
    p.innerHTML = entry.text;

    p.style.marginTop = "0";
    p.style.marginBottom = "0";
    p.style.fontSize = `${settings.fontSize}pt`;
    p.style.textIndent = citationStyleOptions.bibliographyStyle.textIndent || "0";
    p.style.lineHeight = citationStyleOptions.bibliographyStyle.lineHeight;
    p.style.fontFamily = settings.font;
    p.style.tabSize = citationStyleOptions.bibliographyStyle.tabSize;

    p.style.marginLeft = citationStyleOptions.bibliographyStyle.marginLeft;

    wrapper.appendChild(p);
    plainTextParts.push(p.textContent || p.innerText || "");

    if (entry.source.data.note) {
      const paragraphs = splitParagraphs(entry.source.data.note);
      const div = document.createElement("div");

      div.style.marginTop = "0";
      div.style.marginBottom = "0";

      div.style.marginLeft = citationStyleOptions.bibliographyStyle.marginLeft;

      for (const [index, text] of paragraphs.entries()) {
        const p = document.createElement("p");
        p.innerHTML = text;

        const { marginLeft, textIndent } = getAnnotationStyle(
          citationStyleOptions,
          index === 0,
          paragraphs.length > 1,
        );

        p.style.marginTop = "0";
        p.style.marginBottom = "0";
        p.style.fontSize = `${settings.fontSize}pt`;
        p.style.textIndent = textIndent || "0";
        p.style.lineHeight = citationStyleOptions.bibliographyStyle.lineHeight;
        p.style.fontFamily = settings.font;
        p.style.tabSize = citationStyleOptions.bibliographyStyle.tabSize;

        p.style.marginLeft = marginLeft;

        div.appendChild(p);
        plainTextParts.push(p.textContent || p.innerText || "");
      }

      wrapper.appendChild(div);
    }
  }

  return [
    ["text/html", wrapper.outerHTML],
    ["text/plain", plainTextParts.join(" ")],
  ];
}

export function citationToClipboardItem(citation: string): Array<ClipboardData> {
  return [
    ["text/html", citation],
    ["text/plain", new DOMParser().parseFromString(citation, "text/html").documentElement.textContent || citation],
  ];
}
