import { Skeleton, TextInputProps } from "@cgs/ui";
import { ActionFooter } from "./ActionFooter";
import { useHistory } from "./useHistory";
import { ListGroup } from "./ListGroup";
import { HistoryEntry } from "../../common/types";
import { sendMessage } from "../../common/messaging";

type Props = Omit<ReturnType<typeof useHistory>, "viewedEntry" | "onCloseViewEntry">;

export const List = ({
  isLoading,
  totalHistories,
  filterString,
  onFilterStringChange,
  selectedHistories,
  dailyHistoryCollections,
  onDeselectAllHistoryEntries,
  onSelectAllHistoryEntries,
  onDeleteHistoryEntries,
  onToggleHistoryEntry,
  onViewEntry,
}: Props) => {
  const listGroupProps = {
    selectedHistories,
    onToggleHistoryEntry,
    onViewEntry: async (entry: HistoryEntry) => {
      onViewEntry(entry);
      await sendMessage({
        type: "logEvent",
        event: {
          name: "Citation Generator Browser Extension History Entry Viewed",
          data: {
            url: entry.id,
            lastCitedTimestamp: entry.timestamp,
          },
        },
      });
    },
  };

  const footerProps = {
    totalSelected: selectedHistories.length,
    onClose: onDeselectAllHistoryEntries,
    onSelectAll: onSelectAllHistoryEntries,
    onDeleteSelected: async () => {
      onDeleteHistoryEntries(selectedHistories);
      await sendMessage({
        type: "logEvent",
        event: {
          name: "Citation Generator Browser Extension History Entries Deleted",
          data: {
            count: selectedHistories.length,
          },
        },
      });
    },
  };

  return (
    <div className="flex h-full flex-col">
      <div className="px-5 py-3">
        <SearchFilterInput
          disabled={isLoading || totalHistories === 0}
          value={filterString}
          onChange={(e) => onFilterStringChange(e.target.value)}
          type="search"
          placeholder="Search history"
        />
      </div>
      <div className="flex grow flex-col gap-6 px-5 py-4">
        {totalHistories === 0 && (
          <div className="text-center text-xs text-navy-blue-11">
            No history yet. Begin citing sources to manage your histories
          </div>
        )}
        {isLoading ? (
          <Skeleton.Lines count={15} className="space-y-3" />
        ) : (
          Object.entries(dailyHistoryCollections).map(([date, entries], i) => (
            <ListGroup key={`${date}-${i}`} date={new Date(date)} entries={entries} {...listGroupProps} />
          ))
        )}
      </div>
      {footerProps.totalSelected > 0 && <ActionFooter {...footerProps} />}
    </div>
  );
};

const SearchFilterInput = (props: TextInputProps) => {
  return (
    <input
      {...props}
      className="h-9 w-full rounded-full bg-navy-blue-3 px-5 py-3 placeholder:text-navy-blue-8 hover:border-navy-blue-8 focus:border-blue-9 focus:outline-2 focus:outline-blue-9 disabled:opacity-40"
    />
  );
};
