import { useSourceFormContext } from "../SourceForm";
import { Checkbox } from "../../Checkbox";
import * as Form from "../../Form";
import { Fieldset } from "../components/Fieldset";
import { TextInput } from "../../TextInput";
import { Control } from "../types";
import { ArrowRight } from "../../Icon";
import { useTranslation } from "react-i18next";

export const Composed = ({ control }: { control: Control }) => {
  const { t } = useTranslation();
  const { scopedTKey } = useSourceFormContext();
  const { value, update } = Form.useFormField(control, "composed");
  const year = Form.useFormField(control, "composed.year");
  const startYear = Form.useFormField(control, "composed.start.year");
  const endYear = Form.useFormField(control, "composed.start.year");

  const isRange = value != null && "start" in value;
  const start =
    (value && "start" in value && value.start?.year) || (value && "year" in value && value.year) || undefined;
  const end =
    (value && "end" in value && value.end?.year) || (value && "year" in value && value.year) || undefined;

  const handleStartChange = (newValue: string) => {
    const newValueAsNumber = parseInt(newValue);
    const newYear = !isNaN(newValueAsNumber) ? newValueAsNumber : undefined;
    update(isRange ? { ...value, start: { year: newYear } } : { year: newYear });
  };
  const handleEndChange = (newValue: string) => {
    const newValueAsNumber = parseInt(newValue);
    const newYear = !isNaN(newValueAsNumber) ? newValueAsNumber : undefined;
    update(isRange ? { ...value, end: { year: newYear } } : { year: newYear });
  };
  const handleIsRangeChange = () => {
    update(isRange ? { year: start } : { start: { year: start }, end: { year: end } });
  };

  return (
    <Fieldset id="composed" fields={["composed"]} onLegendClick={isRange ? startYear.focus : year.focus}>
      <div className="flex items-center space-x-4">
        <div className="flex flex-1 items-center space-x-4">
          <div className="flex-1">
            <Form.Element issue={isRange ? startYear.issue : year.issue}>
              <TextInput
                value={start || ""}
                onValueChange={handleStartChange}
                aria-label={t(scopedTKey(isRange ? "composed.start.year.label" : "composed.year.label"))}
                invalid={!!(isRange ? startYear.issue : year.issue)}
                ref={isRange ? startYear.ref : year.ref}
                id={isRange ? startYear.id : year.id}
                type="number"
              />
            </Form.Element>
          </div>
          {isRange && (
            <>
              <ArrowRight className="h-text shrink-0 fill-navy-blue-11" />
              <div className="flex-1">
                <Form.Element issue={endYear.issue}>
                  <TextInput
                    value={end || ""}
                    onValueChange={handleEndChange}
                    aria-label={t(scopedTKey("composed.end.label"))}
                    invalid={!!endYear.issue}
                    ref={endYear.ref}
                    id={endYear.id}
                    type="number"
                  />
                </Form.Element>
              </div>
            </>
          )}
        </div>
        <label className="flex shrink-0 items-center space-x-2 text-sm">
          <Checkbox checked={isRange} size="sm" onCheckedChange={handleIsRangeChange} />
          <span>{t(scopedTKey("composed.range.label"))}</span>
        </label>
      </div>
    </Fieldset>
  );
};
