import { RelatedWorksSection, ReferencedWorksSection, CitedByWorksSection } from "./Tabs";
import { SegmentedButton, SkeletonTextList, Tooltip } from "@cgs/ui";
import { ComponentProps, ComponentType, ReactNode, useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { Message, OpenAlexWorks } from "../../common/types";
import { Source } from "@cgs/types";
import { sendMessage } from "../../common/messaging";

type Tab = {
  name: OpenAlexWorks;
  content: ReactNode;
};

type OtherWorksSectionProps = {
  doi: string;
};

export const OtherWorksSection = ({ doi }: OtherWorksSectionProps) => {
  const { t } = useTranslation();
  const [activeTab, setActiveTab] = useState<Tab["name"]>("citedBy");
  const [isLoading, setIsLoading] = useState(false);
  const [otherWorks, setOtherWorks] = useState<{
    [key in Tab["name"]]: {
      error?: string;
      sources?: Source[];
    };
  }>({
    citedBy: {
      error: undefined,
      sources: undefined,
    },
    referencedWorks: {
      error: undefined,
      sources: undefined,
    },
    relatedWorks: {
      error: undefined,
      sources: undefined,
    },
  });

  useEffect(() => {
    // If we already have a result, don't fetch again
    if (otherWorks[activeTab].sources || otherWorks[activeTab].error) {
      return;
    }
    (async () => {
      setIsLoading(true);
      const response: Message = await sendMessage({
        type: "otherWorks",
        doi,
        relation: activeTab,
      });
      switch (response.type) {
        case "otherWorksError":
          setOtherWorks((prevState) => ({
            ...prevState,
            [activeTab]: {
              error: response.error,
              sources: undefined,
            },
          }));
          break;
        case "otherWorksResponse":
          setOtherWorks((prevState) => ({
            ...prevState,
            [activeTab]: {
              error: undefined,
              sources: response.sources,
            },
          }));
          break;
        default:
          break;
      }
      setIsLoading(false);
    })();
  }, [activeTab, doi, otherWorks]);

  const otherWorksTabs: Array<Tab> = useMemo(() => {
    const renderOtherTabContent = (
      tab: Tab["name"],
      Content: ComponentType<
        ComponentProps<typeof CitedByWorksSection | typeof ReferencedWorksSection | typeof RelatedWorksSection>
      >,
    ) => {
      // If there is an error, show the error message
      if (otherWorks[tab].error) {
        return (
          <div className="text-md" role="alert">
            {otherWorks[tab].error}
          </div>
        );
      }
      // If the sources are not available yet or loading, show the skeleton
      const sources = otherWorks[tab].sources;
      if (!sources || isLoading) {
        return <SkeletonTextList />;
      }
      return <Content sources={sources} />;
    };

    return [
      {
        name: "citedBy",
        content: renderOtherTabContent("citedBy", CitedByWorksSection),
      },
      {
        name: "referencedWorks",
        content: renderOtherTabContent("referencedWorks", CitedByWorksSection),
      },
      {
        name: "relatedWorks",
        content: renderOtherTabContent("relatedWorks", CitedByWorksSection),
      },
    ];
  }, [isLoading, otherWorks]);

  const handleTabChange = (value: Tab["name"]) => {
    setActiveTab(value);
    chrome.runtime.sendMessage({
      type: "logEvent",
      event: {
        name: "Citation Generator Source Tab Clicked",
        data: {
          tab: value,
        },
      },
    });
  };

  const activeTabContent = otherWorksTabs.find((tab) => tab.name === activeTab)?.content;

  return (
    <div className="flex flex-col gap-y-4">
      <SegmentedButton.Root size="sm" value={activeTab} onValueChange={handleTabChange}>
        {otherWorksTabs.map(({ name }) => (
          <Tooltip.Root key={`trigger-${name}`} delayDuration={0}>
            <Tooltip.Trigger asChild>
              <SegmentedButton.Item
                data-state={name === activeTab ? "checked" : undefined}
                key={`trigger-${name}`}
                value={name}
              >
                {t(`otherWorksSection.${name}.title`)}
              </SegmentedButton.Item>
            </Tooltip.Trigger>
            {<Tooltip.Content>{t(`otherWorksSection.${name}.tooltip`)}</Tooltip.Content>}
          </Tooltip.Root>
        ))}
      </SegmentedButton.Root>
      {activeTabContent && <div>{activeTabContent}</div>}
    </div>
  );
};
