class MapEvent<V> extends Event {
  constructor(
    type: string,
    public readonly newValue: V | undefined,
  ) {
    super(type);
  }
}

export interface MapEventListener<V> {
  (event: MapEvent<V>): void;
}

export class ObservableMap<K extends string, V> extends Map<K, V> {
  // this instance var is possibly undefined during object construction,
  private eventTarget: EventTarget | undefined = new EventTarget();

  on(key: K, listener: MapEventListener<V>) {
    this.eventTarget?.addEventListener(key, listener as EventListener);
  }

  off(key: K, listener: MapEventListener<V>) {
    this.eventTarget?.removeEventListener(key, listener as EventListener);
  }

  set(key: K, value: V): this {
    super.set(key, value);
    this.eventTarget?.dispatchEvent(new MapEvent(key, value));
    return this;
  }

  delete(key: K): boolean {
    const result = super.delete(key);
    this.eventTarget?.dispatchEvent(new MapEvent(key, undefined));
    return result;
  }
}
